9fb1-605e4d04e8b3","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO CUARTO.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":226,"contenido_md5":"22ad000fced8c350fc7e51197b6b0083"},{"id":"ef6d3e97-6ad6-44e8-b657-52f4c54318e2","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO QUINTO.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":227,"contenido_md5":"6b5a620bd5d16dab4dbb693f088d9958"},{"id":"d574ce36-1a91-48f5-8bfd-0ce28b0e8103","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio TERCERO","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":228,"contenido_md5":"3cbc5fe738c9e47f43ad6dc563b36fb4"},{"id":"bbce4d22-15fc-4afb-8544-38b3d00c865f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO SEXTO.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":229,"contenido_md5":"64de539d1b0c32bb1cbc5cefb2d2c757"},{"id":"aeb089ab-04ef-4c9c-860e-ce2cbf77c947","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":230,"contenido_md5":"0f4562d949de2c12b337de91c9ed65dc"},{"id":"3c626412-3bcb-452d-a6bb-a5b6788060ef","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO OCTAVO.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":231,"contenido_md5":"3e4f111fe97d7b3581a2a92038e7b669"},{"id":"88e2a81e-a10a-4a97-99de-3941abccdd7f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio DÉCIMO NOVENO.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":232,"contenido_md5":"b03ec691e7495b98ecd9926ad6efc41c"},{"id":"f10bb70f-0076-48ef-85e3-7f88d6b60ad5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","identificador":"Transitorio VIGÉSIMO.","tipo_articulo":"transitorio","titulo_nombre":"MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"De las Sanciones","seccion_nombre":null,"orden":233,"contenido_md5":"7161876d462a4e2a58467e554397fb84"}],"after":[{"identificador":"Preámbulo","tipo_articulo":"preambulo","contenido":"LEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA\nTEXTO VIGENTE\nNueva Ley publicada en el Diario Oficial de la Federación el 20 de marzo de 2025\nAl margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Presidencia de la República.\nCLAUDIA SHEINBAUM PARDO , Presidenta de los Estados Unidos Mexicanos, a sus habitantes sabed:\nQue el Honorable Congreso de la Unión, se ha servido dirigirme el siguiente\nDECRETO\n\" EL CONGRESO GENERAL DE LOS ESTADOS UNIDOS MEXICANOS, DECRETA:\nSE EXPIDEN LA LEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA; LA LEY GENERAL DE\nPROTECCIÓN DE DATOS PERSONALES EN POSESIÓN DE SUJETOS OBLIGADOS; LA LEY FEDERAL DE PROTECCIÓN\nDE DATOS PERSONALES EN POSESIÓN DE LOS PARTICULARES; Y SE REFORMA EL ARTÍCULO 37, FRACCIÓN XV, DE\nLA LEY ORGÁNICA DE LA ADMINISTRACIÓN PÚBLICA FEDERAL\nArtículo Primero.-  Se  expide  la Ley General de Transparencia y Acceso a la Información Pública, para quedar\ncomo sigue:\nLEY GENERAL DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"id":"d79154ae-bb28-4bb9-87e1-94078136a2ea","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":0},{"identificador":"Artículo 1","tipo_articulo":"ordinario","contenido":"La presente Ley es reglamentaria del artículo 6o. de la Constitución Política de los Estados Unidos\nMexicanos, en materia de transparencia y acceso a la información pública y sus disposiciones son de orden público,\nde interés social y de observancia general en todo el territorio nacional, con el fin de garantizar el derecho humano al\nacceso a la información y promover la transparencia y rendición de cuentas.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo I Disposiciones Preliminares","seccion_nombre":null,"id":"b1bcab9d-b628-4b63-afe8-68e5bca1d862","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":1},{"identificador":"Artículo 2","tipo_articulo":"ordinario","contenido":"Esta Ley tiene por objeto:\nI.  Establecer los principios, bases generales y procedimientos para garantizar el derecho de acceso a la\ninformación pública en posesión de cualquier autoridad, agencia, comisión, comité, corporación, ente,\nentidad, institución, órgano, organismo o equivalente de los poderes Ejecutivo, Legislativo y Judicial de\nlos tres niveles de gobierno, órganos constitucionalmente autónomos, partidos políticos, fideicomisos y\nfondos públicos, así como de cualquier persona física, moral o sindicato que reciba y ejerza recursos\npúblicos o realice actos de autoridad de la Federación, de las entidades federativas, de los municipios\no demarcaciones territoriales de Ciudad de México;\nII.  Distribuir las competencias de las Autoridades garantes en materia de transparencia y acceso a la\ninformación pública, conforme a sus respectivos ámbitos de responsabilidad;\nIII.  Establecer las bases mínimas que regirán los procedimientos para garantizar el ejercicio del derecho\nde acceso a la información pública;\nIV.  Establecer procedimientos sencillos y expeditos para el ejercicio del derecho de acceso a la\ninformación pública, que permitan garantizar condiciones homogéneas y accesibles para las personas\nsolicitantes;\nV.  Regular los medios de impugnación por parte de las Autoridades garantes;\nVI.  Establecer las bases y la información de interés público que deben ser difundidos proactivamente por\nlos sujetos obligados;\nVII.  Regular la organización y funcionamiento del Sistema Nacional de Acceso a la Información, así como\nestablecer las bases de coordinación entre sus integrantes;\nVIII.  Promover, fomentar y difundir la cultura de la transparencia en el ejercicio de la función pública, el\nacceso a la información pública, la participación ciudadana y la rendición de cuentas, mediante\npolíticas públicas y mecanismos que garanticen la difusión de información oportuna, verificable,\ncomprensible, actualizada y completa, en los formatos más adecuados y accesibles para el público,\ntomando en cuenta las condiciones sociales, económicas y culturales de cada región;\nIX.  Propiciar la participación ciudadana en los procesos de toma de decisiones públicas, con el fin de\nfortalecer la democracia, y\nX.  Establecer los mecanismos necesarios para garantizar el cumplimiento de las disposiciones de esta\nLey, a través de la aplicación efectiva de medidas de apremio y sanciones que correspondan.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo I Disposiciones Preliminares","seccion_nombre":null,"id":"007e8b3f-bb93-407b-83f4-65ea4347936d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":2},{"identificador":"Artículo 3","tipo_articulo":"ordinario","contenido":"Para los efectos de la presente Ley se entiende por:\nI.  Ajustes Razonables:  Modificaciones o adaptaciones necesarias y adecuadas que no impongan una\ncarga desproporcionada o indebida, cuando se requieran en un caso particular, con el fin de garantizar\na las personas con discapacidad el goce y ejercicio, en condiciones de igualdad, de los derechos\nhumanos;\nII.  Áreas:  Instancias que disponen o pueden disponer de la información pública. En el sector público,\nserán aquellas que estén previstas en el reglamento interior, el estatuto orgánico respectivo o sus\nequivalentes;\nIII.  Autoridad garante federal:  Transparencia para el Pueblo, órgano administrativo desconcentrado de\nla Secretaría Anticorrupción y Buen Gobierno;\nIV.  Autoridad garante local:  Órganos encargados de la contraloría u homólogos en el poder ejecutivo de\nlas entidades federativas, quienes conocerán también de los asuntos en materia de transparencia de\nsus municipios o demarcaciones territoriales de Ciudad de México, conforme a lo que establezcan sus\nrespectivas leyes;\nV.  Autoridades garantes:  Autoridades garantes federal y local; el órgano de control y disciplina del\nPoder Judicial; los órganos internos de control o equivalentes de los órganos constitucionales\nautónomos, las contralorías internas del Congreso de la Unión; el Instituto Nacional Electoral, por\ncuanto hace al acceso a la información pública de los partidos políticos; el Centro Federal de\nConciliación y Registro Laboral y el Tribunal Federal de Conciliación y Arbitraje, estos dos últimos por\ncuanto hace al acceso a la información pública de los sindicatos y los órganos encargados de la\ncontraloría interna u homólogos de los poderes legislativo y judicial, así como los órganos\nconstitucionales autónomos, de las entidades federativas;\nVI.  Comité de Transparencia:  Instancia a la que hace referencia el artículo 39 de la presente Ley;\nVII.  Consejo Nacional:  Consejo del Sistema Nacional de Acceso a la Información Pública al que hace\nreferencia el artículo 26 de la presente Ley;\nVIII.  Datos Abiertos:  Los datos digitales de carácter público que son accesibles en línea, que pueden ser\nusados, reutilizados y redistribuidos por cualquier persona interesada, los cuales tienen las siguientes\ncaracterísticas:\na)  Accesibles: Disponibles para la mayor cantidad de personas usuarias posibles, para cualquier\npropósito;\nb)  Integrales: Contienen el tema que describen a detalle y con metadatos necesarios;\nc)  Gratuitos: No requieren contraprestación alguna para su acceso;\nd)  No discriminatorios: Están disponibles para cualquier persona, sin necesidad de registro;\ne)  Oportunos: Son actualizados periódicamente, conforme se generen;\nf)  Permanentes: Se conservan en el tiempo, para lo cual, las versiones históricas relevantes para\nuso público se mantendrán disponibles con identificadores adecuados al efecto;\ng)  Primarios: Provienen directamente de la fuente de origen con el mayor nivel de desagregación\nposible;\nh)  Legibles por máquinas: Deberán estar estructurados, total o parcialmente, para ser procesados e\ninterpretados por equipos electrónicos de manera automática;\ni)  En formatos abiertos: Estarán disponibles con el conjunto de características técnicas y de\npresentación que corresponden a la estructura lógica usada para almacenar datos en un archivo\ndigital, cuyas especificaciones técnicas están disponibles públicamente, que no suponen una\ndificultad de acceso y que su aplicación y reproducción no estén condicionadas a\ncontraprestación alguna, y\nj)  De libre uso: Requieren la cita de la fuente de origen como único requisito para su uso;\nIX.  Documento:  Expedientes, reportes, estudios, actas, resoluciones, oficios, correspondencia, acuerdos,\ndirectivas, directrices, circulares, contratos, convenios, instructivos, notas, memorandos, estadísticas y,\nen general, cualquier registro que documente el ejercicio de las facultades, funciones y competencias\nde los sujetos obligados, sus personas servidoras públicas y demás integrantes, sin importar su fuente\no fecha de elaboración, ni el medio en el que se encuentren, ya sea escrito, impreso, sonoro, visual,\nelectrónico, informático u holográfico;\nX.  Entidades federativas:  Partes integrantes de la Federación que son los Estados de Aguascalientes,\nBaja California, Baja California Sur, Campeche, Coahuila de Zaragoza, Colima, Chiapas, Chihuahua,\nDurango, Guanajuato, Guerrero, Hidalgo, Jalisco, México, Michoacán de Ocampo, Morelos, Nayarit,\nNuevo León, Oaxaca, Puebla, Querétaro, Quintana Roo, San Luis Potosí, Sinaloa, Sonora, Tabasco,\nTamaulipas, Tlaxcala, Veracruz de Ignacio de la Llave, Yucatán, Zacatecas y Ciudad de México;\nXI.  Expediente:  Unidad documental física o electrónica compuesta por documentos de archivo,\nordenados y relacionados por un mismo asunto, actividad o trámite de los sujetos obligados;\nXII.  Formatos Abiertos:  Conjunto de características técnicas y de presentación de la información que\ncorresponden a la estructura lógica usada para almacenar datos de forma integral y que facilitan su\nprocesamiento digital, cuyas especificaciones están disponibles públicamente y que permiten el\nacceso sin restricción de uso por parte de las personas usuarias;\nXIII.  Formatos Accesibles:  Cualquier manera o forma alternativa que dé acceso a las personas\nsolicitantes de información, en forma tan viable y cómoda como la de las personas sin discapacidad ni\notras dificultades para acceder a cualquier texto impreso y/o cualquier otro formato convencional en el\nque la información pueda encontrarse;\nXIV.  Información de Interés Público:  Es aquella que resulta relevante o útil para la sociedad y no\nsimplemente de interés individual, cuya divulgación contribuye a que el público conozca las actividades\nque realizan los sujetos obligados en el ejercicio de sus funciones y como ejercen los recursos\npúblicos, así como a exigir la rendición de cuentas y el combate a la corrupción;\nXV.  Ley:  Ley General de Transparencia y Acceso a la Información Pública;\nXVI.  Personas servidoras públicas:  Las mencionadas en el primer párrafo del artículo 108 de la\nConstitución Política de los Estados Unidos Mexicanos y sus correlativos en las Constituciones locales;\nXVII.  Plataforma Nacional:  Plataforma Nacional de Transparencia, a la que se hace referencia en el\nartículo 44 de la presente Ley;\nXVIII.  Sistema Nacional:  Sistema Nacional de Acceso a la Información Pública;\nXIX.  Sujetos obligados:  Cualquier autoridad, agencia, comisión, comité, corporación, ente, entidad,\ninstitución, órgano, organismo o equivalente de los poderes Ejecutivo, Legislativo y Judicial de los tres\nniveles de gobierno, órganos constitucionalmente autónomos, partidos políticos, fideicomisos y fondos\npúblicos, así como cualquier persona física, moral o sindicato que reciba y ejerza recursos públicos o\nrealice actos de autoridad en los referidos niveles de gobierno;\nXX.  Unidad de Transparencia:  Instancia a la que hace referencia el artículo 41 de esta Ley, y\nXXI.  Versión Pública:  Documento o expediente en el que se otorga acceso a la información pública, previa\neliminación u omisión de aquellas partes o secciones que se encuentren clasificadas conforme a la\nLey.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo I Disposiciones Preliminares","seccion_nombre":null,"id":"c96ec9f3-6203-4a52-9638-1f5b3a675dcc","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":3},{"identificador":"Artículo 4","tipo_articulo":"ordinario","contenido":"El derecho humano de acceso a la información comprende solicitar, investigar, difundir, buscar y\nrecibir información.\nToda la información generada, obtenida, adquirida, transformada o en posesión de los sujetos obligados es\npública y accesible a cualquier persona, en los términos y condiciones que se establezcan en la presente Ley, en los\ntratados internacionales de los que el Estado mexicano sea parte, las leyes de las entidades federativas y en las\ndisposiciones jurídicas aplicables dentro de sus respectivas competencias.\nLa información podrá ser clasificada como reservada temporalmente por razones de interés público o seguridad\nnacional conforme a los términos establecidos por esta Ley.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo I Disposiciones Preliminares","seccion_nombre":null,"id":"661f7e14-fabb-4085-8053-cdc69a2bc2a1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":4},{"identificador":"Artículo 5","tipo_articulo":"ordinario","contenido":"No podrá clasificarse como reservada aquella información relacionada con violaciones graves a los\nderechos humanos o con delitos de lesa humanidad, conforme al derecho nacional o a los tratados internacionales\nde los que el Estado mexicano sea parte.\nNinguna persona podrá ser objeto de inquisición judicial o administrativa derivado del ejercicio del derecho de\nacceso a la información, ni se podrá restringir este derecho mediante vías o medios, directos o indirectos.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo I Disposiciones Preliminares","seccion_nombre":null,"id":"f297730b-d5b4-47f4-9506-229f7fc083ff","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":5},{"identificador":"Artículo 6","tipo_articulo":"ordinario","contenido":"El Estado garantizará el efectivo acceso de toda persona a la información en posesión de cualquier\nautoridad, agencia, comisión, comité, corporación, ente, entidad, institución, órgano, organismo o equivalente de los\npoderes Ejecutivo, Legislativo y Judicial de los tres niveles de gobierno, órganos constitucionalmente autónomos,\npartidos políticos, fideicomisos y fondos públicos, así como de cualquier persona física, moral o sindicato que reciba\ny ejerza recursos públicos o realice actos de autoridad de la Federación, de las entidades federativas, de los\nmunicipios o demarcaciones territoriales de la Ciudad de México.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo I Disposiciones Preliminares","seccion_nombre":null,"id":"ddd66d18-5a35-471b-938f-f88aefb53a75","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":6},{"identificador":"Artículo 7","tipo_articulo":"ordinario","contenido":"El derecho de acceso a la información y la clasificación de la información se interpretarán conforme a\nlos principios establecidos en la Constitución Política de los Estados Unidos Mexicanos, en los tratados\ninternacionales de los que el Estado mexicano sea parte, y en la presente Ley.\nEn la aplicación e interpretación de la presente Ley, deberá prevalecer el principio de máxima publicidad,\nconforme a lo dispuesto en la Constitución Política de los Estados Unidos Mexicanos, en los tratados internacionales\nde los que el Estado mexicano sea parte, así como en las resoluciones y sentencias vinculantes que emitan los\nórganos nacionales e internacionales especializados. En todo momento, se deberá favorecer la protección más\namplia de los derechos de las personas.\nPara el caso de la interpretación, se podrán considerar los criterios, determinaciones y opiniones de las\nAutoridades garantes y los organismos internacionales en dicha materia.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo I Disposiciones Preliminares","seccion_nombre":null,"id":"3dd045ff-a152-457a-90bf-da19526481a5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":7},{"identificador":"Artículo 8","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes deberán regir su funcionamiento de acuerdo a los siguientes principios:\nI.  Certeza:  Otorga seguridad y certidumbre jurídica a las personas particulares, ya que permite conocer\nsi las acciones que realizan se ajustan a derecho y garantizan que los procedimientos sean\nverificables, fidedignos y confiables;\nII.  Congruencia:  Implica que exista concordancia entre el requerimiento formulado por el particular y la\nrespuesta proporcionada por el sujeto obligado;\nIII.  Documentación:  Consiste en que los sujetos obligados deberán otorgar acceso a los documentos que\nse encuentren en sus archivos o que estén obligados a documentar, de acuerdo con sus facultades,\ncompetencias o funciones, conforme a las características físicas de la información o del lugar donde se\nencuentre, sin que ello implique la elaboración de documentos ad hoc para atender las solicitudes de\ninformación;\nIV.  Eficacia:  Tutela de manera efectiva el derecho de acceso a la información pública;\nV.  Excepcionalidad:  Implica que la información podrá ser clasificada como reservada o confidencial\núnicamente si se actualizan los supuestos que esta Ley expresamente señala;\nVI.  Exhaustividad:  Significa que la respuesta se refiera expresamente a cada uno de los puntos\nsolicitados, con las limitantes del principio de documentación;\nVII.  Imparcialidad:  Deben en sus actuaciones, ser ajenos o extraños a los intereses de las partes en\ncontroversia, sin inclinaciones hacia ninguna de las partes involucradas;\nVIII.  Independencia:  Deben actuar sin influencias que puedan afectar la imparcialidad o la eficacia del\nderecho de acceso a la información;\nIX.  Legalidad:  Ajustar su actuación a las disposiciones jurídicas aplicables, fundamentando y motivando\nsus resoluciones y actos;\nX.  Máxima publicidad:  Promover que toda la información en posesión de los sujetos obligados\ndocumentada sea pública y accesible, salvo en los casos expresamente establecidos en esta Ley o en\notras disposiciones jurídicas aplicables, en los que podrá ser clasificada como reservada o confidencial\npor razones de interés público o seguridad nacional;\nXI.  Objetividad:  Ajustar su actuación a los supuestos de ley que deben ser aplicados al analizar el caso\nen concreto para resolver, sin considerar juicios personales;\nXII.  Profesionalismo:  Deben sujetar su actuación a conocimientos técnicos, teóricos y metodológicos, que\ngaranticen un desempeño eficiente y eficaz en el ejercicio de su actuar, y\nXIII.  Transparencia:  Dar publicidad a los actos relacionados con sus atribuciones, así como dar acceso a\nla información que tengan la obligación de documentar.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo II De los Principios Generales","seccion_nombre":"Sección Primera De los principios rectores de las Autoridades garantes","id":"94859d98-c0c0-444e-953f-9d22358445d7","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":8},{"identificador":"Artículo 9","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes, así como los sujetos obligados, en el ejercicio, tramitación e interpretación\nde la presente Ley, las correspondientes de las entidades federativas y demás disposiciones relacionadas con la\nreferida materia, deberán atender a los principios establecidos en la presente sección.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo II De los Principios Generales","seccion_nombre":"Sección Segunda De los Principios en Materia de Transparencia y Acceso a la Información Pública","id":"dc1c54ef-4150-421b-8d03-db646fc2ed91","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":9},{"identificador":"Artículo 10","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes otorgarán las medidas pertinentes para asegurar el acceso a la\ninformación a todas las personas, en igualdad de condiciones con las demás.\nEstá prohibida toda forma de discriminación que limite o impida el ejercicio del derecho de acceso a la\ninformación pública en posesión de los sujetos obligados.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo II De los Principios Generales","seccion_nombre":"Sección Segunda De los Principios en Materia de Transparencia y Acceso a la Información Pública","id":"86e0dc67-8072-4757-9bce-35c7ae9529a2","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":10},{"identificador":"Artículo 11","tipo_articulo":"ordinario","contenido":"Toda la información pública documentada, obtenida, adquirida, transformada o en posesión de los\nsujetos obligados es pública y debe ser accesible a cualquier persona. Para ello, se deberán habilitar los medios y\nacciones disponibles, conforme a los términos y condiciones establecidos en esta Ley y demás disposiciones\njurídicas aplicables.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo II De los Principios Generales","seccion_nombre":"Sección Segunda De los Principios en Materia de Transparencia y Acceso a la Información Pública","id":"95690938-84f6-49b7-8994-982d06378afc","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":11},{"identificador":"Artículo 12","tipo_articulo":"ordinario","contenido":"Los sujetos obligados en la generación, publicación y entrega de información, deberán:\nI.  Garantizar que esta sea accesible, confiable, completa, verificable, veraz y oportuna, atendiendo las\nnecesidades del derecho de acceso a la información de toda persona, sin embargo, estará sujeta a un\nrégimen de excepciones claramente definido, y\nII.  Procurar que se utilice un lenguaje inclusivo, claro y comprensible para cualquier persona, y en la\nmedida de lo posible, su accesibilidad y traducción a lenguas indígenas.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo II De los Principios Generales","seccion_nombre":"Sección Segunda De los Principios en Materia de Transparencia y Acceso a la Información Pública","id":"012b9deb-1dcb-48b6-9862-dafaab9ddfd4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":12},{"identificador":"Artículo 13","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes, en el ámbito de sus atribuciones, deberán suplir cualquier deficiencia para\ngarantizar el ejercicio del derecho de acceso a la información, sin que ello implique variar la solicitud, atendiendo al\nprincipio de congruencia.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo II De los Principios Generales","seccion_nombre":"Sección Segunda De los Principios en Materia de Transparencia y Acceso a la Información Pública","id":"095078d0-b6d9-4b90-ade5-ad9bd7e5166d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":13},{"identificador":"Artículo 14","tipo_articulo":"ordinario","contenido":"El ejercicio del derecho de acceso a la información no podrá ser restringido ni estará condicionado a\nque la persona solicitante acredite interés alguno, ni a que justifique el uso que hará de la información solicitada.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo II De los Principios Generales","seccion_nombre":"Sección Segunda De los Principios en Materia de Transparencia y Acceso a la Información Pública","id":"679f6a45-d45e-4419-8ac4-06bcebccbac1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":14},{"identificador":"Artículo 15","tipo_articulo":"ordinario","contenido":"El ejercicio del derecho de acceso a la información es gratuito y solo podrá requerirse el cobro\ncorrespondiente a la modalidad de reproducción y entrega solicitada.\nEn ningún caso los ajustes razonables que se realicen para garantizar el acceso a la información a personas\nsolicitantes con discapacidad, será con algún costo.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo II De los Principios Generales","seccion_nombre":"Sección Segunda De los Principios en Materia de Transparencia y Acceso a la Información Pública","id":"94ae9a04-09b8-4065-b7c0-abc7c8f927d5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":15},{"identificador":"Artículo 16","tipo_articulo":"ordinario","contenido":"Se presume que la información debe existir cuando se refiere a las facultades, competencias y\nfunciones que los ordenamientos jurídicos aplicables otorgan a los sujetos obligados y se tenga la obligación jurídica\nde documentarla.\nEn los casos en que ciertas facultades, competencias o funciones no se hayan ejercido, el sujeto obligado deberá\nmotivar la respuesta que lo justifique.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo II De los Principios Generales","seccion_nombre":"Sección Segunda De los Principios en Materia de Transparencia y Acceso a la Información Pública","id":"48e0e949-90f8-4e28-9182-dec0757a8c56","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":16},{"identificador":"Artículo 17","tipo_articulo":"ordinario","contenido":"Ante la negativa de acceso a la información o inexistencia, el sujeto obligado deberá indicar que la\ninformación solicitada se encuentra comprendida dentro de alguna de las excepciones previstas en esta Ley o, en su\ncaso, que no corresponde a sus facultades, competencias o funciones, o bien, no existe la obligación jurídica de\ndocumentarla.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo II De los Principios Generales","seccion_nombre":"Sección Segunda De los Principios en Materia de Transparencia y Acceso a la Información Pública","id":"f95feb58-b823-48d5-917e-8b281b4c0680","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":17},{"identificador":"Artículo 18","tipo_articulo":"ordinario","contenido":"Todo procedimiento relacionado con el derecho de acceso, entrega y publicación a la información\ndeberá:\nI.  Sustanciarse de manera sencilla, clara y expedita, conforme a las disposiciones establecidas en esta\nLey, y\nII.  Propiciar las condiciones necesarias para garantizar que este sea accesible a cualquier persona, de\nconformidad con el artículo 1o. de la Constitución Política de los Estados Unidos Mexicanos.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo II De los Principios Generales","seccion_nombre":"Sección Segunda De los Principios en Materia de Transparencia y Acceso a la Información Pública","id":"b79832ea-3335-4611-918f-5e5f0649c013","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":18},{"identificador":"Artículo 19","tipo_articulo":"ordinario","contenido":"Los sujetos obligados deberán transparentar y garantizar el acceso a la información documentada en\nsu poder, de conformidad con las disposiciones jurídicas aplicables.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo III De los Sujetos Obligados","seccion_nombre":null,"id":"8f13295a-8263-41e9-add5-e367fbd28e24","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":19},{"identificador":"Artículo 20","tipo_articulo":"ordinario","contenido":"Para el cumplimiento de los objetos de esta Ley, los sujetos obligados deberán cumplir con las\nsiguientes obligaciones, según corresponda, de acuerdo con su naturaleza:\nI.  Constituir el Comité de Transparencia y las Unidades de Transparencia, así como velar por su correcto\nfuncionamiento conforme a su normativa interna;\nII.  Designar en las Unidades de Transparencia a las personas titulares que dependan directamente de la\npersona titular del sujeto obligado y que preferentemente cuenten con experiencia en la materia;\nIII.  Proporcionar capacitación continua y especializada al personal que forme parte de los Comités y las\nUnidades de Transparencia;\nIV.  Constituir y mantener actualizados sus sistemas de archivo y gestión documental, conforme a las\ndisposiciones jurídicas aplicables;\nV.  Promover la generación, documentación y publicación de la información en formatos abiertos y\naccesibles;\nVI.  Proteger y resguardar la información clasificada como reservada o confidencial, conforme a las\ndisposiciones aplicables;\nVII.  Reportar a las Autoridades garantes competentes sobre las acciones de implementación de las\ndisposiciones aplicables en la materia, en los términos que estos determinen;\nVIII.  Atender los requerimientos, observaciones, recomendaciones y criterios en materia de transparencia y\nacceso a la información emitidos por las Autoridades garantes y el Sistema Nacional;\nIX.  Fomentar el uso de tecnologías de la información para garantizar la transparencia, el ejercicio del\nderecho de acceso a la información y la accesibilidad a estos;\nX.  Cumplir con las resoluciones emitidas por las Autoridades garantes;\nXI.  Publicar y mantener actualizada la información relativa a las obligaciones de transparencia, integrando\nlos archivos o ligas correspondientes en la Plataforma Nacional según los procedimientos que para ello\nse establezcan;\nXII.  Difundir proactivamente la información de interés público;\nXIII.  Dar atención a las recomendaciones de las Autoridades garantes;\nXIV.  Promover acuerdos con instituciones públicas especializadas que pudieran auxiliarles a entregar las\nrespuestas a solicitudes de información en lengua indígena, braille o cualquier otro ajuste razonable\ncon el formato accesible correspondiente, en la forma más eficiente;\nXV.  Promover la digitalización de la información en su posesión y la utilización de las tecnologías de\ninformación y comunicación, de conformidad con las políticas que al efecto establezca el Sistema\nNacional;\nXVI.  Responder las solicitudes en materia de acceso a la información a través de la Plataforma Nacional en\nlos términos y plazos establecidos en la presente Ley, sin perjuicio del medio en que se hayan\npresentado o la modalidad de reproducción y entrega solicitada, y\nXVII.  Las demás que resulten de las disposiciones aplicables.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo III De los Sujetos Obligados","seccion_nombre":null,"id":"4bafdc47-7853-430e-a036-a3858256876a","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":20},{"identificador":"Artículo 21","tipo_articulo":"ordinario","contenido":"Los sujetos obligados serán responsables del cumplimiento de las obligaciones, procedimientos y\nresponsabilidades establecidas en esta Ley y las correspondientes de las entidades federativas, en los términos que\nlas mismas determinen.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo III De los Sujetos Obligados","seccion_nombre":null,"id":"127f77af-9240-4195-85de-02d5f88b304c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":21},{"identificador":"Artículo 22","tipo_articulo":"ordinario","contenido":"Los fideicomisos y fondos públicos que no cuenten con estructura orgánica y, por lo tanto, no sean\nconsiderados una entidad paraestatal, así como de los mandatos públicos y demás contratos análogos, deberán\ncumplir con las obligaciones de esta Ley a través de la unidad administrativa responsable de coordinar su operación.","titulo_nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","capitulo_nombre":"Capítulo III De los Sujetos Obligados","seccion_nombre":null,"id":"9aafd115-1c5d-4124-a9f4-e7ea86447d76","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":22},{"identificador":"Artículo 23","tipo_articulo":"ordinario","contenido":"El Sistema Nacional se integra por el conjunto orgánico y articulado de sus miembros,\nprocedimientos, instrumentos y políticas, con el objeto de fortalecer la rendición de cuentas del Estado mexicano.\nTiene como finalidad coordinar y evaluar las acciones relativas a la política pública transversal de transparencia y\nacceso a la información pública, así como establecer e implementar los criterios y lineamientos correspondientes, de\nconformidad con lo señalado en la presente Ley y demás disposiciones jurídicas aplicables.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo I Del Sistema Nacional","seccion_nombre":null,"id":"418a44fc-614d-4178-95ee-222985a79668","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":23},{"identificador":"Artículo 24","tipo_articulo":"ordinario","contenido":"El Sistema Nacional se conformará a partir de la coordinación que se realice entre las distintas\ninstancias que, en razón de sus ámbitos de competencia, contribuyen a la transparencia a nivel nacional, en los tres\nniveles de gobierno.\nEste Sistema que favorecerá a la generación de información de calidad, a la gestión de la información, al\nprocesamiento de la misma como un medio para facilitar el conocimiento, a la evaluación de la gestión pública, a la\npromoción del derecho de acceso a la información, a la difusión de una cultura de la transparencia y a su\naccesibilidad, así como, a una fiscalización y rendición de cuentas efectivas.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo I Del Sistema Nacional","seccion_nombre":null,"id":"2ede7b49-d729-4de3-8a79-04f3046c694d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":24},{"identificador":"Artículo 25","tipo_articulo":"ordinario","contenido":"El Sistema Nacional, que funcionará por conducto de un Consejo Nacional, tiene las siguientes\nfunciones:\nI.  Establecer lineamientos, instrumentos, objetivos, indicadores, metas, estrategias, códigos de buenas\nprácticas, modelos y políticas integrales, sistemáticas, continuas y evaluables, tendientes a cumplir con\nlos objetos de la presente Ley;\nII.  Promover e implementar acciones para garantizar condiciones de accesibilidad para que los grupos de\natención prioritaria puedan ejercer, en igualdad de condiciones, el derecho de acceso a la información\npública;\nIII.  Desarrollar y establecer programas comunes de alcance nacional, para la promoción, investigación,\ndiagnóstico y difusión en materia de transparencia, acceso a la información pública y apertura\ngubernamental en el país;\nIV.  Establecer los criterios para la publicación de los indicadores que permitan a los sujetos obligados\nrendir cuentas del cumplimiento de sus objetivos y resultados obtenidos;\nV.  Coadyuvar en la elaboración, fomento y difusión entre los sujetos obligados de los criterios para la\nsistematización y conservación de archivos que permitan localizar eficientemente la información\npública de acuerdo a las disposiciones jurídicas aplicables en la materia;\nVI.  Establecer políticas en cuanto a la digitalización de la información pública en posesión de los sujetos\nobligados, el uso de tecnologías de información y la implementación de Ajustes Razonables, que\ngaranticen el pleno acceso a esta;\nVII.  Diseñar e implementar políticas en materia de generación, actualización, organización, clasificación,\npublicación, difusión, conservación y accesibilidad de la información pública, de conformidad con las\ndisposiciones jurídicas aplicables;\nVIII.  Promover la participación ciudadana a través de mecanismos eficaces en la planeación,\nimplementación y evaluación de políticas en la materia;\nIX.  Establecer programas de profesionalización, actualización y capacitación de las personas servidoras\npúblicas e integrantes de los sujetos obligados en materia de transparencia y acceso a la información\npública;\nX.  Emitir acuerdos y resoluciones generales para el funcionamiento del Sistema Nacional;\nXI.  Aprobar, promover, evaluar y modificar la política nacional en materia de transparencia y acceso a la\ninformación pública;\nXII.  Promover el ejercicio del derecho de acceso a la información pública en toda la República mexicana;\nXIII.  Promover la coordinación efectiva de las instancias que integran el Sistema Nacional y dar\nseguimiento a las acciones que para tal efecto se establezcan;\nXIV.  Emitir los acuerdos que autoricen y legitimen a la Autoridad garante federal para resolver los recursos\nde inconformidad que interpongan las personas particulares en contra de las resoluciones emitidas por\nlas Autoridades garantes locales distintas a las señaladas en el artículo 163 de esta Ley;\nXV.  Emitir las reglas de operación y funcionamiento del Sistema Nacional, y\nXVI.  Las demás que se desprendan de esta Ley y demás disposiciones jurídicas aplicables.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo I Del Sistema Nacional","seccion_nombre":null,"id":"d70f0654-8dbf-4909-b30c-374d613fafca","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":25},{"identificador":"Artículo 26","tipo_articulo":"ordinario","contenido":"El Consejo Nacional estará integrado por las personas titulares de:\nI.  La Secretaría Anticorrupción y Buen Gobierno, quien lo presidirá;\nII.  La Agencia de Transformación Digital y Telecomunicaciones;\nIII.  El Archivo General de la Nación;\nIV.  El Centro Federal de Conciliación y Registro Laboral;\nV.  El Tribunal Federal de Conciliación y Arbitraje;\nVI.  El Instituto Nacional Electoral, y\nVII.  La presidencia de cada Comité de los Subsistemas de Transparencia a que se refiere el artículo 32 de\nla presente Ley.\nLas personas integrantes a que se refieren las fracciones I a VI del párrafo anterior, podrán ser suplidas en sus\nausencias por la persona servidora pública que al efecto designen, quien deberá tener el nivel jerárquico mínimo de\nDirección General o equivalente.\nLas personas integrantes del Consejo Nacional contarán con voz y voto, y ejercerán sus cargos a título honorífico,\npor lo que no recibirán retribución, emolumento, ni compensación por su participación.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo II Del Consejo Nacional","seccion_nombre":null,"id":"8e4de1df-49c6-4040-81eb-3ebbd067c6e2","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":26},{"identificador":"Artículo 27","tipo_articulo":"ordinario","contenido":"El Consejo Nacional podrá invitar, por la naturaleza de los asuntos a tratar, a las personas,\ninstituciones, representantes de los sujetos obligados y de la sociedad para el desahogo de las reuniones del mismo.\nEn todo caso, los sujetos obligados tendrán la potestad de solicitar ser invitados a estas reuniones.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo II Del Consejo Nacional","seccion_nombre":null,"id":"15e8ca64-cfce-406b-b378-9faff070b4ae","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":27},{"identificador":"Artículo 28","tipo_articulo":"ordinario","contenido":"El Consejo Nacional se reunirá por lo menos cada seis meses, previa convocatoria de la persona\ntitular de la Presidencia o de la persona Secretaria Ejecutiva a indicación de esta, la que deberá ir acompañada del\norden del día y de la documentación correspondiente.\nEl Consejo Nacional sesionará válidamente con la asistencia de por lo menos la mitad más uno de sus\nintegrantes. Los acuerdos se tomarán por la mayoría de votos de los integrantes presentes, teniendo la persona\ntitular de la Presidencia voto de calidad en caso de empate.\nCorresponde a la persona titular de la Presidencia del Consejo Nacional, la facultad de promover en todo tiempo\nla efectiva coordinación y funcionamiento del Sistema Nacional.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo II Del Consejo Nacional","seccion_nombre":null,"id":"56845a88-dd6d-41b4-b024-14ae66da0fc0","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":28},{"identificador":"Artículo 29","tipo_articulo":"ordinario","contenido":"En el desarrollo de los criterios a que se refiere el artículo 25, fracción IV, de esta Ley participarán\nlos integrantes del Consejo Nacional, así como un representante del Consejo Nacional de Armonización Contable,\nprevisto en el artículo 6 de la Ley General de Contabilidad Gubernamental, quien tendrá derecho a voz y podrá\npresentar observaciones por escrito a dichos criterios, las cuales no tendrán carácter obligatorio. Una vez que el\nConsejo Nacional apruebe los criterios, estos serán obligatorios para todos los sujetos obligados.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo II Del Consejo Nacional","seccion_nombre":null,"id":"78a1bd98-83ce-42f3-ae01-eedfbe399c86","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":29},{"identificador":"Artículo 30","tipo_articulo":"ordinario","contenido":"El Consejo Nacional contará con una Secretaría Ejecutiva designada por la persona titular de la\nAutoridad garante federal, que contará con las siguientes atribuciones:\nI.  Dar seguimiento a los acuerdos y resoluciones del Sistema Nacional;\nII.  Verificar el cumplimiento de los programas, estrategias, acciones, políticas y servicios que se adopten\npor el Sistema Nacional;\nIII.  Elaborar y publicar informes de actividades del Sistema Nacional;\nIV.  Colaborar con los integrantes del Sistema Nacional, para fortalecer y garantizar la eficiencia de los\nmecanismos de coordinación, y\nV.  Las demás que le encomiende la persona titular de la Presidencia del Consejo Nacional.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo II Del Consejo Nacional","seccion_nombre":null,"id":"7e6ac207-9cf8-457d-8e3e-d7cde4496aba","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":30},{"identificador":"Artículo 31","tipo_articulo":"ordinario","contenido":"El Sistema Nacional contará con un Subsistema de Transparencia por cada entidad federativa, que\nfuncionará por conducto de su respectivo Comité.\nLos Subsistemas de Transparencia tendrán las siguientes funciones:\nI.  Dar a conocer al Consejo Nacional, a través de su Presidencia, las opiniones que tuvieren sobre el\nproyecto de política nacional en materia de transparencia y acceso a la información pública;\nII.  Apoyar en la supervisión de la ejecución de la política nacional en materia de transparencia y acceso a\nla información pública;\nIII.  Presentar al Consejo Nacional un informe anual sobre sus actividades;\nIV.  Impulsar acciones de coordinación entre sus integrantes que promuevan el cumplimiento de\nobligaciones en materia de transparencia y acceso a la información pública;\nV.  Opinar respecto de los demás asuntos que someta a su consideración el Consejo Nacional, y\nVI.  Las demás que le confiera el Sistema Nacional.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo III De los Subsistemas de Transparencia","seccion_nombre":null,"id":"b655cd17-0aa0-45d9-ae75-a3fea16ed6ba","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":31},{"identificador":"Artículo 32","tipo_articulo":"ordinario","contenido":"El Comité de cada Subsistema de Transparencia se integrará con una persona representante de los\nórganos encargados de la contraloría u homólogos de la entidad federativa de:\nI.  El poder ejecutivo, quien lo presidirá;\nII.  El poder legislativo;\nIII.  El poder judicial, y\nIV.  Cada uno de los órganos constitucionales autónomos.\nEl Comité de cada Subsistema de Transparencia también tendrá como integrantes a los representantes de\nmunicipios de la entidad federativa o demarcaciones territoriales de la Ciudad de México que se determine en la\nlegislación local que corresponda.\nLas personas integrantes del Comité de cada Subsistema de Transparencia, podrán ser suplidas en sus\nausencias por la persona servidora pública que al efecto designen, quienes deberán tener el nivel jerárquico\ninmediato inferior al de ellas.\nLas personas integrantes del Comité de cada Subsistema de Transparencia contarán con voz y voto, y ejercerán\nsus cargos a título honorífico, por lo que no recibirán retribución, emolumento, ni compensación por su participación.\nLas decisiones del Comité de cada Subsistema de Transparencia se tomarán por mayoría de sus integrantes\npresentes. En caso de empate la persona que lo preside tendrá voto de calidad.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo III De los Subsistemas de Transparencia","seccion_nombre":null,"id":"b144f131-9863-4693-bec2-013a34ccc31e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":32},{"identificador":"Artículo 33","tipo_articulo":"ordinario","contenido":"El Comité de cada Subsistema de Transparencia podrá invitar, por la naturaleza de los asuntos a\ntratar, a las personas, instituciones, representantes de los sujetos obligados y de la sociedad para el desahogo de las\nreuniones del mismo. En todo caso, los sujetos obligados tendrán la potestad de solicitar ser invitados a estas\nreuniones.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo III De los Subsistemas de Transparencia","seccion_nombre":null,"id":"2b8d3b91-ea74-40d9-8d90-09e5e1840489","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":33},{"identificador":"Artículo 34","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes serán responsables de garantizar, en el ámbito de su competencia, el\nejercicio de los derechos de acceso a la información pública y la protección de datos personales, conforme a los\nprincipios y bases establecidos por el artículo 6o. de la Constitución Política de los Estados Unidos Mexicanos, así\ncomo por lo previsto en esta Ley y demás disposiciones jurídicas aplicables.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo IV De las Autoridades garantes","seccion_nombre":null,"id":"cb810fc2-dfd0-487f-9d3b-5f77af51232c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":34},{"identificador":"Artículo 35","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes tendrán las atribuciones siguientes:\nI.  Interpretar, en el ámbito de sus atribuciones, los ordenamientos que les resulten aplicables, derivados\nde esta Ley y de la Constitución Política de los Estados Unidos Mexicanos;\nII.  Conocer y resolver los recursos de revisión interpuestos por las personas particulares en contra de las\nresoluciones de los sujetos obligados en sus respectivos ámbitos de competencia, en términos de lo\ndispuesto en el Capítulo I del Título Octavo de la presente Ley;\nIII.  Imponer las medidas de apremio y sanciones, según corresponda, de conformidad con lo previsto en\nla presente Ley y demás disposiciones que deriven de la misma;\nIV.  Promover y difundir el ejercicio de los derechos de acceso a la información, de conformidad con la\npolítica nacional en materia de transparencia y acceso a la información pública y las disposiciones\njurídicas aplicables en la materia;\nV.  Fomentar la cultura de la transparencia en el sistema educativo;\nVI.  Brindar capacitación a las personas servidoras públicas y apoyo técnico a los sujetos obligados en\nmateria de transparencia y acceso a la información;\nVII.  Establecer políticas de transparencia con sentido social, atendiendo a las condiciones económicas,\nsociales y culturales;\nVIII.  Suscribir convenios con los sujetos obligados que propicien la publicación de información en el marco\nde las políticas de transparencia con sentido social;\nIX.  Suscribir convenios de colaboración con las personas particulares o con sectores de la sociedad\ncuando sus actividades o productos sean de interés público o de relevancia social;\nX.  Suscribir convenios de colaboración con otras Autoridades garantes para el cumplimiento de sus\natribuciones y promover mejores prácticas en la materia;\nXI.  Promover la igualdad sustantiva;\nXII.  Coordinarse con las autoridades competentes para que, en los procedimientos de acceso a la\ninformación y en los medios de impugnación, se contemple contar con la información en lenguas\nindígenas y en formatos accesibles para que sean sustanciados y atendidos en la misma lengua y en\nsu caso, se promuevan los ajustes razonables necesarios si se tratara de personas con discapacidad;\nXIII.  Garantizar condiciones de accesibilidad para que los grupos de atención prioritaria puedan ejercer su\nderecho de acceso a la información pública en igualdad de circunstancias;\nXIV.  Informar a la instancia competente sobre la probable responsabilidad de los sujetos obligados que\nincumplan las obligaciones previstas en la presente Ley y en las demás disposiciones aplicables;\nXV.  Promover la participación y colaboración con organismos internacionales, en el análisis y mejores\nprácticas en materia de acceso a la información pública;\nXVI.  Fomentar los principios de transparencia, rendición de cuentas, participación ciudadana, accesibilidad\ne innovación tecnológica;\nXVII.  Emitir recomendaciones a los sujetos obligados, con el propósito de diseñar, implementar y evaluar\nacciones de apertura gubernamental que permitan orientar las políticas internas en la materia;\nXVIII.  Promover la digitalización de la información pública en posesión de los sujetos obligados y la\nutilización de las tecnologías de información y comunicación, conforme a las políticas que establezca\nel Sistema Nacional, y\nXIX.  Las demás atribuciones que les confiera esta Ley y otras disposiciones aplicables.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo IV De las Autoridades garantes","seccion_nombre":null,"id":"c2c7547f-d11b-46c7-9e11-0ac9a0264868","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":35},{"identificador":"Artículo 36","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes para el ejercicio y desempeño de las atribuciones que les otorga la\npresente Ley, tendrán la naturaleza jurídica, adscripción y estructura administrativa que se establezca en sus\nrespectivos reglamentos interiores o análogos o acuerdos de carácter general, en el ámbito de sus respectivas\ncompetencias.\nLas Autoridades garantes locales podrán prever que su estructura será similar a la de la Autoridad garante federal\nen sus respectivas leyes.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo IV De las Autoridades garantes","seccion_nombre":null,"id":"ffd70d10-e90c-4cc6-9732-0fb99bb504c5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":36},{"identificador":"Artículo 37","tipo_articulo":"ordinario","contenido":"La Autoridad garante federal, además de lo señalado en el artículo 35 de la presente Ley, tendrá las\nsiguientes atribuciones:\nI.  Conocer y resolver los recursos de inconformidad que interpongan las personas particulares en contra\nde las resoluciones emitidas por las Autoridades garantes locales cuando las mismas se encuentren\nvinculadas con recursos públicos federales;\nII.  Encabezar y coordinar el Sistema Nacional, y\nIII.  Las demás que le confiera el Sistema Nacional por conducto del Consejo Nacional, esta Ley y otras\ndisposiciones en la materia.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo IV De las Autoridades garantes","seccion_nombre":null,"id":"46b3aadb-2b50-4447-8334-ec3b58791f90","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":37},{"identificador":"Artículo 38","tipo_articulo":"ordinario","contenido":"La persona titular de la Autoridad garante federal será nombrada por la persona titular del Ejecutivo\nFederal.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo IV De las Autoridades garantes","seccion_nombre":null,"id":"a7ca4010-9b2c-4368-9ae7-e908fe373de8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":38},{"identificador":"Artículo 39","tipo_articulo":"ordinario","contenido":"En cada sujeto obligado se integrará un Comité de Transparencia colegiado e integrado por un\nnúmero impar.\nEl Comité de Transparencia adoptará sus resoluciones por mayoría de votos, en caso de empate, quien presida\nel Comité tendrá voto de calidad. A sus sesiones podrán asistir como personas invitadas, aquéllas que sus\nintegrantes consideren necesarias, quienes tendrán voz, pero no voto.\nQuienes integren el Comité de Transparencia no podrán depender jerárquicamente entre sí, tampoco podrán\nreunirse dos o más integrantes en una sola persona. Cuando se presente el caso, la persona titular del sujeto\nobligado tendrá que nombrar a la persona que supla al subordinado. Quienes integren los Comités de Transparencia\ncontarán con suplentes cuya designación se realizará de conformidad con la normatividad interna de los respectivos\nsujetos obligados, y deberán corresponder a personas que ocupen cargos de la jerarquía inmediata inferior a la de\nlas personas integrantes propietarias.\nEn el caso de la Administración Pública Federal, los Comités de Transparencia de las dependencias y entidades,\nestarán conformados por:\nI.  La persona responsable del área coordinadora de archivos o equivalente;\nII.  La persona responsable de la Unidad de Transparencia, y\nIII.  La persona titular del Órgano Interno de Control u homólogo.\nLas personas integrantes del Comité de Transparencia tendrán acceso a la información para determinar su\nclasificación, conforme a las disposiciones jurídicas emitidas por los sujetos obligados para el resguardo o\nsalvaguarda de la información.\nEl Sistema Nacional de Investigación e Inteligencia en materia de Seguridad Pública, el Centro Nacional de\nInteligencia, el Centro Federal de Protección a Personas, las Divisiones de Inteligencia e Investigación de la Policía\nFederal Ministerial y Guardia Nacional, la Agencia de Investigación Criminal, el Centro Federal de Investigación\nCriminal, la Fiscalía Especializada en materia de Delincuencia Organizada, la Unidad de Inteligencia Financiera, el\nEstado Mayor de la Defensa Nacional, el Estado Mayor General de la Armada, o bien las unidades administrativas\nque los sustituyan, no estarán sujetos a la autoridad de los Comités de Transparencia a que se refiere este artículo.\nLas funciones correspondientes serán responsabilidad exclusiva de la persona titular de la entidad o unidad\nadministrativa.\nLa clasificación, desclasificación y acceso a la información que generan o custodian las instancias de inteligencia\ne investigación deberán apegarse a los términos previstos en la presente Ley y a los protocolos de seguridad y\nresguardo establecidos para ello.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo V De los Comités de Transparencia","seccion_nombre":null,"id":"0e9ba5cf-f80f-42f0-b9b9-8553bc43c0dd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":39},{"identificador":"Artículo 40","tipo_articulo":"ordinario","contenido":"Cada Comité de Transparencia tendrá las siguientes atribuciones:\nI.  Instituir, coordinar y supervisar las acciones y procedimientos para asegurar la mayor eficacia en la\ngestión de las solicitudes en materia de acceso a la información, en términos de las disposiciones\naplicables;\nII.  Confirmar, modificar o revocar las determinaciones en materia de ampliación del plazo de respuesta,\nclasificación de la información y declaración de inexistencia o incompetencia, que sean adoptadas por\nlas personas titulares de las Áreas correspondientes de los sujetos obligados;\nIII.  Ordenar, en su caso, a las áreas competentes que generen la información que derivado de sus\nfacultades, competencias y funciones deban tener en posesión o que previa acreditación de la\nimposibilidad de su generación, exponga, de forma fundada y motivada, las razones por las cuales, en\nel caso particular, no ejercieron dichas facultades, competencias o funciones;\nIV.  Establecer políticas para facilitar la obtención de información y el ejercicio del derecho de acceso a la\ninformación;\nV.  Promover y establecer programas de capacitación en materia de transparencia, acceso a la\ninformación y accesibilidad para todas las personas servidoras públicas o integrantes del sujeto\nobligado;\nVI.  Recabar y enviar a las Autoridades garantes los datos necesarios para la elaboración del informe\nanual, conforme a los lineamientos que dichas autoridades expidan;\nVII.  Solicitar y autorizar la ampliación del plazo de reserva de la información, conforme a lo dispuesto en el\nartículo 104 de la presente Ley, y\nVIII.  Las demás que se desprendan de las disposiciones jurídicas aplicables.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo V De los Comités de Transparencia","seccion_nombre":null,"id":"e91fc27d-be52-4942-aaf1-4f0125f68d44","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":40},{"identificador":"Artículo 41","tipo_articulo":"ordinario","contenido":"Los sujetos obligados designarán a la persona responsable de la Unidad de Transparencia, quien\ntendrá las siguientes atribuciones:\nI.  Recabar y difundir la información prevista en los Capítulos II, III, IV y V del Título Quinto de esta Ley, y\npropiciar que las áreas la actualicen periódicamente, conforme las disposiciones jurídicas aplicables;\nII.  Recibir y dar trámite a las solicitudes de acceso a la información;\nIII.  Auxiliar a las personas particulares en la elaboración de solicitudes de acceso a la información y, en su\ncaso, orientarles sobre los sujetos obligados competentes conforme a las disposiciones jurídicas\naplicables;\nIV.  Realizar los trámites internos necesarios para la atención de las solicitudes de acceso a la información;\nV.  Efectuar las notificaciones a las personas solicitantes;\nVI.  Proponer al Comité de Transparencia los procedimientos internos que aseguren la mayor eficiencia en\nla gestión de las solicitudes de acceso a la información, conforme a las disposiciones jurídicas\naplicables;\nVII.  Proponer personal habilitado que sea necesario para recibir y dar trámite a las solicitudes de acceso a\nla información;\nVIII.  Llevar un registro de las solicitudes de acceso a la información, respuestas, resultados, costos de\nreproducción y envío;\nIX.  Promover e implementar políticas de transparencia con sentido social procurando su accesibilidad;\nX.  Fomentar la transparencia y accesibilidad al interior del sujeto obligado;\nXI.  Hacer del conocimiento de la instancia competente la probable responsabilidad por el incumplimiento\nde las obligaciones previstas en la presente Ley y en las demás disposiciones aplicables, y\nXII.  Las demás que se desprendan de las disposiciones jurídicas aplicables.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo VI De las Unidades de Transparencia","seccion_nombre":null,"id":"790dfadf-73e5-4db7-b2c8-b635858bbf08","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":41},{"identificador":"Artículo 42","tipo_articulo":"ordinario","contenido":"En caso que alguna área de los sujetos obligados se negara a colaborar con la Unidad de\nTransparencia, esta informará a su superior jerárquico para que le ordene realizar sin demora las acciones\nconducentes.\nSi persiste la negativa de colaboración, la Unidad de Transparencia lo hará del conocimiento de la autoridad\ncompetente, quien podrá iniciar el procedimiento de responsabilidad respectivo.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo VI De las Unidades de Transparencia","seccion_nombre":null,"id":"34eaabd8-8d8e-4d7f-a987-ec0aed6b4d48","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":42},{"identificador":"Artículo 43","tipo_articulo":"ordinario","contenido":"Las oficinas que ocupen las Unidades de Transparencia se deben ubicar en lugares visibles al\npúblico en general y ser de fácil acceso.\nLas Unidades de Transparencia deben contar con las condiciones mínimas de operación que aseguren el\ncumplimiento de sus funciones.\nLos sujetos obligados deberán capacitar al personal que integra las Unidades de Transparencia, de conformidad\ncon los lineamientos que para dicho efecto emita el Sistema Nacional.","titulo_nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","capitulo_nombre":"Capítulo VI De las Unidades de Transparencia","seccion_nombre":null,"id":"6737986c-f66a-43ad-98d7-38941870dc3e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":43},{"identificador":"Artículo 44","tipo_articulo":"ordinario","contenido":"La Secretaría Anticorrupción y Buen Gobierno administrará, implementará y pondrá en\nfuncionamiento la Plataforma Nacional que permita cumplir con los procedimientos, obligaciones y disposiciones\nseñaladas en la presente Ley para los sujetos obligados y Autoridades garantes atendiendo a las necesidades de\naccesibilidad de las personas usuarias, así como en otras disposiciones jurídicas.","titulo_nombre":"TÍTULO TERCERO PLATAFORMA NACIONAL DE TRANSPARENCIA","capitulo_nombre":"Capítulo Único De la Plataforma Nacional de Transparencia","seccion_nombre":null,"id":"68dab437-bf45-4a1a-b79b-a5bb1762beb4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":44},{"identificador":"Artículo 45","tipo_articulo":"ordinario","contenido":"La Plataforma Nacional contará con los módulos siguientes:\nI.  Solicitudes de acceso a la información;\nII.  Gestión de medios de impugnación;\nIII.  Portales de obligaciones de transparencia;\nIV.  Comunicación entre las Autoridades garantes y sujetos obligados, y\nV.  Cualquier otro que determine el Sistema Nacional.","titulo_nombre":"TÍTULO TERCERO PLATAFORMA NACIONAL DE TRANSPARENCIA","capitulo_nombre":"Capítulo Único De la Plataforma Nacional de Transparencia","seccion_nombre":null,"id":"4bf87553-664a-44a9-a01a-bb3c9febe879","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":45},{"identificador":"Artículo 46","tipo_articulo":"ordinario","contenido":"El Sistema Nacional establecerá las medidas necesarias para garantizar la estabilidad y seguridad\nde la Plataforma Nacional, promoviendo la homologación de procesos y la simplicidad del uso de los sistemas por\nparte de las personas usuarias.","titulo_nombre":"TÍTULO TERCERO PLATAFORMA NACIONAL DE TRANSPARENCIA","capitulo_nombre":"Capítulo Único De la Plataforma Nacional de Transparencia","seccion_nombre":null,"id":"c295a168-6b2e-4f6f-b3c0-bb3ae4aa033a","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":46},{"identificador":"Artículo 47","tipo_articulo":"ordinario","contenido":"Los sujetos obligados en coordinación con las Autoridades garantes deberán capacitar y actualizar\nde forma permanente, a todas sus personas servidoras públicas en materia del derecho de acceso a la información,\na través de los medios que se considere pertinentes.\nCon el objeto de crear una cultura de la transparencia y acceso a la información entre las personas habitantes de\nlos Estados Unidos Mexicanos, las Autoridades garantes podrán promover, en colaboración con instituciones\neducativas y culturales del sector público o privado, actividades, mesas de trabajo, exposiciones y concursos\nrelativos a la transparencia y acceso a la información.","titulo_nombre":"TÍTULO CUARTO CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL","capitulo_nombre":"Capítulo I De la Promoción de la Transparencia y el Derecho de Acceso a la Información","seccion_nombre":null,"id":"37281b68-a09f-4258-8659-2207faa2c685","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":47},{"identificador":"Artículo 48","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes, en el ámbito de sus respectivas competencias o a través de los\nmecanismos de coordinación que al efecto establezcan, podrán:\nI.  Proponer, a las autoridades educativas competentes que incluyan contenidos sobre la importancia\nsocial del derecho de acceso a la información en los planes y programas de estudio de educación\npreescolar, primaria, secundaria, normal y para la formación de maestros de educación básica en sus\nrespectivas jurisdicciones;\nII.  Promover, entre las instituciones públicas y privadas de educación media superior y superior, la\ninclusión, dentro de sus programas de estudio, actividades académicas curriculares y extracurriculares,\nde temas que ponderen la importancia social del derecho de acceso a la información y rendición de\ncuentas;\nIII.  Promover, que en las bibliotecas y entidades especializadas en materia de archivos se prevea la\ninstalación de módulos de información pública, que faciliten el ejercicio del derecho de acceso a la\ninformación y la consulta de la información derivada de las obligaciones de transparencia a que se\nrefiere esta Ley;\nIV.  Proponer, entre las instituciones públicas y privadas de educación superior, la creación de centros de\ninvestigación, difusión y docencia sobre transparencia, derecho de acceso a la información y rendición\nde cuentas;\nV.  Establecer, entre las instituciones públicas de educación, acuerdos para la elaboración y publicación\nde materiales que fomenten la cultura del derecho de acceso a la información y rendición de cuentas;\nVI.  Promover, en coordinación con autoridades federales, estatales y municipales o de las demarcaciones\nterritoriales de la Ciudad de México, la participación ciudadana y de organizaciones sociales en\ntalleres, seminarios y actividades que tengan por objeto la difusión de los temas de transparencia y\nderecho de acceso a la información;\nVII.  Desarrollar, programas de formación de personas usuarias de este derecho para incrementar su\nejercicio y aprovechamiento, privilegiando a integrantes de grupos de atención prioritaria;\nVIII.  Impulsar, estrategias que pongan al alcance de los diversos sectores de la sociedad los medios para el\nejercicio del derecho de acceso a la información, acordes a su contexto sociocultural, y\nIX.  Desarrollar, con el concurso de centros comunitarios digitales y bibliotecas públicas, universitarias,\ngubernamentales y especializadas, programas para la asesoría y orientación de sus personas usuarias\nen el ejercicio y aprovechamiento del derecho de acceso a la información.","titulo_nombre":"TÍTULO CUARTO CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL","capitulo_nombre":"Capítulo I De la Promoción de la Transparencia y el Derecho de Acceso a la Información","seccion_nombre":null,"id":"cee7f361-e19b-4688-858a-bd29c6b93207","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":48},{"identificador":"Artículo 49","tipo_articulo":"ordinario","contenido":"Para el cumplimiento de las obligaciones previstas en la presente Ley, los sujetos obligados podrán\ndesarrollar o adoptar, en lo individual o en acuerdo con otros sujetos obligados, esquemas de mejores prácticas que\ntengan por objeto:\nI.  Elevar el nivel de cumplimiento de las disposiciones previstas en la presente Ley;\nII.  Armonizar el acceso a la información por sectores;\nIII.  Facilitar el ejercicio del derecho de acceso a la información a las personas, y\nIV.  Procurar la accesibilidad de la información.","titulo_nombre":"TÍTULO CUARTO CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL","capitulo_nombre":"Capítulo I De la Promoción de la Transparencia y el Derecho de Acceso a la Información","seccion_nombre":null,"id":"ca33a692-8dbb-430c-9812-09376bc99bd5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":49},{"identificador":"Artículo 50","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes emitirán políticas de transparencia con sentido social, en atención a los\nlineamientos generales definidos para ello por el Sistema Nacional, diseñadas para incentivar a los sujetos obligados\na publicar información de utilidad sobre temas prioritarios. Dichas políticas tendrán por objeto, entre otros, promover\nla reutilización y aprovechamiento de la información que generan los sujetos obligados, considerando la demanda de\nla sociedad, identificada con base en las metodologías previamente establecidas.","titulo_nombre":"TÍTULO CUARTO CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL","capitulo_nombre":"Capítulo II De la Transparencia con Sentido Social","seccion_nombre":null,"id":"388f7524-69ed-4653-84c3-e6373716a59e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":50},{"identificador":"Artículo 51","tipo_articulo":"ordinario","contenido":"La información publicada por los sujetos obligados, en el marco de la política de transparencia con\nsentido social, se difundirá en los medios y formatos que más convengan al público al que va dirigida.","titulo_nombre":"TÍTULO CUARTO CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL","capitulo_nombre":"Capítulo II De la Transparencia con Sentido Social","seccion_nombre":null,"id":"9a874663-da58-4c60-9050-8bf0ec25b449","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":51},{"identificador":"Artículo 52","tipo_articulo":"ordinario","contenido":"El Sistema Nacional emitirá los criterios para evaluar la efectividad de la política de la transparencia\ncon sentido social, considerando como base, la reutilización y aprovechamiento que la sociedad haga a la\ninformación.\nLa información que se publique, como resultado de las políticas de transparencia, deberá permitir la generación\nde conocimiento público útil, para disminuir asimetrías de la información, mejorar los accesos a trámites y servicios,\noptimizar la toma de decisiones de autoridades o cualquier persona y deberá tener un objeto claro enfocado en las\nnecesidades de sectores de la sociedad determinados o determinables.","titulo_nombre":"TÍTULO CUARTO CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL","capitulo_nombre":"Capítulo II De la Transparencia con Sentido Social","seccion_nombre":null,"id":"c8d0700f-9f18-446a-af46-7815d41b8c97","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":52},{"identificador":"Artículo 53","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes, en el ámbito de sus atribuciones, coadyuvarán con los sujetos obligados y\nrepresentantes de la sociedad civil en la construcción e implementación de mecanismos de colaboración para la\npromoción e implementación de políticas y mecanismos de apertura institucional.","titulo_nombre":"TÍTULO CUARTO CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL","capitulo_nombre":"Capítulo III De la Apertura Institucional","seccion_nombre":null,"id":"ccf2b23c-4855-4c70-a9bb-3ac71b1bc0a9","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":53},{"identificador":"Artículo 54","tipo_articulo":"ordinario","contenido":"Los sujetos obligados, en el ámbito de su competencia, en materia de apertura deben:\nI.  Garantizar el ejercicio y cumplimiento de los principios de transparencia con sentido social, la\nparticipación ciudadana, la rendición de cuentas, la innovación y el aprovechamiento de la tecnología\nque privilegie su diseño centrado en el usuario;\nII.  Implementar tecnología y datos abiertos incluyendo, en la digitalización de información relativa a\nservicios públicos, trámites y demás componentes del actuar gubernamental, la publicidad de datos de\ninterés para la población, principalmente de manera automática y sin incremento de la carga\nadministrativa, de conformidad con su disponibilidad presupuestaria, y\nIII.  Procurar mecanismos que fortalezcan la participación y la colaboración de las personas particulares en\nasuntos económicos, sociales, culturales y políticos de la Nación.","titulo_nombre":"TÍTULO CUARTO CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL","capitulo_nombre":"Capítulo III De la Apertura Institucional","seccion_nombre":null,"id":"2ae64ea3-1f7d-589f-b18e-4cd56f9158cb","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":54},{"identificador":"Artículo 55","tipo_articulo":"ordinario","contenido":"Las dependencias y entidades de la Administración Pública Federal deberán realizar acciones en\nmateria de datos abiertos y gobierno abierto conforme a los lineamientos que al efecto emita la Agencia de\nTransformación Digital y Telecomunicaciones.","titulo_nombre":"TÍTULO CUARTO CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL","capitulo_nombre":"Capítulo III De la Apertura Institucional","seccion_nombre":null,"id":"30417a7b-95dd-4a77-8562-6d1cc406eadd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":55},{"identificador":"Artículo 56","tipo_articulo":"ordinario","contenido":"Los sujetos obligados deberán cumplir con las obligaciones de transparencia y poner a disposición\ndel público y mantener actualizada, en los respectivos medios electrónicos, de acuerdo con sus facultades,\natribuciones, funciones u objeto social, según corresponda, la información, por lo menos, de los temas, documentos y\npolíticas e información señalados en este Título.\nAquella información particular de la referida en este Título que se ubique en alguno de los supuestos de\nclasificación señalados en los artículos 110 y 113 de la presente Ley, no será objeto de la publicación a que se\nrefiere este mismo artículo, salvo que pueda ser elaborada una versión pública. En todo caso se aplicará la prueba\nde daño a que se refiere el artículo 107 de la presente Ley.\nEn sus resoluciones las Autoridades garantes podrán señalar a los sujetos obligados que la información que\ndeben proporcionar sea considerada como obligación de transparencia de conformidad con este Título, atendiendo a\nla relevancia de la información, la incidencia de las solicitudes sobre la misma y el sentido reiterativo de las\nresoluciones.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo I De las Obligaciones Generales","seccion_nombre":null,"id":"b22119d4-d2c9-45ed-aab5-403ea0d773c4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":56},{"identificador":"Artículo 57","tipo_articulo":"ordinario","contenido":"Los lineamientos que emita el Sistema Nacional establecerán los formatos de publicación de la\ninformación para asegurar que la información sea veraz, confiable, oportuna, congruente, integral, actualizada,\naccesible, comprensible, verificable.\nLos lineamientos a que se refiere el párrafo anterior procurarán la homologación en la presentación de la\ninformación a la que hace referencia este Título por parte de los sujetos obligados.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo I De las Obligaciones Generales","seccion_nombre":null,"id":"749bfca2-4241-4ccb-93ad-6b3e880d093f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":57},{"identificador":"Artículo 58","tipo_articulo":"ordinario","contenido":"La información correspondiente a las obligaciones de transparencia deberá actualizarse por lo\nmenos cada tres meses, salvo que en la presente Ley se establezca un plazo diverso. El Sistema Nacional emitirá\nlos criterios para determinar el plazo mínimo que deberá permanecer disponible y accesible la información,\natendiendo a las cualidades de la misma.\nLa publicación de la información deberá indicar el sujeto obligado encargado de generarla, así como la fecha de\nsu última actualización.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo I De las Obligaciones Generales","seccion_nombre":null,"id":"058f158e-715b-4a50-9831-b29df8284380","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":58},{"identificador":"Artículo 59","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes, de oficio o a petición de las personas particulares, verificarán el\ncumplimiento que los sujetos obligados den a las disposiciones previstas en este Título.\nLas denuncias presentadas por las personas particulares podrán realizarse en cualquier momento, de\nconformidad con el procedimiento señalado en la presente Ley.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo I De las Obligaciones Generales","seccion_nombre":null,"id":"ffd3fcf4-b8c1-48fb-9087-a717e0745ad6","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":59},{"identificador":"Artículo 60","tipo_articulo":"ordinario","contenido":"La página de inicio de los portales de Internet de los sujetos obligados tendrá un vínculo de acceso\ndirecto al sitio donde se encuentra la información pública a la que se refiere este Título, el cual deberá contar con un\nbuscador.\nLa información de obligaciones de transparencia deberá publicarse con perspectiva de género y discapacidad,\ncuando así corresponda a su naturaleza.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo I De las Obligaciones Generales","seccion_nombre":null,"id":"e1558584-5cef-41de-8e28-e045e59ca1b5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":60},{"identificador":"Artículo 61","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes y los sujetos obligados establecerán las medidas que faciliten el acceso y\nbúsqueda de la información para personas con discapacidad y se procurará que la información publicada sea\naccesible de manera focalizada a personas que hablen alguna lengua indígena.\nPor lo que, por sí mismos o a través del Sistema Nacional, deberán promover y desarrollar de forma progresiva,\npolíticas y programas tendientes a garantizar la accesibilidad de la información en la máxima medida posible.\nSe promoverá la homogeneidad y la estandarización de la información, a través de la emisión de lineamientos y\nde formatos por parte del Sistema Nacional.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo I De las Obligaciones Generales","seccion_nombre":null,"id":"12cdd781-a160-42d5-812c-b690ddcfe200","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":61},{"identificador":"Artículo 62","tipo_articulo":"ordinario","contenido":"Los sujetos obligados pondrán a disposición de las personas interesadas equipos de cómputo con\nacceso a Internet, que permitan a las personas particulares consultar la información o utilizar el sistema de\nsolicitudes de acceso a la información en las oficinas de las Unidades de Transparencia. Lo anterior, sin perjuicio de\nque adicionalmente se utilicen medios alternativos de difusión de la información, cuando en determinadas\npoblaciones éstos resulten de más fácil acceso y comprensión.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo I De las Obligaciones Generales","seccion_nombre":null,"id":"91c5d5c3-d640-424c-9cff-e9b9c93ed346","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":62},{"identificador":"Artículo 63","tipo_articulo":"ordinario","contenido":"La información publicada por los sujetos obligados, en términos del presente Título, no constituye\npropaganda gubernamental. Los sujetos obligados, incluso dentro de los procesos electorales, a partir del inicio de\nlas precampañas y hasta la conclusión del proceso electoral, deberán mantener accesible la información en el portal\nde obligaciones de transparencia, salvo disposición expresa en contrario en las disposiciones jurídicas en materia\nelectoral.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo I De las Obligaciones Generales","seccion_nombre":null,"id":"a87b0879-b33a-4092-98a5-f3a35970870d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":63},{"identificador":"Artículo 64","tipo_articulo":"ordinario","contenido":"Los sujetos obligados y las personas particulares serán responsables de los datos personales en su\nposesión de conformidad con las disposiciones jurídicas aplicables en la materia.\nLos sujetos obligados no podrán difundir, distribuir o comercializar los datos personales contenidos en los\nsistemas de información, desarrollados en el ejercicio de sus funciones, salvo que haya mediado el consentimiento\nexpreso, por escrito o por un medio de autenticación similar, de las personas a que haga referencia la información de\nacuerdo a las disposiciones jurídicas aplicables. Lo anterior, sin perjuicio a lo establecido por el artículo 119 de esta\nLey.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo I De las Obligaciones Generales","seccion_nombre":null,"id":"9e5172dd-4602-4070-b124-00c95d1a4e3f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":64},{"identificador":"Artículo 65","tipo_articulo":"ordinario","contenido":"Los sujetos obligados pondrán a disposición del público y mantendrán actualizada, en los\nrespectivos medios electrónicos, de acuerdo con sus facultades, atribuciones, funciones u objeto social, según\ncorresponda, la información, por lo menos, de los temas, documentos y políticas que a continuación se señalan:\nI.  El marco normativo aplicable al sujeto obligado, en el que deberá incluirse leyes, códigos,\nreglamentos, decretos de creación, manuales administrativos, reglas de operación, criterios, políticas,\nentre otros;\nII.  Su estructura orgánica completa, en un formato que permita vincular cada parte de la estructura, las\natribuciones y responsabilidades que le corresponden a cada persona servidora pública y/o persona\nprestadora de servicios profesionales miembro de los sujetos obligados, de conformidad con las\ndisposiciones aplicables;\nIII.  Las facultades de cada área;\nIV.  Las metas y objetivos de las áreas de conformidad con sus programas operativos;\nV.  Los indicadores relacionados con temas de interés público o trascendencia social que, conforme a sus\nfunciones, deban establecer, así como los que permitan rendir cuenta de sus objetivos y resultados;\nVI.  El directorio de todas las personas servidoras públicas, a partir del nivel de jefe de departamento o su\nequivalente, o de menor nivel, cuando se brinde atención al público; manejen o apliquen recursos\npúblicos; realicen actos de autoridad o presten servicios profesionales bajo el régimen de confianza u\nhonorarios y personal de base. El directorio deberá incluir, al menos el nombre, cargo o nombramiento\nasignado, nivel del puesto en la estructura orgánica, fecha de alta en el cargo, número telefónico,\ndomicilio para recibir correspondencia y dirección de correo electrónico oficiales;\nVII.  La remuneración bruta y neta de todas las personas servidoras públicas de base o de confianza, de\ntodas las percepciones, incluyendo sueldos, prestaciones, gratificaciones, primas, comisiones, dietas,\nbonos, estímulos, ingresos y sistemas de compensación, señalando la periodicidad de dicha\nremuneración;\nVIII.  Los gastos de representación y viáticos, así como el objeto e informe de comisión correspondiente;\nIX.  El número total de las plazas y del personal de base y confianza, especificando el total de las\nvacantes, por nivel de puesto, para cada unidad administrativa;\nX.  Las contrataciones de servicios profesionales por honorarios, señalando los nombres de las personas\nprestadoras de servicios, los servicios contratados, el monto de los honorarios y el periodo de\ncontratación;\nXI.  La versión pública de las declaraciones patrimoniales de las personas servidoras públicas en términos\nde las disposiciones jurídicas aplicables, en los sistemas habilitados para ello;\nXII.  El domicilio de la Unidad de Transparencia, además de la dirección electrónica donde podrán recibirse\nlas solicitudes para obtener la información;\nXIII.  Las convocatorias a concursos para ocupar cargos públicos y los resultados de los mismos, en los\nsistemas habilitados para ello, de conformidad con las disposiciones jurídicas aplicables;\nXIV.  Los programas, subsidios, estímulos y apoyos, en el que se deberá informar respecto de los\nprogramas de transferencia, de servicios, de infraestructura social y de subsidio, en los que se deberá\ncontener lo siguiente:\na)  Área;\nb)  Denominación del programa;\nc)  Periodo de vigencia;\nd)  Diseño, objetivos y alcances;\ne)  Metas físicas;\nf)  Población beneficiada estimada;\ng)  Monto aprobado, modificado y ejercido, así como los calendarios de su programación\npresupuestal;\nh)  Requisitos y procedimientos de acceso;\ni)  Procedimiento de queja o inconformidad ciudadana;\nj)  Mecanismos de exigibilidad;\nk)  Mecanismos de evaluación, informes de evaluación y seguimiento de recomendaciones;\nl)  Indicadores con nombre, definición, método de cálculo, unidad de medida, dimensión, frecuencia\nde medición, nombre de las bases de datos utilizadas para su cálculo;\nm)  Formas de participación social;\nn)  Articulación con otros programas sociales;\no)  Vínculo a las reglas de operación o documento equivalente;\np)  Informes periódicos sobre la ejecución y los resultados de las evaluaciones realizadas, y\nq)  Padrón de personas beneficiarias mismo que deberá contener los siguientes datos: nombre de la\npersona física o denominación social de las personas morales beneficiarias, el monto, recurso,\nbeneficio o apoyo otorgado para cada una de ellas, unidad territorial, en su caso, edad y sexo;\nXV.  Las condiciones generales de trabajo, contratos o convenios que regulen las relaciones laborales del\npersonal de base o de confianza, así como los recursos públicos económicos, en especie o donativos,\nque sean entregados a los sindicatos y ejerzan como recursos públicos;\nXVI.  La información curricular, desde el nivel de jefatura de departamento o equivalente, hasta la titularidad\ndel sujeto obligado;\nXVII.  El listado de personas servidoras públicas con sanciones administrativas firmes, especificando la\ncausa de sanción y la disposición, de conformidad a lo establecido en las disposiciones jurídicas\naplicables;\nXVIII.  Los servicios y trámites que ofrecen, incluyendo sus requisitos, en los sistemas habilitados para ello,\nde conformidad con las disposiciones jurídicas aplicables;\nXIX.  La información financiera sobre el presupuesto asignado, así como los informes del ejercicio trimestral\ndel gasto, en términos de la Ley General de Contabilidad Gubernamental y demás disposiciones\njurídicas aplicables;\nXX.  La información relativa a la deuda pública, en términos de las disposiciones jurídicas aplicables;\nXXI.  Los montos destinados a gastos relativos a comunicación social y publicidad oficial que permita\nidentificar el tipo de medio, proveedores, número de contrato y concepto o campaña;\nXXII.  Los informes de resultados de las auditorías al ejercicio presupuestal de cada sujeto obligado que se\nrealicen y, en su caso, las aclaraciones que correspondan;\nXXIII.  El resultado de la dictaminación de los estados financieros;\nXXIV.  Los montos, criterios, convocatorias y listado de personas físicas o morales a quienes, por cualquier\nmotivo, se les asigne o permita usar recursos públicos o, en los términos de las disposiciones\naplicables, realicen actos de autoridad. Asimismo, los informes que dichas personas les entreguen\nsobre el uso y destino de dichos recursos;\nXXV.  Las concesiones, contratos, convenios, permisos, licencias o autorizaciones otorgados, especificando\nlas personas titulares de aquéllos, debiendo publicarse su objeto, nombre o razón social de la persona\ntitular, vigencia, tipo, términos, condiciones, monto y modificaciones, así como si el procedimiento\ninvolucra el aprovechamiento de bienes, servicios y/o recursos públicos;\nXXVI.  Los resultados de los procedimientos de adjudicación directa, invitación restringida y licitación de\ncualquier naturaleza, incluyendo la versión pública del Expediente respectivo y de los contratos\ncelebrados, que deberá contener, por lo menos, lo siguiente:\na)  De licitaciones públicas o procedimientos de invitación restringida:\n1.  La convocatoria o invitación emitida, así como los fundamentos legales aplicados para\nllevarla a cabo;\n2.  Los nombres de las personas participantes o invitadas;\n3.  El nombre de la persona ganadora y las razones que lo justifican;\n4.  El Área solicitante y la responsable de su ejecución;\n5.  Las convocatorias e invitaciones emitidas;\n6.  Los dictámenes y fallo de adjudicación;\n7.  El contrato y, en su caso, sus anexos;\n8.  Los mecanismos de vigilancia y supervisión, incluyendo, en su caso, los estudios de\nimpacto urbano y ambiental, según corresponda;\n9.  La partida presupuestal, de conformidad con el clasificador por objeto del gasto, en el caso\nde ser aplicable;\n10.  Origen de los recursos especificando si son federales, estatales o municipales, así como el\ntipo de fondo de participación o aportación respectiva;\n11.  Los convenios modificatorios que, en su caso, sean firmados, precisando el objeto y la\nfecha de celebración;\n12.  Los informes de avance físico y financiero sobre las obras o servicios contratados;\n13.  El convenio de terminación, y\n14.  El finiquito, y\nb)  De las adjudicaciones directas:\n1.  La propuesta enviada por el participante;\n2.  Los motivos y fundamentos legales aplicados para llevarla a cabo;\n3.  La autorización del ejercicio de la opción;\n4.  En su caso, las cotizaciones consideradas, especificando los nombres de proveedores y los\nmontos;\n5.  El nombre de la persona física o moral adjudicada;\n6.  La unidad administrativa solicitante y la responsable de su ejecución;\n7.  El número, fecha, el monto del contrato y el plazo de entrega o de ejecución de los servicios\nu obra;\n8.  Los mecanismos de vigilancia y supervisión, incluyendo, en su caso, los estudios de\nimpacto urbano y ambiental, según corresponda;\n9.  Los informes de avance sobre las obras o servicios contratados;\n10.  El convenio de terminación, y\n11.  El finiquito;\nXXVII.  Los informes que generen de conformidad con las disposiciones jurídicas;\nXXVIII.  Las estadísticas que generen en cumplimiento de sus facultades, competencias o funciones;\nXXIX.  Los informes de avances programáticos o presupuestales, balances generales y su estado financiero;\nXXX.  El Padrón de proveedores y contratistas en los sistemas habilitados para ello, de conformidad con las\ndisposiciones jurídicas aplicables;\nXXXI.  Los convenios de coordinación de concertación con los sectores social y privado;\nXXXII.  El inventario de bienes muebles e inmuebles en posesión y propiedad;\nXXXIII.  Las recomendaciones emitidas por los órganos públicos del Estado mexicano u organismos\ninternacionales garantes de los derechos humanos, así como las acciones que han llevado a cabo\npara su atención;\nXXXIV.  Las resoluciones que se emitan en procesos o procedimientos seguidos en forma de juicio;\nXXXV.  Los mecanismos de participación ciudadana;\nXXXVI.  Los programas que ofrecen, incluyendo información sobre la población, objetivo y destino, así como\nlos trámites, tiempos de respuesta, requisitos y formatos para acceder a los mismos;\nXXXVII.  Las actas y resoluciones del Comité de Transparencia de los sujetos obligados;\nXXXVIII.  Las evaluaciones y encuestas que hagan los sujetos obligados a programas financiados con recursos\npúblicos;\nXXXIX.  Los estudios financiados con recursos públicos;\nXL.  El listado de personas jubiladas y pensionadas, así como el monto que reciben;\nXLI.  Los ingresos recibidos por cualquier concepto señalando el nombre de las personas responsables de\nrecibirlos, administrarlos y ejercerlos, así como su destino;\nXLII.  Las donaciones hechas a terceros en dinero o en especie;\nXLIII.  El catálogo de disposición y guía de archivo documental;\nXLIV.  Las actas de sesiones ordinarias y extraordinarias, así como las opiniones y recomendaciones que, en\nsu caso, emitan los consejos consultivos;\nXLV.  El listado de solicitudes a las empresas concesionarias de telecomunicaciones y proveedores de\nservicios o aplicaciones de Internet para la intervención de comunicaciones privadas, el acceso al\nregistro de comunicaciones y la localización geográfica en tiempo real de equipos de comunicación,\nque contenga exclusivamente el objeto, el alcance temporal y los fundamentos legales del\nrequerimiento, así como, en su caso, la mención de que cuenta con la autorización judicial\ncorrespondiente, y\nXLVI.  Cualquier otra información que sea de utilidad o se considere relevante, y la que se encuentre prevista\nen otras disposiciones jurídicas aplicables.\nLos sujetos obligados deberán informar a las Autoridades garantes de forma fundada y motivada cuáles son las\nfracciones de este artículo que les resultan aplicables, para efecto de que las Autoridades las validen.\nUna vez que cuenten con la validación de referencia los sujetos obligados procederán a publicarlas en la\nPlataforma Nacional.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo II De las Obligaciones de Transparencia Comunes","seccion_nombre":null,"id":"a38a0b6d-54b2-4908-83dc-c8af6781a8c7","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":65},{"identificador":"Artículo 66","tipo_articulo":"ordinario","contenido":"Los sujetos obligados de los Poderes Ejecutivos Federal, de las entidades federativas y municipales\no de las demarcaciones territoriales de la Ciudad de México, además de lo señalado en el artículo anterior, deberán\nponer a disposición del público y actualizar, conforme al ámbito de su competencia la información siguiente:\nI.  El Plan Nacional de Desarrollo y los planes de desarrollo de las entidades federativas, según\ncorresponda;\nII.  El presupuesto de egresos y las fórmulas de distribución de los recursos otorgados;\nIII.  Las expropiaciones decretadas y ejecutadas, que incluya, cuando menos, la fecha de expropiación, el\ndomicilio y la causa de utilidad pública y las ocupaciones superficiales;\nIV.  El nombre, denominación o razón social y clave del registro federal de contribuyentes a quienes se les\nhubiera cancelado o condonado algún crédito fiscal, así como los montos respectivos;\nV.  Los nombres de las personas a quienes se les habilitó para ejercer como corredores y notarios\npúblicos, así como sus datos de contacto, la información relacionada con el proceso de otorgamiento\nde la patente y las sanciones que se les hubieran aplicado;\nVI.  Los planes de desarrollo urbano, ordenamiento territorial y ecológico, los tipos y usos de suelo,\nlicencias de uso y construcción otorgadas por los gobiernos municipales;\nVII.  Los proyectos de disposiciones administrativas, salvo que su difusión pueda comprometer los efectos\nque se pretenden lograr con la disposición o se trate de situaciones de emergencia, en términos de lo\nprevisto en la Ley General de Mejora Regulatoria;\nVIII.  Las gacetas municipales, las cuales se deberán comprender los resolutivos y acuerdos aprobados por\nlos ayuntamientos, y\nIX.  Las actas de sesiones de cabildo, los controles de asistencia de las personas integrantes del\nAyuntamiento a las sesiones de cabildo y el sentido de votación de las y los miembros del cabildo\nsobre las iniciativas o acuerdos.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"af482582-71dd-4a6f-af39-61f207d3980b","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":66},{"identificador":"Artículo 67","tipo_articulo":"ordinario","contenido":"Los sujetos obligados del Poder Ejecutivo Federal, además de lo señalado en el artículo anterior,\ndeberán poner a disposición del público y actualizar la siguiente información:\nI.  A las fuerzas armadas:\na)  Las estadísticas sobre indultos, juicios en trámite, resoluciones ejecutorias, por delito, por grado\nde los sentenciados, por año y sentencias cumplidas, y\nb)  La estadística de las licencias de armas de fuego por tipo;\nII.  En materia hacendaria:\na)  La cartera de programas y proyectos de inversión;\nb)  Para efectos estadísticos, la lista de estímulos fiscales establecidos en las leyes fiscales,\nidentificados por acreditamientos, devoluciones, disminuciones, y deducciones, tanto de personas\nfísicas, como morales, así como su porcentaje;\nc)  El nombre, denominación o razón social y clave del registro federal de contribuyentes a quienes\nse les hubiera cancelado o condonado algún crédito fiscal, ya determinado y exigible, así como\nlos montos respectivos; debiendo vincular tales actos con los datos de identificación de\ncontribuyentes señalados en este párrafo. Asimismo, la información estadística sobre las\nexenciones previstas en las disposiciones fiscales, y\nd)  Agentes aduanales con patente autorizada;\nIII.  En materia de población:\na)  El número de centros penitenciarios o centros de tratamiento para adolescentes, indicando su\ncapacidad instalada, así como su ubicación y la función de los espacios físicos de infraestructura\ncon los que cuentan;\nb)  La estadística migratoria de entradas de extranjeros con legal estancia en México y condición de\nestancia, eventos de extranjeros presentados y devueltos; desagregada por sexo, grupo de edad\ny nacionalidad, y\nc)  La estadística de los grupos de protección a migrantes, por acciones de atención;\nIV.  En materia de seguridad pública y procuración de justicia:\na)  Para efectos estadísticos, el listado de solicitudes a las empresas concesionarias de\ntelecomunicaciones y proveedores de servicios o aplicaciones de Internet para la intervención de\ncomunicaciones privadas, el acceso al registro de comunicaciones y la localización geográfica en\ntiempo real de equipos de comunicación, que contenga exclusivamente el objeto, el alcance\ntemporal y los fundamentos legales del requerimiento, así como, en su caso, la mención de que\ncuenta con la autorización judicial correspondiente;\nb)  La estadística de los procesos de control de confianza desagregada por entidad federativa e\ninstitución;\nc)  La incidencia delictiva del fuero federal, desagregada por tipo de delito, así como el número de\nvíctimas desagregado por sexo y rango de edad;\nd)  La estadística desagregada de procesos, denuncias e investigaciones relacionadas a las\nconductas consideradas como delitos en materia de justicia para adolescentes, y\ne)  La estadística relativa a la solución de controversias realizadas a través de los mecanismos\nalternativos de solución de controversias en materia penal, desagregada por medios de\nmediación, conciliación y junta restaurativa;\nV.  En materia de política exterior:\na)  El listado de asuntos de protección a mexicanos en el exterior, que contenga sexo, rango de\nedad, país, tipo de apoyo y, en su caso, monto;\nb)  El número de constancias de suscripción del Convenio a que hace referencia la fracción I del\nartículo 27 de la Constitución Política de los Estados Unidos Mexicanos para obtener\nconcesiones para la exploración y explotación de minas y aguas en territorio nacional, indicando\nla entidad federativa y la nacionalidad de la persona solicitante y para la adquisición de bienes\ninmuebles fuera de la zona restringida, indicando la entidad federativa y la nacionalidad de la\npersona solicitante, así como el número de permisos otorgados para la constitución de\nfideicomisos, señalando la fiduciaria, nacionalidad del fideicomisario y la entidad federativa donde\nse localiza el inmueble;\nc)  El número de cartas de naturalización, identificadas por modalidad, fecha de expedición, sexo,\nrango de edad y país de origen;\nd)  Las determinaciones o resoluciones emitidas por órganos u organismos jurisdiccionales\ninternacionales en los que México haya sido parte o haya intervenido, desagregado por tribunal\nde procedencia, fecha, materia y estado de cumplimiento de la resolución;\ne)  Los tratados internacionales celebrados y en vigor para México y, en su caso, los informes de los\nmecanismos de revisión de su implementación;\nf)  Información estadística sobre candidaturas internacionales que el gobierno de México postule,\nuna vez que el desarrollo del proceso de elección haya finalizado y no actualice el supuesto a\nque se refiere la fracción II del artículo 112 de la presente Ley;\ng)  El informe sobre el desempeño de las personas representantes de México cuando presidan,\nencabecen o coordinen comisiones, consejos, comités, grupos de trabajo, asambleas, reuniones\ny conferencias de alto nivel, mecanismos ad hoc, o cualquier órgano dependiente y/o de carácter\nsubsidiario de organismos internacionales y mecanismos multilaterales;\nh)  Los votos, posicionamientos e iniciativas de México emitidos en el seno de organismos\ninternacionales y mecanismos multilaterales, así como las declaraciones y resoluciones que\nhubieren propuesto o copatrocinado, una vez que el proceso de negociación haya finalizado;\ni)  Los acuerdos interinstitucionales registrados ante la Secretaría de Relaciones Exteriores a los\nque hace referencia la Ley Sobre la Celebración de Tratados, y\nj)  Los acuerdos ejecutivos, memorandos de entendimiento, protocolos, cartas de intención y otros\ninstrumentos que, sin adoptar la categoría de Tratados, suscriben representantes del Gobierno\nFederal con representantes de otros gobiernos mediante los cuales se adquieren compromisos\njurídicamente vinculantes;\nVI.  En materia del medio ambiente y recursos naturales:\na)  El listado de áreas naturales protegidas, que contenga categoría, superficie, región y entidades\nfederativas que las comprenden;\nb)  El listado de especies mexicanas en riesgo, por grupo taxonómico;\nc)  El listado de vegetación natural, por entidad federativa, por ecosistema y por superficie;\nd)  El listado estimado de residuos, por tipo, por volumen, por entidad federativa y por año;\ne)  La disponibilidad media anual de aguas superficiales y subterráneas por región hidrológica;\nf)  El Inventario nacional de plantas municipales de potabilización y tratamiento de aguas residuales;\ng)  El listado de zonas contaminadas, por tipo de contaminante y localización;\nh)  Los tipos de vegetación forestal y de suelos, su localización, formaciones y clases, con\ntendencias y proyecciones que permitan clasificar y delimitar el estado actual de la deforestación\ny degradación, así como las zonas de conservación, protección, restauración y producción\nforestal, en relación con las cuencas hidrológicas-forestales, las regiones ecológicas, las áreas\nforestales permanentes y las áreas naturales protegidas;\ni)  La dinámica de cambio de la vegetación forestal del país, que permita conocer y evaluar las tasas\nde deforestación y las tasas de degradación y disturbio, registrando sus causas principales;\nj)  Los criterios e indicadores de sustentabilidad, deforestación y degradación de los ecosistemas\nforestales;\nk)  El listado de plantaciones comerciales forestales, que contenga su ubicación, superficie, tipo de\nespecie forestal, nivel de producción y su estatus;\nl)  Las manifestaciones y resoluciones en materia de impacto ambiental;\nm)  Información estadística sobre los árboles históricos y notables del país;\nn)  Información estadística sobre infracciones, identificando la causa que haya motivado la\ninfracción, el precepto legal infringido y la descripción de la infracción, y\no)  El índice de participación ciudadana, que contenga la categoría, ponderación, unidad de medida\ny año;\nVII.  En materia de economía:\na)  La lista de los aranceles vigentes que contenga la fracción arancelaria, la descripción, la tasa\nbase, la categoría y, en su caso, el instrumento al que atiende;\nb)  Los nombres de las personas a quienes se les habilitó para ejercer como corredores públicos, así\ncomo el domicilio de las corredurías públicas, los resultados del examen definitivo por los cuales\nse obtuvo la habilitación y las sanciones que se les hubieran aplicado;\nc)  Información estadística sobre controversias resueltas en arbitraje internacional en materia de\ncomercio exterior, desglosado por árbitro, partes, controversia y fecha de la resolución, y\nd)  La información relacionada con:\n1.  La información geológica, geofísica, geoquímica y yacimientos minerales del país;\n2.  Las coordenadas geográficas de la concesión con lados, rumbos y distancias;\n3.  Las regiones y zonas asignadas para la exploración y explotación de los minerales;\n4.  Las bases y reglas que se hayan empleado para adjudicar las concesiones y asignaciones;\n5.  El padrón de concesiones mineras;\n6.  Las cifras globales de volumen y valor de minerales concesibles; producción minera por\nEntidad y Municipio, producción minerometalúrgica por forma de presentación, producción\nde Carbón y participación en el valor de producción por Entidad, y\n7.  Los informes sobre las visitas de inspección que incluyan, cuando menos, los datos del\ntítulo de concesión, fecha de ejecución de la visita, titular de la concesión y resolución de la\nmisma;\nVIII.  En materia de agricultura, ganadería, desarrollo rural, pesca y alimentación:\na)  El listado de apoyos otorgados en materia de agricultura, ganadería, pesca o alimentación, que\ncontenga municipio, población o localidad, descripción o monto del apoyo, y el número de\nbeneficiarios distinguidos por género;\nb)  El listado de ingenios azucareros, que contenga producción, costo anual y entidad federativa;\nc)  El listado de activos y unidades económicas de pesca y acuacultura, que contenga entidad\nfederativa, embarcaciones, granjas, laboratorios y tipo de actividad;\nd)  El listado de agronegocios, empresas rurales y productores que reciben incentivos de riesgo\ncompartido, que contenga objetivo y tipo de incentivo, y\ne)  La lista de certificaciones emitidas para la importación o exportación de mercancías agrícolas,\npecuarias, acuícolas y pesqueras, desagregada por tipo de mercancía, origen, punto de ingreso,\ntránsito y destino; y en caso de negativa, las medidas sanitarias o fitosanitarias pertinentes como\nel retorno, acondicionamiento, reacondicionamiento o destrucción de la mercancía;\nIX.  En materia de comunicaciones y transportes:\na)  Información estadística sobre las aeronaves civiles mexicanas identificadas;\nb)  La incidencia de accidentes de aviación, desagregado por fecha, hora local, marca de\nnacionalidad, matrícula, tipo, marca, modelo, servicio destinado, operador aéreo, lugar del\naccidente, entidad federativa, tipo de lesión de la tripulación y pasajeros, daños a la aeronave y\ncausas probables;\nc)  Información estadística operativa correspondiente al número de vuelos, pasajeros y mercancía\ntransportada por origen-destino en operación doméstica e internacional en servicio regular y\nfletamento de manera acumulada;\nd)  Información estadística por operador aéreo respecto de número de vuelos, pasajeros y\nmercancía transportada en operación doméstica e internacional en servicio regular y fletamento\nde manera acumulada;\ne)  El listado de regiones carreteras que contemple la zona, el tipo de red carretera, el tramo\ncarretero y los puentes;\nf)  Información estadística portuaria de movimiento de carga, por mes, contenedor, puerto, tipo de\ncarga, peso, importación, exportación, tipo de tráfico, origen y destino;\ng)  Información estadística de tránsito de buques y transbordadores por mes, puerto, origen y\ndestino;\nh)  Información estadística de arribo de cruceros por mes, puerto, origen, destino y número de\npasajeros;\ni)  Información estadística de embarcaciones mexicanas matriculadas, por año de matriculación,\nedad de la embarcación y tipo, y\nj)  La información financiera y tarifaria de las redes de telecomunicaciones alámbricas e\ninalámbricas que cuenten con participación gubernamental;\nX.  En materia del sector educación y cultura:\na)  El Catálogo de los Centros de Trabajo de carácter educativo en la educación básica, media\nsuperior, superior, especial, inicial y formación para el trabajo incluyendo la información relativa a\nsu situación geográfica, tipo de servicio que proporciona y estatus de operación;\nb)  El listado del personal que presta sus servicios en los sistemas de educación pública básica,\ntecnológica y de adultos, cuyas remuneraciones se cubren con cargo a recursos públicos\nfederales;\nc)  El padrón de beneficiarios de las becas, así como los procedimientos y requisitos para\nobtenerlas, desagregado por nombre, tipo, fecha de inicio y término de la beca, área del\nconocimiento, así como el monto otorgado, y\nd)  El Catálogo de museos, que contenga el nombre, la entidad federativa, ubicación, horarios,\ntemática tratada, servicios disponibles y cuota de acceso;\nXI.  En materia de salud:\na)  El listado de los institutos o centros de salud, desagregados por nombre, especialidad, dirección y\nteléfono, y\nb)  El listado de las instituciones de beneficencia privada, que tengan por objeto la asistencia pública,\ndesagregada por nombre, ubicación, datos de contacto y tipo;\nXII.  En materia del trabajo y previsión social:\na)  El nombre y objeto de las asociaciones obreras y patronales de jurisdicción federal registradas;\nb)  El número de trabajadores asegurados en el Instituto Mexicano del Seguro Social, desagregado\npor mes, por actividad económica, entidad federativa, permanentes y eventuales; y respecto de\nestos últimos, distinguidos por urbanos y de campo, y\nc)  El número de personas beneficiadas por las actividades de capacitación, promoción al empleo,\ncolocación de trabajadores y vinculación laboral del Servicio Nacional de Empleo, por año,\nentidad federativa, oficio o profesión, género, rango de edad, ramo o industria y mecanismo de\nvinculación;\nXIII.  En materia de desarrollo agrario, territorial y urbano:\na)  El listado de núcleos agrarios identificando los datos técnicos generales y la síntesis diagnóstica\nde los mismos, y\nXIV.  En materia de turismo:\na)  Información estadística sobre las actividades económicas vinculadas al turismo, como número de\nvisitantes internacionales, flujos aéreos, flujos de cruceros y flujos carreteros;\nb)  Información correspondiente a destinos turísticos por entidad federativa, con estadísticas sobre\nactividades turísticas;\nc)  Información estadística sobre ocupación hotelera, y\nd)  El listado de prestadores de servicios turísticos.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"5e3cfcff-c633-400b-8e9f-726554881d6c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":67},{"identificador":"Artículo 68","tipo_articulo":"ordinario","contenido":"Los sujetos obligados del Poder Legislativo Federal y de las entidades federativas, además de lo\nseñalado en el artículo 65 de la presente Ley, deberán poner a disposición del público y actualizar la información\nsiguiente:\nI.  Agenda legislativa;\nII.  Gaceta Parlamentaria;\nIII.  Orden del Día;\nIV.  El Diario de Debates;\nV.  Las versiones estenográficas;\nVI.  La asistencia de cada una de sus sesiones del Pleno y de las Comisiones y Comités;\nVII.  Las iniciativas de ley o decretos, puntos de acuerdo, la fecha en que se recibió, las Comisiones a las\nque se turnaron, y los dictámenes que, en su caso, recaigan sobre las mismas;\nVIII.  Las leyes, decretos y acuerdos aprobados por el órgano legislativo;\nIX.  Las convocatorias, actas, acuerdos, listas de asistencia y votación de las Comisiones y Comités y de\nlas sesiones del Pleno, identificando el sentido del voto, en votación económica, y por cada legislador,\nen la votación nominal y el resultado de la votación por cédula, así como votos particulares y reservas\nde los dictámenes y acuerdos sometidos a consideración;\nX.  Las resoluciones definitivas sobre juicios políticos y declaratorias de procedencia;\nXI.  Las versiones públicas de la información entregada en las audiencias públicas, comparecencias y en\nlos procedimientos de designación, ratificación, elección, reelección o cualquier otro;\nXII.  Las contrataciones de servicios personales señalando el nombre del prestador del servicio, objeto,\nmonto y vigencia del contrato de los órganos de gobierno, Comisiones, Comités, Grupos\nParlamentarios y centros de estudio u órganos de investigación;\nXIII.  El informe semestral del ejercicio presupuestal del uso y destino de los recursos financieros de los\nórganos de gobierno, Comisiones, Comités, Grupos Parlamentarios y centros de estudio u órganos de\ninvestigación;\nXIV.  Los resultados de los estudios o investigaciones de naturaleza económica, política y social que\nrealicen los centros de estudio o investigación legislativa, y\nXV.  El padrón de cabilderos, de acuerdo a las disposiciones jurídicas aplicables.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"83d7bfc1-2fa0-49ea-a86c-d7ba1106cf8c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":68},{"identificador":"Artículo 69","tipo_articulo":"ordinario","contenido":"Los sujetos obligados de los Poderes Judiciales Federal y de las entidades federativas, además de\nlo señalado en el artículo 65 de la presente Ley, deberán poner a disposición del público y actualizar la información\nsiguiente:\nI.  Las tesis y ejecutorias publicadas en el Semanario Judicial de la Federación o en la Gaceta respectiva\nde cada tribunal administrativo, incluyendo, tesis jurisprudenciales y aisladas;\nII.  Las versiones públicas de todas las sentencias y laudos emitidas;\nIII.  Las versiones estenográficas, los audios y las videograbaciones de las sesiones públicas, según\ncorresponda;\nIV.  La relacionada con los procesos por medio de los cuales fueron designados los jueces y magistrados;\nV.  La lista de acuerdos que diariamente se publiquen;\nVI.  Sobre los procedimientos de designación de jueces y magistrados: la convocatoria, el registro de\naspirantes, la lista de aspirantes aceptados, la lista de los aspirantes que avanzan cada una de las\netapas, el resultado de las evaluaciones de cada etapa protegiendo, en su caso, los datos personales\nde los aspirantes y la lista de vencedores;\nVII.  Sobre los procedimientos de ratificación: la resolución definitiva donde se plasmen las razones de esa\ndeterminación;\nVIII.  Las resoluciones que impongan sanciones disciplinarias a los integrantes del Poder Judicial de la\nFederación, de conformidad a lo establecido en las disposiciones jurídicas aplicables;\nIX.  Los indicadores relacionados con el desempeño jurisdiccional que, conforme a sus funciones, deban\nestablecer, publicitando por lo menos los números de ingresos de asuntos nuevos por mes y por año,\nnúmeros de resoluciones emitidas por mes y por año, sentido general del fallo de acuerdo con la\nmateria, tiempo promedio de resolución de asuntos, número de impugnaciones recibidas por mes y por\naño, número de impugnaciones declaradas procedentes por mes y por año;\nX.  Las disposiciones de observancia general emitidas por los Plenos o sus presidentes, para el adecuado\nejercicio de sus atribuciones;\nXI.  Los votos concurrentes, minoritarios, aclaratorios, particulares o de cualquier otro tipo, que emitan los\nintegrantes de los Plenos, y\nXII.  Las resoluciones recaídas a los asuntos de contradicciones de criterios.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"3ee6b255-e90c-4956-b593-75a6fc809f4d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":69},{"identificador":"Artículo 70","tipo_articulo":"ordinario","contenido":"Los órganos autónomos, además de lo señalado en el artículo 65 de la presente Ley, deberán poner\na disposición del público y actualizar la información siguiente:\nI.  Instituto Nacional Electoral y organismos públicos locales electorales de las entidades federativas:\na)  Los listados de partidos políticos, asociaciones y agrupaciones políticas o de ciudadanos\nregistrados ante la autoridad electoral;\nb)  Los informes que presenten los partidos políticos, asociaciones y agrupaciones políticas o de\nciudadanos;\nc)  La geografía y cartografía electoral;\nd)  El registro de candidatos a cargos de elección popular;\ne)  El Catálogo de estaciones de radio y canales de televisión, pautas de transmisión, versiones de\nspots de los institutos electorales y de los partidos políticos;\nf)  Los montos de financiamiento público por actividades ordinarias, de campaña y específicas\notorgadas a los partidos políticos, asociaciones y agrupaciones políticas o de ciudadanos y\ndemás asociaciones políticas, así como los montos autorizados de financiamiento privado y los\ntopes de los gastos de campañas;\ng)  La metodología e informes sobre la publicación de encuestas por muestreo, encuestas de salida\ny conteos rápidos financiados por las autoridades electorales competentes;\nh)  La metodología e informe del Programa de Resultados Preliminares Electorales;\ni)  Los cómputos totales de las elecciones y procesos de participación ciudadana;\nj)  Los resultados y declaraciones de validez de las elecciones;\nk)  Las franquicias postales y telegráficas asignadas al partido político para el cumplimiento de sus\nfunciones;\nl)  La información sobre votos de mexicanos residentes en el extranjero;\nm)  Los dictámenes, informes y resoluciones sobre pérdida de registro y liquidación del patrimonio de\nlos partidos políticos nacionales y locales, y\nn)  El monitoreo de medios;\nII.  Organismos de protección de los derechos humanos Nacional y de las entidades federativas:\na)  El listado y las versiones públicas de las recomendaciones emitidas, su destinatario o autoridad a\nla que se recomienda y el estado que guarda su atención, incluyendo, en su caso, las minutas de\ncomparecencias de los titulares que se negaron a aceptar las recomendaciones;\nb)  Las quejas y denuncias presentadas ante las autoridades administrativas y penales respectivas,\nseñalando el estado procesal en que se encuentran y, en su caso, el sentido en el que se\nresolvieron;\nc)  Las versiones públicas del acuerdo de conciliación, previo consentimiento del quejoso;\nd)  Listado de medidas precautorias, cautelares o equivalentes, giradas una vez concluido el\nExpediente;\ne)  Toda la información con que cuente, relacionada con hechos constitutivos de violaciones graves\nde derechos humanos o delitos de lesa humanidad, una vez determinados así por la autoridad\ncompetente, incluyendo, en su caso, las acciones de reparación del daño, atención a víctimas y\nde no repetición;\nf)  La información relacionada con las acciones y resultados de defensa, promoción y protección de\nlos derechos humanos;\ng)  Las actas y versiones estenográficas de las sesiones del consejo consultivo, así como las\nopiniones que emite;\nh)  Los resultados de los estudios, publicaciones o investigaciones que realicen;\ni)  Los programas de prevención y promoción en materia de derechos humanos;\nj)  El estado que guardan los derechos humanos en el sistema penitenciario y de readaptación\nsocial del país;\nk)  El seguimiento, evaluación y monitoreo, en materia de igualdad entre mujeres y hombres;\nl)  Los programas y las acciones de coordinación con las dependencias competentes para impulsar\nel cumplimiento de tratados de los que el Estado mexicano sea parte, en materia de derechos\nhumanos, y\nm)  Los lineamientos generales de la actuación de la Comisión Nacional de los Derechos Humanos;\nIII.  El Banco de México:\na)  La estadística de la emisión de billetes y acuñación de moneda metálica;\nb)  El informe del crédito que, en su caso, otorgue al Gobierno Federal de conformidad con la Ley del\nBanco de México;\nc)  El listado de las aportaciones realizadas por el Banco de México a organismos financieros\ninternacionales de conformidad con la Ley del Banco de México;\nd)  El listado de los financiamientos otorgados a las instituciones de crédito, en forma agregada;\ne)  El importe de la reserva de activos internacionales;\nf)  La relación de sanciones impuestas por infracciones a las disposiciones emitidas por el propio\nBanco, que regulan las entidades y personas sujetas a su supervisión, excepto por aquellas\nrelacionadas con operaciones realizadas como parte de política monetaria, para lo cual deberán\nseñalar:\n1.  El nombre, denominación o razón social de la persona infractora;\n2.  El precepto legal infringido, el tipo de sanción impuesta, el monto o plazo, según\ncorresponda, así como la conducta infractora, y\n3.  El estado que guarda la resolución, indicando si se encuentra firme o bien, si es susceptible\nde ser impugnada y, en este último caso, si se ha interpuesto algún medio de defensa y su\ntipo, cuando se tenga conocimiento de tal circunstancia por haber sido debidamente\nnotificada por autoridad competente.\nEn todo caso, si la sanción impuesta se deja sin efectos por alguna autoridad competente, deberá\nigualmente publicarse tal circunstancia, y\ng)  La exposición sobre la política monetaria a seguir por el propio Banco, así como los informes\ntrimestrales sobre la inflación, la evolución económica y el comportamiento de los indicadores\neconómicos del país y la ejecución de la política monetaria y, en general, las actividades del\nBanco, que este deba enviar al Ejecutivo Federal y al Congreso de la Unión de conformidad con\nla Ley del Banco de México;\nIV.  La Fiscalía General de la República publicará la información estadística en las siguientes materias:\na)  Incidencia delictiva;\nb)  Indicadores de la procuración de justicia. En materia de carpetas de investigación y\naveriguaciones previas, deberá publicarse el número de aquéllas en las que se ejerció acción\npenal; en cuántas se decretó el no ejercicio de la acción penal; cuántas se archivaron; en cuántas\nse ejerció la facultad de atracción en materia de delitos cometidos contra la libertad de expresión;\nen cuántas se ejerció el criterio de oportunidad, y en cuántas ejerció la facultad de no investigar\nlos hechos de su conocimiento. Dicha información deberá incluir el número de denuncias o\nquerellas que le fueron interpuestas, y\nc)  Número de órdenes de presentación, aprehensión y de cateo emitidas, y\nV.  El Instituto Nacional de Estadística y Geografía:\na)  El Programa Estratégico del Sistema Nacional de Información Estadística y Geográfica y el\nresultado de su evaluación sexenal;\nb)  El Programa Nacional de Estadística y Geografía;\nc)  El Programa Anual de Estadística y Geografía;\nd)  Las inspecciones realizadas para verificar la autenticidad de la información de interés nacional,\nasí como el seguimiento que se dé a las mismas;\ne)  El Catálogo Nacional de Indicadores;\nf)  El anuario estadístico geográfico;\ng)  El Catálogo de claves de áreas geo estadísticas estatales, municipales y localidades;\nh)  Los documentos que den cuenta de la realidad demográfica y social, económica, del medio\nambiente, de gobierno, seguridad pública e impartición de justicia del país;\ni)  Las variables utilizadas para su cálculo, metadatos, comportamiento en el tiempo, a través de\ntabulados y elementos gráficos;\nj)  Las clasificaciones, catálogos, cuestionarios;\nk)  Las metodologías, documentos técnicos y proyectos estadísticos;\nl)  Los censos, encuestas, conteos de población, micro datos y macro datos, estadísticas\nexperimentales y muestras representativas de los operativos censales realizados;\nm)  La información nacional, por entidad federativa y municipios, cartografía, recursos naturales,\ntopografía, sistemas de consulta, bancos de datos, fuente, normas técnicas;\nn)  Los resultados de la ejecución del Programa Anual de Información Estadística y Geográfica\ncorrespondiente al año inmediato anterior;\no)  Un informe de las actividades de los Comités de los Subsistemas;\np)  El informe anual de actividades y sobre el ejercicio del gasto correspondiente al ejercicio\ninmediato anterior, y\nq)  El calendario anual de publicación aprobado por la Junta de Gobierno.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"24e18c46-5f24-476e-8031-72078445e000","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":70},{"identificador":"Artículo 71","tipo_articulo":"ordinario","contenido":"El sujeto obligado con facultades en materia de competencia económica, además de lo señalado en\nel artículo 65 de la presente Ley, deberá poner a disposición del público y actualizar la información siguiente:\nI.  El registro de las entrevistas que lleve a cabo con personas que representen los intereses de los\nagentes económicos para tratar asuntos de su competencia, en términos de la ley de la materia;\nII.  Las versiones públicas de las resoluciones que califiquen las excusas o recusaciones;\nIII.  El listado de los asuntos por resolver;\nIV.  Las notificaciones que deban realizarse por lista en los términos que señale las disposiciones\naplicables;\nV.  El listado de las sanciones que determine;\nVI.  Las directrices, guías, lineamientos y criterios técnicos que emita previa consulta pública;\nVII.  Los comentarios presentados por terceros en un procedimiento de consulta pública para la elaboración\ny expedición de las disposiciones regulatorias a que se refiere la Ley Federal de Competencia\nEconómica;\nVIII.  La versión pública de las evaluaciones cuantitativa y cualitativa de las aportaciones netas al bienestar\ndel consumidor que haya generado su actuación en el periodo respectivo, y\nIX.  La versión pública de los estudios, trabajos de investigación e informes generales en materia de\ncompetencia económica sobre sectores, en su caso, con las propuestas respectivas de liberalización,\ndesregulación o modificación normativa.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"8adff3ce-718f-4f79-a624-b19a923355be","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":71},{"identificador":"Artículo 72","tipo_articulo":"ordinario","contenido":"El sujeto obligado con facultades en materia de telecomunicaciones, además de lo señalado en el\nartículo 65 de la presente Ley, deberá poner a disposición del público y actualizar la información siguiente:\nI.  El registro de las entrevistas que lleve a cabo con personas que representen los intereses de los\nagentes económicos para tratar asuntos de su competencia, en términos de la ley de la materia;\nII.  Los procesos de consultas públicas, el calendario de consultas a realizar y las respuestas o\npropuestas recibidas;\nIII.  Los programas sobre bandas de frecuencias del espectro radioeléctrico para usos determinados, con\nsus correspondientes modalidades de uso y coberturas geográficas que sean materia de licitación\npública, y\nIV.  Respecto del Registro Público de Concesiones, la información pública y no clasificada de:\na)  Los títulos de concesión y las autorizaciones otorgadas, así como sus modificaciones o\nterminación de los mismos;\nb)  El Cuadro Nacional de Atribución de Frecuencias actualizado;\nc)  Los servicios asociados;\nd)  Los gravámenes impuestos a las concesiones;\ne)  Las cesiones de derechos y obligaciones de las concesiones;\nf)  Las bandas de frecuencias otorgadas en las distintas zonas del país;\ng)  Los convenios de interconexión, los de compartición de infraestructura y desagregación de la red\nlocal que realicen los concesionarios;\nh)  Las ofertas públicas que realicen los concesionarios declarados como agentes económicos\npreponderantes en los sectores de telecomunicaciones y radiodifusión o con poder sustancial;\ni)  Las tarifas al público de los servicios de telecomunicaciones ofrecidos por los concesionarios y\nlos autorizados;\nj)  Los contratos de adhesión de los concesionarios;\nk)  La estructura accionaria de los concesionarios;\nl)  Los criterios adoptados;\nm)  Los programas anuales de trabajo, los informes trimestrales de actividades, así como los estudios\ny consultas que genere;\nn)  Los lineamientos, modelos y resoluciones en materia de interconexión, así como los planes\ntécnicos fundamentales que expida;\no)  Las medidas y obligaciones específicas impuestas al o a los concesionarios que se determinen\ncomo agentes económicos con poder sustancial o preponderantes;\np)  Los resultados de las acciones de supervisión, respecto del cumplimiento de las obligaciones de\nlos concesionarios;\nq)  Las estadísticas de participación de los concesionarios, autorizados y grupo de interés\neconómico en cada mercado que determine el sujeto obligado;\nr)  Los procedimientos sancionatorios iniciados y las sanciones impuestas que hubieren quedado\nfirmes, y\ns)  Las sanciones impuestas por la Procuraduría Federal del Consumidor que hubieren quedado\nfirmes.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"934c46e2-7cd0-4d80-863c-4727636410b4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":72},{"identificador":"Artículo 73","tipo_articulo":"ordinario","contenido":"Además de lo señalado en el artículo 65, las Autoridades garantes deberán poner a disposición del\npúblico y actualizar:\nI.  La relación de observaciones y resoluciones emitidas y el seguimiento a cada una de ellas, incluyendo\nlas respuestas entregadas por los sujetos obligados a las personas solicitantes en cumplimiento de las\nresoluciones;\nII.  Los criterios orientadores que deriven de sus resoluciones;\nIII.  Los resultados de la evaluación que, en su caso, se realice al cumplimiento de la presente Ley por\nparte de los sujetos obligados;\nIV.  En su caso, las sentencias, ejecutorias o suspensiones judiciales que existan en contra de sus\nresoluciones, y\nV.  El número de quejas, denuncias y recursos de revisión dirigidos a cada uno de los sujetos obligados.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"4d3b039f-8d89-40c6-968d-7e881399aae1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":73},{"identificador":"Artículo 74","tipo_articulo":"ordinario","contenido":"Las instituciones de educación superior públicas dotadas de autonomía, además de lo señalado en\nel artículo 65 de la presente Ley, deberán poner a disposición del público y actualizar la información siguiente:\nI.  Los planes y programas de estudio según el sistema que ofrecen, ya sea escolarizado o abierto, con\nlas áreas de conocimiento, el perfil profesional de quien cursa el plan de estudios, la duración del\nprograma con las asignaturas, su valor en créditos, formas y costos de titulación;\nII.  La información relacionada con sus procedimientos administrativos;\nIII.  La remuneración de los profesores, incluyendo los estímulos, prestaciones, gratificaciones, primas,\ncomisiones, dietas, bonos, ingresos y sistemas de compensación, señalando la periodicidad de dicha\nremuneración, nivel y monto;\nIV.  La lista con los profesores con licencia o en año sabático;\nV.  El listado de las becas y apoyos que otorgan, así como los procedimientos y requisitos para\nobtenerlos;\nVI.  Las convocatorias de los concursos de oposición;\nVII.  La información relativa a los procesos de selección de los consejos;\nVIII.  El resultado de las evaluaciones del cuerpo docente;\nIX.  El listado de instituciones incorporadas y requisitos de incorporación;\nX.  El número de personas estudiantes inscritas, desglosado por área de conocimiento, tipo de sistema de\nestudios, modalidad de estudio, grado académico y denominación o título del grado, y\nXI.  El número de personas egresadas y tituladas, desglosado por área de conocimiento, tipo de sistema\nde estudios, modalidad de estudio, grado académico y denominación o título del grado.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"33064c92-6931-499d-a2b3-3fe9002184ce","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":74},{"identificador":"Artículo 75","tipo_articulo":"ordinario","contenido":"Los partidos políticos nacionales y locales, las agrupaciones políticas nacionales y las personas\nmorales constituidas en asociación civil creadas por los ciudadanos que pretendan postular su candidatura\nindependiente, según corresponda, además de lo señalado en el artículo 65 de la presente Ley, deberán poner a\ndisposición del público y actualizar la información siguiente:\nI.  El padrón de afiliados o militantes de los partidos políticos, que contendrá, exclusivamente: apellidos,\nnombre o nombres, fecha de afiliación y entidad de residencia;\nII.  Los acuerdos y resoluciones de los órganos de dirección de los partidos políticos;\nIII.  Los convenios de participación entre partidos políticos con organizaciones de la sociedad civil;\nIV.  Los contratos y convenios para la adquisición o arrendamiento de bienes y servicios;\nV.  Las minutas de las sesiones de los partidos políticos;\nVI.  Los responsables de los órganos internos de finanzas de los partidos políticos;\nVII.  Las organizaciones sociales adherentes o similares a algún partido político;\nVIII.  Los montos de las cuotas ordinarias y extraordinarias aportadas por sus militantes;\nIX.  Los montos autorizados de financiamiento privado, así como una relación de los nombres de los\naportantes vinculados con los montos aportados;\nX.  El listado de aportantes a las precampañas y campañas políticas;\nXI.  El acta de la asamblea constitutiva;\nXII.  Las demarcaciones electorales en las que participen;\nXIII.  Los tiempos que les corresponden en canales de radio y televisión;\nXIV.  Los documentos básicos, plataformas electorales y programas de gobierno y los mecanismos de\ndesignación de los órganos de dirección en sus respectivos ámbitos;\nXV.  El directorio de sus órganos de dirección nacionales, estatales, municipales, de las demarcaciones\nterritoriales y, en su caso, regionales, delegacionales y distritales;\nXVI.  El tabulador de remuneraciones que perciben los integrantes de los órganos a que se refiere la\nfracción anterior y de los demás funcionarios partidistas, que deberá vincularse con el directorio y\nestructura orgánica, así como cualquier persona que reciba ingresos por parte del partido político,\nindependientemente de la función que desempeñe dentro o fuera del partido;\nXVII.  El currículo con fotografía reciente de todos los precandidatos y candidatos a cargos de elección\npopular, con el cargo al que se postula, el distrito electoral y la entidad federativa;\nXVIII.  El currículo de los dirigentes a nivel nacional, estatal y municipal;\nXIX.  Los convenios de frente, coalición o fusión que celebren o de participación electoral que realicen con\nagrupaciones políticas nacionales;\nXX.  Las convocatorias que emitan para la elección de sus dirigentes o la postulación de sus candidatos a\ncargos de elección popular y, en su caso, el registro correspondiente;\nXXI.  Los responsables de los procesos internos de evaluación y selección de candidatos a cargos de\nelección popular, conforme a su normatividad interna;\nXXII.  Informes sobre el gasto del financiamiento público ordinario recibido para la capacitación, promoción y\ndesarrollo del liderazgo político de las mujeres;\nXXIII.  Las resoluciones dictadas por los órganos de control;\nXXIV.  Los montos de financiamiento público otorgados mensualmente, en cualquier modalidad, a sus\nórganos nacionales, estatales, municipales y demarcaciones territoriales, así como los descuentos\ncorrespondientes a sanciones;\nXXV.  El estado de situación financiera y patrimonial; el inventario de los bienes inmuebles de los que sean\npropietarios, así como los anexos que formen parte integrante de los documentos anteriores;\nXXVI.  Las resoluciones que emitan sus órganos disciplinarios de cualquier nivel, una vez que hayan causado\nestado;\nXXVII.  Los nombres de sus representantes ante la autoridad electoral competente;\nXXVIII.  Los mecanismos de control y supervisión aplicados a los procesos internos de selección de\ncandidatos;\nXXIX.  El listado de fundaciones, asociaciones, centros o institutos de investigación o capacitación o cualquier\notro que reciban apoyo económico de los partidos políticos, así como los montos destinados para tal\nefecto, y\nXXX.  Las resoluciones que dicte la autoridad electoral competente respecto de los informes de ingresos y\ngastos.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"559e5a4e-8b15-4e8f-bb25-777d8b06a96f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":75},{"identificador":"Artículo 76","tipo_articulo":"ordinario","contenido":"Los fideicomisos, fondos públicos, mandatos o cualquier contrato análogo, además de lo señalado\nen el artículo 65 de la presente Ley, deberán poner a disposición del público y mantener actualizada y accesible, en\nlo que resulte aplicable a cada contrato, la información siguiente:\nI.  El nombre de la persona servidora pública y de la persona física o moral que represente al\nfideicomitente, al fiduciario y al fideicomisario;\nII.  La unidad administrativa responsable del fideicomiso;\nIII.  El monto total, el uso y destino del patrimonio fideicomitido, distinguiendo las aportaciones públicas y\nfuente de los recursos, los subsidios, donaciones, transferencias, excedentes, inversiones realizadas y\naportaciones o subvenciones que reciban;\nIV.  El saldo total al cierre del ejercicio fiscal, sin perjuicio de los demás informes que deban presentarse en\nlos términos de las disposiciones aplicables;\nV.  Las modificaciones que, en su caso, sufran los contratos o decretos de constitución del fideicomiso o\ndel fondo público;\nVI.  El padrón de beneficiarios, en su caso;\nVII.  Causas por las que, en su caso, se inicie el proceso de constitución o extinción del fideicomiso o fondo\npúblico, especificando, de manera detallada, los recursos financieros destinados para tal efecto, y\nVIII.  Los contratos de obras, adquisiciones y servicios que involucren recursos públicos del fideicomiso, así\ncomo los honorarios derivados de los servicios y operaciones que realice la institución de crédito o la\nfiduciaria.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"dc2c4841-92b2-46dd-85e9-1fcf503ce809","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":76},{"identificador":"Artículo 77","tipo_articulo":"ordinario","contenido":"Las autoridades administrativas y jurisdiccionales en materia laboral deberán poner a disposición del\npúblico y mantener actualizada y accesible, la información de los sindicatos siguiente:\nI.  Los documentos del registro de los sindicatos, que deberán contener, entre otros:\na)  El domicilio;\nb)  Número de registro;\nc)  Nombre del sindicato;\nd)  Nombre de los integrantes del comité ejecutivo y comisiones que ejerzan funciones de vigilancia;\ne)  Fecha de vigencia del comité ejecutivo;\nf)  Número de socios;\ng)  Centro de trabajo al que pertenezcan, y\nh)  Central a la que pertenezcan, en su caso;\nII.  Las tomas de nota;\nIII.  El estatuto;\nIV.  Las actas de asamblea;\nV.  Los reglamentos interiores de trabajo;\nVI.  Los contratos colectivos, incluyendo el tabulador, convenios y las condiciones generales de trabajo, y\nVII.  Todos los documentos contenidos en el Expediente de registro sindical y de contratos colectivos de\ntrabajo.\nLas autoridades administrativas y jurisdiccionales en materia laboral deberán expedir copias de los documentos\nque obren en los expedientes de los registros a las personas solicitantes que los requieran, de conformidad con el\nprocedimiento de acceso a la información.\nPor lo que se refiere a los documentos que obran en el expediente de registro de las asociaciones, únicamente\nestará clasificada como información confidencial, los domicilios de los trabajadores señalados en los padrones de\nsocios.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"57f99495-a9f7-45f0-8df6-5e3735d39837","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":77},{"identificador":"Artículo 78","tipo_articulo":"ordinario","contenido":"Los sindicatos que reciban y ejerzan recursos públicos deberán mantener actualizada y accesible, de\nforma impresa para consulta directa y en los respectivos sitios de Internet, la información aplicable del artículo 65 de\nesta Ley, la señalada en el artículo anterior y la siguiente:\nI.  Contratos y convenios entre sindicatos y autoridades;\nII.  El directorio del Comité Ejecutivo, y\nIII.  La relación detallada de los recursos públicos económicos, en especie, bienes o donativos que reciban\ny el informe detallado del ejercicio y destino final de los recursos públicos que ejerzan.\nLos sujetos obligados que asignen recursos públicos a los sindicatos, deberán habilitar un espacio en sus páginas\nde Internet para que estos cumplan con sus obligaciones de transparencia y dispongan de la infraestructura\ntecnológica para el uso y acceso a la Plataforma Nacional. En todo momento el sindicato será el responsable de la\npublicación, actualización y accesibilidad de la información.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"20301ca3-ec9e-43b2-a69b-4511cdd879dd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":78},{"identificador":"Artículo 79","tipo_articulo":"ordinario","contenido":"Para determinar la información adicional que publicarán todos los sujetos obligados de manera\nobligatoria, las Autoridades garantes deberán:\nI.  Solicitar a los sujetos obligados que, atendiendo a los lineamientos emitidos por el Sistema Nacional,\nremitan el listado de información que consideren de interés público;\nII.  Revisar el listado que remitió el sujeto obligado con base en las funciones, atribuciones y\ncompetencias que las disposiciones jurídicas aplicables le otorguen, y\nIII.  Determinar el catálogo de información que el sujeto obligado deberá publicar como obligación de\ntransparencia.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo III De las Obligaciones Específicas","seccion_nombre":null,"id":"fcb8a1d7-e8e8-40b5-8fff-5f9dd9a0f401","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":79},{"identificador":"Artículo 80","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes, determinarán los casos en que las personas físicas o morales que reciban\ny ejerzan recursos públicos o realicen actos de autoridad, cumplirán con las obligaciones de transparencia y acceso a\nla información directamente o a través de los sujetos obligados que les asignen dichos recursos o, en los términos de\nlas disposiciones aplicables, realicen actos de autoridad.\nLos sujetos obligados correspondientes deberán enviar a las Autoridades garantes un listado de las personas\nfísicas o morales a los que, por cualquier motivo, asignaron recursos públicos o, en los términos que establezcan las\ndisposiciones aplicables, ejercen actos de autoridad.\nPara resolver sobre el cumplimento de lo señalado en el párrafo anterior, las Autoridades garantes tomarán en\ncuenta si realiza una función gubernamental, el nivel de financiamiento público, el nivel de regulación e\ninvolucramiento gubernamental y si el gobierno participó en su creación.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo IV De las Obligaciones Específicas de las Personas Físicas o Morales que Reciben y Ejercen Recursos Públicos o Ejercen Actos de Autoridad","seccion_nombre":null,"id":"05039906-df3f-449f-95ea-da0b8452f108","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":80},{"identificador":"Artículo 81","tipo_articulo":"ordinario","contenido":"Para determinar la información que deberán hacer pública las personas físicas o morales que\nreciben y ejercen recursos públicos o realizan actos de autoridad, las Autoridades garantes deberán:\nI.  Solicitar a las personas físicas o morales que, atendiendo a los lineamientos emitidos por el Sistema\nNacional, remitan el listado de información que consideren de interés público;\nII.  Revisar el listado que remitió la persona física o moral en la medida en que reciban y ejerzan recursos\no realicen actos de autoridad que las disposiciones jurídicas aplicables le otorguen, y\nIII.  Determinar las obligaciones de transparencia que deben cumplir y los plazos para ello.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo IV De las Obligaciones Específicas de las Personas Físicas o Morales que Reciben y Ejercen Recursos Públicos o Ejercen Actos de Autoridad","seccion_nombre":null,"id":"c037e2eb-3fdc-402e-802b-36890ac53d09","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":81},{"identificador":"Artículo 82","tipo_articulo":"ordinario","contenido":"Los sujetos obligados del sector energético, además de la información señalada en el artículo 65 de\nesta Ley, deberán poner a disposición del público y, en su caso, mantener actualizada la siguiente información:\nI.  La Agencia Nacional de Seguridad Industrial y de Protección al Medio Ambiente del Sector\nHidrocarburos:\na)  Los Sistemas de Administración de Seguridad Industrial, Seguridad Operativa y Protección al\nMedio Ambiente establecidos en la Ley de la Agencia Nacional de Seguridad Industrial y de\nProtección al Medio Ambiente del Sector Hidrocarburos;\nb)  El código de conducta de su personal;\nc)  Los planes, lineamientos y procedimientos para prevenir y atender situaciones de emergencia;\nd)  Las autorizaciones en materia de impacto y riesgo ambiental del sector hidrocarburos, incluyendo\nlos anexos;\ne)  Las autorizaciones para emitir olores, gases o partículas sólidas o líquidas a la atmósfera por las\nInstalaciones del sector hidrocarburos;\nf)  Las autorizaciones en materia de residuos peligrosos en el sector hidrocarburos;\ng)  Las autorizaciones de las propuestas de remediación de sitios contaminados y la liberación de los\nmismos al término de la ejecución del programa de remediación correspondiente;\nh)  Las autorizaciones en materia de residuos de manejo especial;\ni)  El registro de planes de manejo de residuos y programas para la instalación de sistemas\ndestinados a su recolección, acopio, almacenamiento, transporte, tratamiento, valorización y\ndisposición final;\nj)  Las autorizaciones de cambio de uso del suelo en terrenos forestales;\nk)  Los permisos para la realización de actividades de liberación al ambiente de organismos\ngenéticamente modificados para biorremediación de sitios contaminados con hidrocarburos;\nl)  Las disposiciones, emitidas en el ámbito de sus atribuciones, para los asignatarios,\npermisionarios y contratistas;\nm)  Los procedimientos para el registro, investigación y análisis de incidentes y accidentes;\nn)  Los estándares técnicos nacionales e internacionales en materia de protección al medio\nambiente;\no)  Las coberturas financieras contingentes frente a daños o perjuicios que se pudieran generar;\np)  Las previsiones a que deberá sujetarse la operación de fuentes fijas donde se desarrollen\nactividades del sector que emitan contaminantes atmosféricos;\nq)  Las especificaciones y los requisitos del control de emisiones de contaminantes procedentes de\nlas fuentes fijas del sector hidrocarburos;\nr)  El pago de viáticos y pasajes, viajes, servicios, financiamiento o aportaciones económicas que se\nrelacionen directa o indirectamente con el ejercicio de sus atribuciones o funciones;\ns)  Los recursos depositados en los fideicomisos que se generen derivado del saldo remanente de\nlos ingresos propios excedentes, así como el uso y destino de los mismos;\nt)  Los registros de las audiencias celebradas, que deberán contener el lugar, fecha y hora de inicio\ny conclusión de las mismas, así como los nombres completos de las personas que estuvieron\npresentes y los temas tratados;\nu)  Los volúmenes de uso de agua, la situación geográfica y todos los productos químicos utilizados\nen el fluido de fracturación por pozo, del sector hidrocarburos;\nv)  Los volúmenes de agua de desecho recuperada por pozo, los volúmenes de agua inyectados en\nlos pozos de aguas residuales y las emisiones de metano a la atmósfera por pozo, del sector\nhidrocarburos;\nw)  Los programas de manejo de agua utilizada en la fracturación hidráulica, y\nx)  Las acciones de seguridad industrial y de seguridad operativa para el control de residuos, y la\ninstalación de sistemas destinados a su recolección, acopio, almacenamiento, transporte,\ntratamiento, valorización y disposición final;\nII.  La dependencia encargada de conducir y supervisar la política energética del país:\na)  Información estadística sobre la producción de hidrocarburos y el total de las reservas,\nincluyendo reportes de estimación y estudios de evaluación o cuantificación y certificación;\nb)  Los criterios utilizados para la contratación y términos contractuales del comercializador de\nhidrocarburos del Estado;\nc)  La relación entre producción de hidrocarburos y reservas totales, así como la información sobre\nlos recursos contingentes y prospectivos;\nd)  La información geológica, geofísica, petrofísica, petroquímica y demás, que se obtenga de las\nactividades de reconocimiento y exploración superficial, así como de la exploración y extracción\nde hidrocarburos en todo el territorio nacional, terrestre y marino, siempre y cuando no tenga el\ncarácter de confidencial en términos de la Ley del Sector Hidrocarburos;\ne)  La información relativa a los contratos para la exploración y extracción incluyendo las cláusulas,\nlos resultados y estadísticas de los procesos de licitación, las bases y reglas de los procesos de\nlicitación que se hayan empleado para adjudicar dichos contratos y el número de los contratos\nque se encuentran;\nf)  La información relacionada con la administración técnica, costos y supervisión de los contratos y\nel volumen de producción de hidrocarburos por Contrato o asignación;\ng)  Los criterios utilizados para la selección del socio de Petróleos Mexicanos u otra empresa pública\ndel Estado, tratándose de la migración de una asignación a un contrato de exploración y\nextracción de hidrocarburos, en términos de la Ley del Sector Hidrocarburos;\nh)  Los volúmenes de producción por tipo de hidrocarburo, desagregados por activo, área contractual\ny asignación, y campo;\ni)  El volumen y las especificaciones de calidad del petróleo, gas natural, petrolíferos y\npetroquímicos transportados y almacenados en los sistemas permisionados, incluido el Sistema\nde Transporte y Almacenamiento Nacional Integrado de Gas Natural;\nj)  Lista de los permisionarios que importen petróleo, gas natural y petrolíferos, el volumen y\nespecificaciones de calidad de los mismos, el permisionario encargado de la importación y el\ndestino de su comercialización;\nk)  Los resultados y estadísticas de las actividades de los gestores de sistemas integrados;\nl)  La capacidad utilizada y disponible en las instalaciones de almacenamiento y sistemas de ductos\nde los permisionarios;\nm)  Las estadísticas relacionadas con el transporte, el almacenamiento, la distribución y el expendio\nal público de gas natural, petrolíferos y petroquímicos, a nivel nacional;\nn)  El número de permisos y autorizaciones que haya otorgado y se encuentren vigentes, así como\nsus términos y condiciones, en su caso;\no)  La energía eléctrica transportada y distribuida en la Red Nacional de Transmisión y en las Redes\nGenerales de Distribución;\np)  Los contratos que versen sobre el uso, goce o afectación de terrenos, bienes o derechos\nnecesarios para realizar el Servicio Público de Transmisión y Distribución de Energía Eléctrica y\npara la construcción de plantas de generación de energía eléctrica;\nq)  Los niveles de generación de energía eléctrica;\nr)  La información de permisos en materia de importación y exportación de energía eléctrica, y\ns)  Las bases del mercado eléctrico;\nIII.  Las empresas públicas del Estado y sus empresas públicas subsidiarias:\na)  La información relacionada con el procedimiento y la designación de los consejeros y directivos\nde las filiales y subsidiarias;\nb)  Las donaciones o cualquier aportación que realice la Comisión Federal de Electricidad o\nPetróleos Mexicanos, así como sus empresas subsidiarias, a personas físicas o morales,\ncualquiera que sea su naturaleza jurídica o su objeto, con excepción de aquellas cuya divulgación\npueda afectar una ventaja competitiva de la empresa pública del Estado, sus empresas públicas\nsubsidiarias o sus empresas filiales;\nc)  La versión pública de su Plan de Negocios;\nd)  El contrato colectivo de trabajo y el reglamento del personal de confianza;\ne)  Los tabuladores aprobados, desglosando todos los conceptos y montos de las percepciones\nordinarias y extraordinarias;\nf)  Las erogaciones globales que realicen por concepto de jubilaciones y pensiones, así como las\nactualizaciones del costo actuarial de su pasivo laboral;\ng)  Los préstamos o créditos, así como las tasas aplicables, que en su caso otorguen a sus\ntrabajadores, jubilados y pensionados;\nh)  Los apoyos para el desempeño de la función y las demás erogaciones que, en su caso, se\notorguen a los trabajadores, que no forman parte de su remuneración;\ni)  Los montos mensuales erogados por contrataciones temporales o eventuales;\nj)  Los lineamientos aprobados por los Consejos de Administración de la Comisión Federal de\nElectricidad y de Petróleos Mexicanos, con base en los cuales se otorgan y cubran los conceptos\ndescritos en los incisos anteriores;\nk)  Los montos erogados en el trimestre que corresponda por cada uno de los conceptos descritos\nen los incisos e) a i) anteriores;\nl)  Las garantías o cualquier otro instrumento financiero necesario para contar con coberturas\nfinancieras contingentes frente a daños o perjuicios que se pudieran generar por sus actividades;\nm)  Los estándares, funciones y responsabilidades de los encargados de los Sistemas de\nAdministración de Seguridad Industrial, Seguridad Operativa y Protección al Medio Ambiente, así\ncomo la información que comprende el artículo 13 de la Ley de la Agencia Nacional de Seguridad\nIndustrial y de Protección al Medio Ambiente del Sector Hidrocarburos;\nn)  Respecto a sus filiales:\n1.  Las inversiones realizadas por parte de la empresa pública o sus subsidiarias;\n2.  El monto de las utilidades y dividendos recibidos, y\n3.  Las actas constitutivas y actas de las reuniones de consejo en las que participan, sin\nimportar su participación accionaria;\no)  La deuda que adquieran las empresas públicas del Estado, y\np)  Las bases, reglas, ingresos, costos, límites de costos, contraprestaciones, contribuciones y pagos\nrealizados y de los procedimientos que lleve a cabo cuando celebren con las personas\nparticulares o entre ellas, contratos, asignaciones, permisos, alianzas, sociedades y demás actos\nen materia de las actividades de planeación y control del sistema eléctrico nacional; del servicio\npúblico de transmisión y distribución de energía eléctrica; y de exploración y extracción de\nhidrocarburos. Lo anterior, siempre y cuando no se trate de información que implique secreto\ncomercial o cuya divulgación pudiera representarles una desventaja competitiva frente a sus\ncompetidores;\nIV.  El Fondo Mexicano del Petróleo para la Estabilización y el Desarrollo:\na)  Las transferencias realizadas a la Tesorería de la Federación y a los fondos señalados en el\nCapítulo III de la Ley del Fondo Mexicano del Petróleo para la Estabilización y el Desarrollo;\nb)  El monto de los honorarios fiduciarios pagados por el Fondo, así como los conceptos y pagos\nrealizados por el fiduciario con cargo a dichos honorarios;\nc)  El monto de los pagos realizados al comercializador del Estado de cada contrato de extracción de\nhidrocarburos a que se refiere la Ley de Ingresos sobre Hidrocarburos, y\nd)  El total de los ingresos derivados de asignaciones y contratos para la exploración y extracción de\nhidrocarburos, y\nV.  La Secretaría de Energía:\na)  Los lineamientos a que deberá sujetarse la adquisición, uso, goce o afectación de terrenos,\nbienes o derechos que se pacten entre propietarios o titulares y los asignatarios o contratistas,\npara realizar las actividades de exploración y extracción de hidrocarburos;\nb)  Los dictámenes técnicos que sustenten el establecimiento de zonas de salvaguarda en términos\nde la Ley del Sector Hidrocarburos;\nc)  Los dictámenes que sustenten la instrucción para unificar campos o yacimientos nacionales de\nextracción de hidrocarburos;\nd)  La información relativa a los procedimientos de consulta previa, libre e informada necesarios para\ntomar en cuenta los intereses y derechos de los pueblos y comunidades indígenas y\nafromexicanas en los que se desarrollen proyectos de la industria eléctrica y de los\nhidrocarburos, así como en materia de energía geotérmica;\ne)  Los lineamientos técnicos conforme a los cuales se deberán realizar las licitaciones para\nseleccionar al socio de las empresas públicas del Estado en los casos de asignaciones que\nmigren a contratos para la exploración y extracción de hidrocarburos;\nf)  Los permisos de exploración y las concesiones de explotación de recursos geotérmicos, y\ng)  La meta de generación limpia de electricidad.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo V De las Obligaciones Específicas en Materia Energética","seccion_nombre":null,"id":"0bed4857-5e6f-4a34-88f7-21959d199e4f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":82},{"identificador":"Artículo 83","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes, en su ámbito de competencia, vigilarán que las obligaciones de\ntransparencia que publiquen los sujetos obligados cumplan con lo dispuesto en esta Ley.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VI De la Verificación de las Obligaciones de Transparencia","seccion_nombre":null,"id":"d8c2da33-425d-49a3-b27d-13f575f876ba","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":83},{"identificador":"Artículo 84","tipo_articulo":"ordinario","contenido":"Las determinaciones que emitan las Autoridades garantes deberán establecer los requerimientos,\nrecomendaciones u observaciones que formulen y los términos y plazos en los que los sujetos obligados deberán\natenderlas. El incumplimiento a los requerimientos formulados, será motivo para aplicar las medidas de apremio, sin\nperjuicio de las sanciones a que haya lugar.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VI De la Verificación de las Obligaciones de Transparencia","seccion_nombre":null,"id":"0a946132-85ae-49e1-b956-099a596203bb","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":84},{"identificador":"Artículo 85","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes vigilarán el debido cumplimiento a las obligaciones de transparencia que\npubliquen los sujetos obligados con lo dispuesto en los artículos 63 a 80 de esta Ley y demás disposiciones jurídicas\naplicables.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VI De la Verificación de las Obligaciones de Transparencia","seccion_nombre":null,"id":"15de49c0-3c48-467e-a72d-6fb446296955","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":85},{"identificador":"Artículo 86","tipo_articulo":"ordinario","contenido":"Las acciones de vigilancia a que se refiere este Capítulo se realizarán de manera oficiosa por las\nAutoridades garantes, a través de la revisión aleatoria o muestral y periódica al portal de Internet de los sujetos\nobligados o a la Plataforma Nacional.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VI De la Verificación de las Obligaciones de Transparencia","seccion_nombre":null,"id":"a4b94738-aa88-5e2d-be46-574a622d9b56","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":86},{"identificador":"Artículo 87","tipo_articulo":"ordinario","contenido":"La verificación que realice las Autoridades garantes se sujetará a lo siguiente:\nI.  Constatar que la información esté completa, publicada y actualizada en tiempo y forma;\nII.  Emitir un dictamen en el que podrá determinar que el sujeto obligado cumple o no con lo establecido\npor esta Ley y demás disposiciones. En el supuesto de que determine que no da cumplimiento\nformulará los requerimientos que procedan a efecto de que el sujeto obligado subsane las\ninconsistencias detectadas e informe la atención a los requerimientos dentro de un plazo no mayor a\nveinte días, y\nIII.  Verificar el cumplimiento a la resolución una vez transcurrido el plazo y si considera que fueron\natendidos los requerimientos del dictamen, emitirá un acuerdo de cumplimiento.\nLas Autoridades garantes podrán solicitar los informes complementarios al sujeto obligado que requiera para\nallegarse de los elementos de juicio que consideren necesarios para llevar a cabo la verificación.\nCuando las Autoridades garantes consideren que existe un incumplimiento total o parcial de la determinación, le\nnotificará, por conducto de la Unidad de Transparencia, al superior jerárquico de la persona servidora pública\nresponsable de dar cumplimiento, para el efecto de que, en un plazo no mayor a diez días, dé cumplimiento a los\nrequerimientos del dictamen.\nEn caso de que las Autoridades garantes consideren que subsiste el incumplimiento total o parcial de la\nresolución, en un plazo no mayor a cinco días impondrán las medidas de apremio o sanciones, conforme a lo\nestablecido por esta Ley.\nAdicionalmente, las Autoridades garantes podrán emitir recomendaciones a los sujetos obligados, a fin de\nprocurar que los formatos en que se publique la información, sea de mayor utilidad.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VI De la Verificación de las Obligaciones de Transparencia","seccion_nombre":null,"id":"38c70ed4-52d2-4bc8-98de-fb5ea0be5499","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":87},{"identificador":"Artículo 88","tipo_articulo":"ordinario","contenido":"Cualquier persona podrá denunciar ante las Autoridades garantes la falta de publicación de las\nobligaciones de transparencia previstas en los artículos 63 a 80 de esta Ley y demás disposiciones jurídicas\naplicables, en sus respectivos ámbitos de competencia.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"0099e4bb-3397-4e76-bd8a-e73374459f7e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":88},{"identificador":"Artículo 89","tipo_articulo":"ordinario","contenido":"El procedimiento de la denuncia se integra por las siguientes etapas:\nI.  Presentación de la denuncia ante las Autoridades garantes;\nII.  Solicitud por parte de las Autoridades garantes de un informe al sujeto obligado;\nIII.  Resolución de la denuncia, y\nIV.  Ejecución de la resolución de la denuncia.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"3c6f6682-8977-4650-b1f1-f2bdf0ed32f9","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":89},{"identificador":"Artículo 90","tipo_articulo":"ordinario","contenido":"La denuncia por incumplimiento a las obligaciones de transparencia deberá cumplir, al menos, los\nsiguientes requisitos:\nI.  Nombre del sujeto obligado denunciado;\nII.  Descripción clara y precisa del incumplimiento denunciado;\nIII.  La persona denunciante podrá adjuntar los medios de prueba que estime necesarios para respaldar el\nincumplimiento denunciado;\nIV.  En caso de que la denuncia se presente:\na)  Por escrito, la persona denunciante deberá señalar el domicilio en la jurisdicción que corresponda\no la dirección de correo electrónico para recibir notificaciones, y\nb)  Por medios electrónicos, se entenderá que se acepta que las notificaciones se efectúen por el\nmismo medio en el que la presento. En caso de que no se señale domicilio o dirección de correo\nelectrónico o se señale un domicilio fuera de la jurisdicción respectiva, las notificaciones, aún las\nde carácter personal, se practicarán a través de los estrados físicos de la Autoridad garante\ncompetente, y\nV.  Opcionalmente el nombre de la persona denunciante.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"09589150-7cd4-4c82-9697-ddc0d0e05364","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":90},{"identificador":"Artículo 91","tipo_articulo":"ordinario","contenido":"La denuncia podrá presentarse de la forma siguiente:\nI.  Por medio electrónico:\na)  A través de la Plataforma Nacional, o\nb)  Por correo electrónico, dirigido a la dirección electrónica que al efecto se establezca, o\nII.  Por escrito libre, presentado físicamente, ante la Unidad de Transparencia de las Autoridades\ngarantes, según corresponda.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"f6e463f2-caff-4569-8e42-87d67fb0acb2","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":91},{"identificador":"Artículo 92","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes pondrán a disposición de las personas particulares el formato de denuncia\ncorrespondiente, a efecto de que estos, si así lo deciden, puedan utilizarlos. Asimismo, las personas particulares\npodrán optar por un escrito libre, conforme a lo previsto en esta Ley.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"3c50426b-d511-4c0a-8284-ff4092a37811","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":92},{"identificador":"Artículo 93","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes, en el ámbito de sus competencias, deben resolver sobre la admisión de la\ndenuncia, dentro de los tres días siguientes a su recepción.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"b1f35da0-2cbf-400b-940f-ad2ce756daa1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":93},{"identificador":"Artículo 94","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes podrán prevenir a la persona denunciante dentro del plazo de tres días\ncontados a partir del día hábil siguiente al de su recepción, para que en el plazo de tres días subsane lo siguiente:\nI.  En su caso, exhiba ante la Autoridad garante los documentos con los que acredite la personalidad del\nrepresentante de una persona física o moral, en caso de aplicar, o\nII.  Aclare o precise alguno de los requisitos o motivos de la denuncia.\nEn el caso de que no se desahogue la prevención en el periodo establecido para tal efecto en este artículo,\ndeberá desecharse la denuncia, dejando a salvo los derechos de la persona denunciante para volver a presentar la\nmisma.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"902470b6-cf90-4e5d-acd9-e3f23e3bca90","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":94},{"identificador":"Artículo 95","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes podrán determinar la improcedencia de la denuncia cuando el\nincumplimiento hubiera sido objeto de una denuncia anterior en la que se resolvió instruir la publicación de las\nobligaciones de transparencia previstas en la presente Ley.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"1a527205-6c03-43a1-a978-d038c7687ee9","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":95},{"identificador":"Artículo 96","tipo_articulo":"ordinario","contenido":"Si la denuncia no versa sobre presuntos incumplimientos a las obligaciones de transparencia\nestablecidas en la presente Ley, o se refiere al ejercicio del derecho de acceso a la información o al trámite del\nrecurso de revisión, la Autoridad garante dictará un acuerdo de desechamiento y, en su caso, dejará a salvo los\nderechos de la persona promovente para que los haga valer por la vía y forma correspondientes.\nLas Autoridades garantes, en el ámbito de sus competencias, deben notificar al sujeto obligado la denuncia\ndentro de los siete días siguientes a su admisión.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"19eb45d4-3910-49a2-b5b7-1e8b86050fa1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":96},{"identificador":"Artículo 97","tipo_articulo":"ordinario","contenido":"El sujeto obligado debe enviar a las Autoridades garantes correspondientes, un informe con\njustificación respecto de los hechos o motivos de la denuncia dentro de los cinco días siguientes a la notificación\nanterior.\nLas Autoridades garantes, pueden realizar las verificaciones virtuales que procedan, así como solicitar los\ninformes complementarios al sujeto obligado que requiera, para allegarse de los elementos de juicio que considere\nnecesarios para resolver la denuncia.\nEn el caso de informes complementarios, el sujeto obligado deberá responder a los mismos, en el término de tres\ndías siguientes a la notificación correspondiente.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"1c9978bf-764b-4a27-a391-0337f808ad37","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":97},{"identificador":"Artículo 98","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes, en el ámbito de sus competencias deben resolver la denuncia, dentro de\nlos veinte días siguientes al término del plazo en que el sujeto obligado debe presentar su informe o, en su caso, los\ninformes complementarios.\nLa resolución debe ser fundada y motivada e invariablemente debe pronunciarse sobre el cumplimiento de la\npublicación de la información por parte del sujeto obligado.\nDe existir incumplimiento, se deberá señalar el artículo y fracción de la presente Ley, así como los preceptos\ncontenidos en las disposiciones jurídicas aplicables que se incumplen, especificar los criterios y metodología del\nestudio y las razones por las cuales se considera que hay un incumplimiento, y establecer las medidas necesarias\npara garantizar la publicidad de la información respecto de la cual exista un incumplimiento, determinando así un\nplazo para que el sujeto obligado cumpla e informe sobre ello.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"4d64a9f3-499a-4151-88b0-cbcdb201094e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":98},{"identificador":"Artículo 99","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes, en el ámbito de sus competencias, deben notificar la resolución a la\npersona denunciante y al sujeto obligado, dentro de los tres días siguientes a su emisión.\nLas resoluciones que emitan las Autoridades garantes, a que se refiere este Capítulo, son definitivas e\ninatacables para los sujetos obligados.\nEl particular podrá impugnar la resolución por la vía del juicio de amparo que corresponda, en los términos de la\nlegislación aplicable. Los juicios de amparo serán sustanciados por jueces y tribunales especializados que para el\nefecto determine el Órgano de Administración Judicial en los términos del artículo 94 de la Constitución Política de\nlos Estados Unidos Mexicanos.\nEl sujeto obligado deberá cumplir con la resolución en un plazo de quince días, a partir del día siguiente al en que\nse le notifique la misma.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"223ec517-42d5-46c7-afda-c399cf0195b8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":99},{"identificador":"Artículo 100","tipo_articulo":"ordinario","contenido":"Transcurrido el plazo señalado en el artículo anterior, el sujeto obligado deberá informar a la\nAutoridad garante correspondiente sobre el cumplimento de la resolución.\nLas Autoridades garantes verificarán el cumplimiento a la resolución; si fuera procedente se emitirá un acuerdo de\ncumplimiento y se ordenará el cierre del Expediente.\nCuando las Autoridades garantes consideren que existe un incumplimiento total o parcial de la resolución, le\nnotificarán, por conducto de la Unidad de Transparencia del sujeto obligado, al superior jerárquico de la persona\nservidora pública responsable de dar cumplimiento, para el efecto de que, en un plazo no mayor a siete días, se dé\ncumplimiento a la resolución.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"d5f99988-ca39-402c-9522-427d60642db1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":100},{"identificador":"Artículo 101","tipo_articulo":"ordinario","contenido":"En caso de que las Autoridades garantes consideren que subsiste el incumplimiento total o parcial\nde la resolución, en un plazo no mayor a cinco días posteriores al aviso de incumplimiento al superior jerárquico de la\npersona servidora pública responsable del mismo, se emitirá un acuerdo de incumplimiento y, en su caso, se\nimpondrán las medidas de apremio o determinaciones que resulten procedentes.","titulo_nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","capitulo_nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","seccion_nombre":null,"id":"3e2d9e8b-a17e-43e3-9fda-5601c8819a3f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":101},{"identificador":"Artículo 102","tipo_articulo":"ordinario","contenido":"La clasificación es el proceso mediante el cual el sujeto obligado determina que la información en\nsu poder, actualiza alguno de los supuestos de reserva o confidencialidad, de conformidad con lo dispuesto en el\npresente Título.\nLos supuestos de reserva o confidencialidad previstos en las leyes deberán ser acordes con las bases, principios\ny disposiciones establecidos en esta Ley y, en ningún caso, podrán contravenirla.\nLas personas titulares de las áreas de los sujetos obligados serán los responsables de clasificar la información,\nde conformidad con lo dispuesto en la presente Ley y leyes de las entidades federativas.\nLos sujetos obligados deberán aplicar, de manera restrictiva y limitada, las excepciones al derecho de acceso a la\ninformación previstas en el presente Título y deberán acreditar su procedencia, sin ampliar las excepciones o\nsupuestos de reserva o confidencialidad previstos en las leyes, de conformidad con lo establecido en esta Ley.\nLos sujetos obligados no podrán emitir acuerdos de carácter general ni particular que clasifiquen documentos o\nexpedientes como reservados, ni clasificar documentos antes de dar respuesta a una solicitud de acceso a la\ninformación. La clasificación podrá establecerse de manera parcial o total de acuerdo al contenido de la información\ndel Documento y deberá estar acorde con la actualización de los supuestos definidos en el presente Título como\ninformación clasificada.\nLa clasificación de información reservada se realizará conforme a un análisis caso por caso, mediante la\naplicación de la prueba de daño.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo I De las Disposiciones Generales de la Clasificación y Desclasificación de la Información","seccion_nombre":null,"id":"f0f851a1-7f13-4c8e-b757-670d4dbbe4dc","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":102},{"identificador":"Artículo 103","tipo_articulo":"ordinario","contenido":"La clasificación de la información se llevará a cabo en el momento en que:\nI.  Se reciba una solicitud de acceso a la información;\nII.  Se determine mediante resolución de autoridad competente, o\nIII.  Se generen versiones públicas para dar cumplimiento a las obligaciones de transparencia previstas en\nesta Ley.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo I De las Disposiciones Generales de la Clasificación y Desclasificación de la Información","seccion_nombre":null,"id":"99092ec8-2303-408d-b85f-22ea46006149","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":103},{"identificador":"Artículo 104","tipo_articulo":"ordinario","contenido":"Los Documentos clasificados como reservados serán públicos cuando:\nI.  Se extingan las causas que dieron origen a su clasificación;\nII.  Expire el plazo de clasificación;\nIII.  Exista resolución de una autoridad competente que determine que existe una causa de interés público\nque prevalece sobre la reserva de la información;\nIV.  El Comité de Transparencia considere pertinente la desclasificación, de conformidad con lo señalado\nen el presente Título, y\nV.  Se trate de información que esté relacionada con violaciones graves a derechos humanos o delitos de\nlesa humanidad.\nLa información clasificada como reservada de conformidad con el artículo 112 de esta Ley podrá permanecer con\ntal carácter hasta por un periodo de cinco años. El periodo de reserva correrá a partir de la fecha en que se clasifica\nel documento.\nExcepcionalmente, los sujetos obligados, con la aprobación de su Comité de Transparencia, podrán ampliar el\nperiodo de reserva hasta por un plazo de cinco años adicionales, siempre y cuando justifiquen que subsisten las\ncausas que dieron origen a su clasificación, mediante la aplicación de una prueba de daño.\nPara los casos previstos por la fracción II de este artículo, cuando se trate de información cuya publicación pueda\nocasionar la destrucción o inhabilitación de la infraestructura de carácter estratégico para la provisión de bienes o\nservicios públicos, o bien se refiera a las circunstancias expuestas en la fracción IV del artículo 112 de esta Ley y que\na juicio de un sujeto obligado sea necesario ampliar nuevamente el periodo de reserva de la información, el Comité\nde Transparencia respectivo deberá hacer la solicitud correspondiente a la Autoridad garante, debidamente fundada\ny motivada, aplicando la prueba de daño y señalando el plazo de reserva, por lo menos con tres meses de\nanticipación al vencimiento del periodo.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo I De las Disposiciones Generales de la Clasificación y Desclasificación de la Información","seccion_nombre":null,"id":"835cbfae-ac55-4f11-b1e6-eb8bbdfd8ade","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":104},{"identificador":"Artículo 105","tipo_articulo":"ordinario","contenido":"Cada área del sujeto obligado elaborará un índice de los expedientes clasificados como\nreservados, por Área responsable de la información y tema.\nEl índice deberá elaborarse semestralmente y publicarse en Formatos Abiertos al día siguiente de su elaboración.\nDicho índice deberá indicar el Área que generó la información, el nombre del Documento, si se trata de una reserva\ncompleta o parcial, la fecha en que inicia y finaliza la reserva, su justificación, el plazo de reserva y, en su caso, las\npartes del Documento que se reservan y si se encuentra en prórroga.\nEn ningún caso el índice será considerado como información reservada.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo I De las Disposiciones Generales de la Clasificación y Desclasificación de la Información","seccion_nombre":null,"id":"8a17ec89-d891-4b24-b420-26970d432f34","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":105},{"identificador":"Artículo 106","tipo_articulo":"ordinario","contenido":"En los casos en que se niegue el acceso a la información, por actualizarse alguno de los supuestos\nde clasificación, el Comité de Transparencia deberá confirmar, modificar o revocar la decisión.\nPara motivar la clasificación de la información y la ampliación del plazo de reserva, se deberán señalar las\nrazones, motivos o circunstancias especiales que llevaron al sujeto obligado a concluir que el caso particular se\najusta al supuesto previsto por la norma legal invocada como fundamento. Además, el sujeto obligado deberá, en\ntodo momento, aplicar una prueba de daño.\nTratándose de aquella información que actualice los supuestos de clasificación, deberá señalarse el plazo al que\nestará sujeto la reserva.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo I De las Disposiciones Generales de la Clasificación y Desclasificación de la Información","seccion_nombre":null,"id":"295358b8-b004-4b6f-a5dd-05239035ff08","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":106},{"identificador":"Artículo 107","tipo_articulo":"ordinario","contenido":"En la aplicación de la prueba de daño, el sujeto obligado deberá justificar que:\nI.  La divulgación de la información representa un riesgo real, demostrable e identificable de perjuicio\nsignificativo al interés público o a la seguridad nacional;\nII.  El riesgo de perjuicio que supondría la divulgación supera el interés público general de que se difunda,\ny\nIII.  La limitación se adecua al principio de proporcionalidad y representa el medio menos restrictivo\ndisponible para evitar el perjuicio.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo I De las Disposiciones Generales de la Clasificación y Desclasificación de la Información","seccion_nombre":null,"id":"26a2525c-e30c-48da-bafa-9248840684df","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":107},{"identificador":"Artículo 108","tipo_articulo":"ordinario","contenido":"Los sujetos obligados deberán aplicar, de manera restrictiva y limitada, las excepciones al derecho\nde acceso a la información prevista en el presente Título y deberán acreditar su procedencia.\nLa carga de la prueba para justificar toda negativa de acceso a la información, por actualizarse cualquiera de los\nsupuestos de reserva previstos, corresponderá a los sujetos obligados.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo I De las Disposiciones Generales de la Clasificación y Desclasificación de la Información","seccion_nombre":null,"id":"b81170f0-422b-439e-abb3-3dee1171c48c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":108},{"identificador":"Artículo 109","tipo_articulo":"ordinario","contenido":"Los Documentos clasificados parcial o totalmente deberán llevar una leyenda que indique tal\ncarácter, la fecha de la clasificación, el fundamento legal y, en su caso, el periodo de reserva.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo I De las Disposiciones Generales de la Clasificación y Desclasificación de la Información","seccion_nombre":null,"id":"2c860f87-ccbd-4f67-b122-9eaabb569140","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":109},{"identificador":"Artículo 110","tipo_articulo":"ordinario","contenido":"Los lineamientos generales que emita el Sistema Nacional en materia de clasificación de la\ninformación reservada y confidencial y, para la elaboración de versiones públicas, serán de observancia obligatoria\npara los sujetos obligados.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo I De las Disposiciones Generales de la Clasificación y Desclasificación de la Información","seccion_nombre":null,"id":"2f0359de-e818-4129-b5f0-e8894f795a65","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":110},{"identificador":"Artículo 111","tipo_articulo":"ordinario","contenido":"Los Documentos clasificados serán debidamente custodiados y conservados, conforme a las\ndisposiciones aplicables y, en su caso, a los lineamientos que expida el Sistema Nacional.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo I De las Disposiciones Generales de la Clasificación y Desclasificación de la Información","seccion_nombre":null,"id":"5d35a148-81a9-415b-8dda-378cfaf6d9cb","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":111},{"identificador":"Artículo 112","tipo_articulo":"ordinario","contenido":"Como información reservada podrá clasificarse aquella cuya publicación:\nI.  Comprometa la seguridad nacional, la seguridad pública, la defensa nacional o la paz social;\nII.  Pueda menoscabar la conducción de las negociaciones y relaciones internacionales;\nIII.  Se entregue al Estado mexicano expresamente con ese carácter o el de confidencial por otro u otros\nsujetos de derecho internacional, excepto cuando se trate de violaciones graves de derechos humanos\no delitos de lesa humanidad de conformidad con el derecho internacional;\nIV.  Pueda afectar la efectividad de las medidas adoptadas en relación con las políticas en materia\nmonetaria, cambiaria o del sistema financiero del país; pueda poner en riesgo la estabilidad de las\ninstituciones financieras susceptibles de ser consideradas de riesgo sistémico o del sistema financiero\ndel país, pueda comprometer la seguridad en la provisión de moneda nacional al país, o pueda\nincrementar el costo de operaciones financieras que realicen los sujetos obligados del sector público\nfederal;\nV.  Pueda poner en riesgo la vida, seguridad o salud de una persona física;\nVI.  Obstruya las actividades de verificación, inspección y auditoría relativas al cumplimiento de las leyes o\nafecte la recaudación de contribuciones;\nVII.  Pueda causar daño u obstruya la prevención o persecución de los delitos, altere el proceso de\ninvestigación de las carpetas de investigación, afecte o vulnere la conducción o los derechos del\ndebido proceso en tanto no hayan quedado firmes o afecte la administración de justicia o la seguridad\nde una persona denunciante, querellante o testigo, así como sus familias, en los términos de las\ndisposiciones jurídicas aplicables;\nVIII.  La que contenga las opiniones, recomendaciones o puntos de vista que formen parte del proceso\ndeliberativo de las personas servidoras públicas, hasta en tanto no sea adoptada la decisión definitiva,\nla cual deberá estar documentada;\nIX.  Obstruya los procedimientos para fincar responsabilidad a las personas servidoras públicas, en tanto la\nresolución administrativa no haya causado estado;\nX.  Afecte los derechos del debido proceso;\nXI.  Afecte o vulnere la conducción de los expedientes judiciales o de los procedimientos administrativos\nseguidos en forma de juicio, incluidos los de denuncias, inconformidades, responsabilidades\nadministrativas y resarcitorias o afecte la administración de justicia o la seguridad de una persona\ndenunciante, querellante o testigo, así como sus familias, en los términos de las disposiciones jurídicas\naplicables en tanto no hayan causado estado;\nXII.  Se encuentre contenida dentro de las investigaciones de hechos que la ley señale como delitos y se\ntramiten ante el Ministerio Público;\nXIII.  El daño que pueda producirse con la publicación de la información sea mayor que el interés público de\nconocer la información de referencia, siempre que esté directamente relacionado con procesos o\nprocedimientos administrativos o judiciales que no hayan quedado firmes;\nXIV.  Cuando se trate de información sobre estudios y proyectos cuya divulgación pueda causar daños al\ninterés del Estado o suponga un riesgo para su realización, siempre que esté directamente relacionado\ncon procesos o procedimientos administrativos o judiciales que no hayan quedado firmes;\nXV.  Se refiera a programas del Gobierno Federal para salvaguardar materiales o instalaciones nucleares;\nXVI.  Ponga en riesgo el funcionamiento o integridad de los sistemas tecnológicos, energéticos, espaciales,\nsatelitales, de telecomunicaciones o de defensa desarrollados, adquiridos u operados por el Gobierno\nFederal de forma directa o indirecta, así como instalaciones, infraestructuras, proyectos, planes o\nservicios de protección estratégicos, prioritarios o de defensa, y\nXVII.  Las que por disposición expresa de una ley tengan tal carácter, siempre que sean acordes con las\nbases, principios y disposiciones establecidos en esta Ley y no la contravengan; así como las previstas\nen tratados internacionales.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo II De la Información Reservada","seccion_nombre":null,"id":"31493012-65cb-4fcd-8aa8-21526c29ae47","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":112},{"identificador":"Artículo 113","tipo_articulo":"ordinario","contenido":"Las causales de reserva previstas en el artículo anterior se deberán fundar y motivar, a través de la\naplicación de la prueba de daño a la que se hace referencia en el presente Título.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo II De la Información Reservada","seccion_nombre":null,"id":"75823113-bf62-44c7-9aeb-c1d0b2e4e40e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":113},{"identificador":"Artículo 114","tipo_articulo":"ordinario","contenido":"No podrá invocarse el carácter de reservado cuando:\nI.  Se trate de violaciones graves de derechos humanos o delitos de lesa humanidad, o\nII.  Se trate de información relacionada con actos de corrupción acreditados de acuerdo con las leyes\naplicables.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo II De la Información Reservada","seccion_nombre":null,"id":"2ef2dc4f-9019-4595-89a2-6a282c9f0b59","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":114},{"identificador":"Artículo 115","tipo_articulo":"ordinario","contenido":"Se considera información confidencial la que contiene datos personales concernientes a una\npersona física identificada o identificable.\nLa información confidencial no estará sujeta a temporalidad alguna y sólo podrán tener acceso a ella los titulares\nde la misma, sus representantes y las personas servidoras públicas facultadas para ello.\nSe considera como información confidencial de personas físicas o morales: los secretos bancario, fiduciario,\nindustrial, comercial, fiscal, bursátil y postal, cuya titularidad corresponda a las personas particulares, sujetos de\nderecho internacional o a sujetos obligados cuando no involucren el ejercicio de recursos públicos.\nAsimismo, será información confidencial aquella que presenten las personas particulares a los sujetos obligados,\nsiempre que tengan el derecho a ello, de conformidad con lo dispuesto por las leyes o los tratados internacionales.\nSe considera confidencial el pronunciamiento sobre la existencia o inexistencia de quejas, denuncias y/o\nprocedimientos administrativos seguidos en contra de personas servidoras públicas y particulares que se encuentren\nen trámite o no hayan concluido con una sanción firme.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo III De la Información Confidencial","seccion_nombre":null,"id":"2e58f1cf-436a-4288-99a7-d090bea60b79","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":115},{"identificador":"Artículo 116","tipo_articulo":"ordinario","contenido":"Los sujetos obligados que se constituyan como fideicomitentes, fideicomisarios o fiduciarios en\nfideicomisos que involucren recursos públicos, no podrán clasificar, por ese solo supuesto, la información relativa al\nejercicio de estos, como secreto bancario o fiduciario, sin perjuicio de las demás causales de clasificación que prevé\nla presente Ley.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo III De la Información Confidencial","seccion_nombre":null,"id":"bddf3c10-f247-4e85-9ad8-9098d9f029a3","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":116},{"identificador":"Artículo 117","tipo_articulo":"ordinario","contenido":"Los sujetos obligados que se constituyan como personas usuarias o como institución bancaria en\noperaciones que involucren recursos públicos, no podrán clasificar, por ese solo supuesto, la información relativa al\nejercicio de estos, como secreto bancario, sin perjuicio de las demás causales de clasificación que prevé la presente\nLey.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo III De la Información Confidencial","seccion_nombre":null,"id":"4b8491df-fb2c-497e-b130-0b4b985666c3","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":117},{"identificador":"Artículo 118","tipo_articulo":"ordinario","contenido":"Los sujetos obligados que se constituyan como contribuyentes o como autoridades en materia\ntributaria, no podrán clasificar la información relativa al ejercicio de recursos públicos como secreto fiscal.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo III De la Información Confidencial","seccion_nombre":null,"id":"96569f33-bf2e-43e8-9723-6bed033ed38f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":118},{"identificador":"Artículo 119","tipo_articulo":"ordinario","contenido":"Para que los sujetos obligados puedan permitir el acceso a información confidencial requieren\nobtener el consentimiento de las personas particulares titulares de la información.\nNo se requerirá el consentimiento del titular de la información confidencial cuando:\nI.  La información se encuentre en registros públicos o fuentes de acceso público;\nII.  Por ley tenga el carácter de pública;\nIII.  Exista una orden judicial;\nIV.  Por razones de seguridad nacional y salubridad general, o para proteger los derechos de terceros, se\nrequiera su publicación, o\nV.  Cuando se transmita entre sujetos obligados y entre estos y los sujetos de derecho internacional, en\ntérminos de los tratados y los acuerdos interinstitucionales, siempre y cuando la información se utilice\npara el ejercicio de facultades propias de los mismos.\nPara efectos de la fracción IV del presente artículo, la Autoridad garante, debidamente fundada y motivada,\ndeberá aplicar la prueba de interés público. Además, se deberá corroborar una conexión patente entre la información\nconfidencial y un tema de interés público y la proporcionalidad entre la invasión a la intimidad ocasionada por la\ndivulgación de la información confidencial y el interés público de la información.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo III De la Información Confidencial","seccion_nombre":null,"id":"886f3487-8b0e-4b92-85b7-79e9c72c1ff3","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":119},{"identificador":"Artículo 120","tipo_articulo":"ordinario","contenido":"Cuando un documento o expediente contenga partes o secciones reservadas o confidenciales, los\nsujetos obligados a través de sus áreas, para efectos de atender una solicitud de información, deberán elaborar una\nversión pública en la que se testen las partes o secciones clasificadas, indicando su contenido de manera genérica,\nfundando y motivando su clasificación, en términos de lo que determine el Sistema Nacional.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo IV De las Versiones Públicas","seccion_nombre":null,"id":"dfbf695e-9ed2-4a1f-8780-e7804b299dcb","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":120},{"identificador":"Artículo 121","tipo_articulo":"ordinario","contenido":"Los sujetos obligados deberán procurar que los sistemas o medios empleados para eliminar la\ninformación en las versiones públicas no permitan la recuperación o visualización de la misma.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo IV De las Versiones Públicas","seccion_nombre":null,"id":"b4da8fe8-9a9d-4499-af38-099d75e921f0","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":121},{"identificador":"Artículo 122","tipo_articulo":"ordinario","contenido":"En las versiones públicas no podrá omitirse la información que constituya obligaciones de\ntransparencia previstas en la presente Ley.","titulo_nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","capitulo_nombre":"Capítulo IV De las Versiones Públicas","seccion_nombre":null,"id":"7d8a77f1-53e6-481f-99ba-5664ee71351c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":122},{"identificador":"Artículo 123","tipo_articulo":"ordinario","contenido":"Las Unidades de Transparencia de los sujetos obligados deberán garantizar las medidas y\ncondiciones de accesibilidad para que toda persona pueda ejercer el derecho de acceso a la información, mediante\nsolicitudes de información y deberá apoyar a la persona solicitante en la elaboración de las mismas, de conformidad\ncon las bases establecidas en el presente Título.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"712f46ce-96e2-4737-9b53-51133a43fae8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":123},{"identificador":"Artículo 124","tipo_articulo":"ordinario","contenido":"Cualquier persona por sí misma o a través de su representante, podrá presentar solicitud de acceso\na información ante la Unidad de Transparencia, a través de la Plataforma Nacional, en la oficina u oficinas\ndesignadas para ello, vía correo electrónico, correo postal, mensajería, telégrafo, verbalmente o cualquier medio\naprobado por el Sistema Nacional.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"58f60d33-639e-4530-9695-3bcc0054febf","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":124},{"identificador":"Artículo 125","tipo_articulo":"ordinario","contenido":"Tratándose de solicitudes de acceso a información formuladas mediante la Plataforma Nacional, se\nasignará automáticamente un número de folio, con el que las personas solicitantes podrán dar seguimiento a sus\nrequerimientos. En los demás casos, la Unidad de Transparencia tendrá que registrar y capturar la solicitud de\nacceso en la Plataforma Nacional dentro de los cinco días posteriores a su recepción, y deberá enviar el acuse de\nrecibo a la persona solicitante, en el que se indique la fecha de recepción, el folio que corresponda y los plazos de\nrespuesta aplicables.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"f28536b8-0830-4374-bdbd-e61dfae2799d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":125},{"identificador":"Artículo 126","tipo_articulo":"ordinario","contenido":"Para presentar una solicitud no se podrán exigir mayores requisitos que los siguientes:\nI.  Medio para recibir notificaciones;\nII.  La descripción de la información solicitada, y\nIII.  La modalidad en la que prefiere se otorgue el acceso a la información, la cual podrá ser verbal,\nsiempre y cuando sea para fines de orientación, mediante consulta directa, mediante la expedición de\ncopias simples o certificadas o la reproducción en cualquier otro medio, incluidos los electrónicos.\nEn su caso, la persona solicitante señalará el formato accesible o la lengua indígena en la que se requiera la\ninformación de acuerdo a lo señalado en la presente Ley.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"c73db6c4-e7fe-4bd6-9ff4-04a883d9578e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":126},{"identificador":"Artículo 127","tipo_articulo":"ordinario","contenido":"Cuando el particular presente su solicitud por medios electrónicos a través de la Plataforma\nNacional, se entenderá que acepta que las notificaciones le sean efectuadas por dicho sistema, salvo que señale un\nmedio distinto para efectos de las notificaciones.\nLas respuestas que otorguen las Unidades de Transparencia a través de la Plataforma Nacional, se consideran\nválidas, aun cuando no cuenten con firma autógrafa.\nEn el caso de solicitudes recibidas en otros medios, en las que las personas solicitantes no proporcionen un\ndomicilio o medio para recibir la información o, en su defecto, no haya sido posible practicar la notificación, se\nnotificará por estrados en la oficina de la Unidad de Transparencia.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"9f635bb4-df65-4696-b460-e01c7b1c3b59","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":127},{"identificador":"Artículo 128","tipo_articulo":"ordinario","contenido":"Los términos de todas las notificaciones previstas en esta Ley, empezarán a correr al día siguiente\nal que se practiquen.\nCuando los plazos fijados por esta Ley sean en días, estos se entenderán como hábiles.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"474ce9e5-3ad9-434d-b65d-87bc9589ad42","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":128},{"identificador":"Artículo 129","tipo_articulo":"ordinario","contenido":"De manera excepcional, cuando, de forma fundada y motivada, así lo determine el sujeto obligado,\nen aquellos casos en que la información solicitada que ya se encuentre en su posesión implique análisis, estudio o\nprocesamiento de documentos cuya entrega o reproducción sobrepase las capacidades técnicas del sujeto obligado\npara cumplir con la solicitud, en los plazos establecidos para dichos efectos, se podrán poner a disposición de la\npersona solicitante los documentos en consulta directa, salvo la información clasificada.\nEn todo caso se facilitará su copia simple o certificada, así como su reproducción por cualquier medio disponible\nen las instalaciones del sujeto obligado previo pago de derechos o que, en su caso, aporte la persona solicitante.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"9abccbac-8fb7-454e-9cb2-6a161cc2c38b","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":129},{"identificador":"Artículo 130","tipo_articulo":"ordinario","contenido":"Cuando los detalles proporcionados en la solicitud de acceso a información resulten insuficientes,\nincompletos o sean erróneos, para localizar la información solicitada, la Unidad de Transparencia podrá requerir a la\npersona solicitante, por una sola vez y dentro de un plazo que no podrá exceder de cinco días, contados a partir de la\npresentación de la solicitud, para que, en un término de hasta diez días, indique otros elementos o corrija los datos\nproporcionados.\nEste requerimiento interrumpirá el plazo de respuesta establecido en el artículo 134 de la presente Ley, por lo que\ncomenzará a computarse nuevamente al día siguiente del desahogo por parte del particular. En este caso, el sujeto\nobligado atenderá la solicitud en los términos en que fue desahogado el requerimiento de información adicional.\nLa solicitud se tendrá por no presentada cuando las personas solicitantes no atiendan el requerimiento de\ninformación adicional. En el caso de requerimientos parciales no desahogados, se tendrá por presentada la solicitud\npor lo que respecta a los contenidos de información que no formaron parte del requerimiento.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"ace51420-05d4-49c6-865f-4713fb793617","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":130},{"identificador":"Artículo 131","tipo_articulo":"ordinario","contenido":"Los sujetos obligados deberán otorgar los documentos que se encuentren en sus archivos o que\nestén obligados a documentar de acuerdo con sus facultades, competencias o funciones, conforme a las\ncaracterísticas físicas o electrónicas de la información con la que cuenten o del lugar donde se encuentre, sin\nnecesidad de elaborar documentos adicionales para atender las solicitudes de acceso a información.\nTratándose de solicitudes de acceso a información cuyo contenido constituya una consulta, el sujeto obligado\npodrá dar una interpretación para verificar si dentro de los documentos con los que cuentan atendiendo a las\ncaracterísticas señaladas en el párrafo anterior puede darse atención, sin que se entienda que debe emitir\npronunciamientos específicos, explicaciones y/o argumentaciones sobre supuestos hipotéticos.\nEn el caso de que la información solicitada consista en bases de datos se deberá privilegiar la entrega de la\nmisma en formatos abiertos.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"b921237f-e535-4877-a2b2-4b276bab8c57","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":131},{"identificador":"Artículo 132","tipo_articulo":"ordinario","contenido":"Cuando la información requerida por la persona solicitante ya esté disponible al público en medios\nimpresos, tales como libros, compendios, trípticos, registros públicos, en formatos electrónicos disponibles en\nInternet o en cualquier otro medio, se le hará saber por el medio requerido por la persona solicitante la fuente, el\nlugar y la forma en que puede consultar, reproducir o adquirir dicha información en un plazo no mayor a cinco días.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"fe616ea3-4941-4a88-ac72-125df6d65110","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":132},{"identificador":"Artículo 133","tipo_articulo":"ordinario","contenido":"Las Unidades de Transparencia deberán garantizar que las solicitudes se turnen a todas las áreas\ncompetentes que cuenten con la información o deban tenerla de acuerdo a sus facultades, competencias y\nfunciones, con el objeto de que realicen una búsqueda exhaustiva y razonable de la información solicitada.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"ce2d4d54-1047-483b-88dd-1d289e23f931","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":133},{"identificador":"Artículo 134","tipo_articulo":"ordinario","contenido":"La respuesta a la solicitud deberá ser notificada a la persona interesada en el menor tiempo\nposible, que no podrá exceder de veinte días, contados a partir del día siguiente a la presentación de aquélla.\nExcepcionalmente, el plazo referido en el párrafo anterior podrá ampliarse hasta por diez días más, siempre y\ncuando se justifiquen de manera fundada y motivada las razones ante el Comité de Transparencia, y este emita la\nresolución respectiva, la cual deberá notificarse a la persona solicitante antes de su vencimiento.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"04dfdf13-0386-49d1-9c9e-6e9ebe54d625","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":134},{"identificador":"Artículo 135","tipo_articulo":"ordinario","contenido":"El acceso se dará en la modalidad de entrega y, en su caso, de envío elegidos por la persona\nsolicitante. Cuando la información no pueda entregarse o enviarse en la modalidad elegida, el sujeto obligado deberá\njustificar el impedimento, y notificar al particular la disposición de la información en todas las modalidades que\npermita el documento de que se trate, procurando reducir, en todo momento, los costos de entrega.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"b0b98b1a-9f10-4cf8-aa57-7589f7f39773","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":135},{"identificador":"Artículo 136","tipo_articulo":"ordinario","contenido":"Los sujetos obligados establecerán la forma y términos en que darán trámite interno a las\nsolicitudes en materia de acceso a la información.\nLa elaboración de versiones públicas, cuya modalidad de reproducción o envío tenga un costo, procederá una\nvez que se acredite el pago respectivo.\nAnte la falta de respuesta a una solicitud en el plazo previsto y en caso de que proceda el acceso, los costos de\nreproducción y envío correrán a cargo del sujeto obligado.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"ba066c3c-4433-4bf0-9bf0-3e427b50a98d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":136},{"identificador":"Artículo 137","tipo_articulo":"ordinario","contenido":"La Unidad de Transparencia tendrá disponible la información solicitada, durante un plazo mínimo\nde sesenta días, contado a partir de que la persona solicitante hubiere realizado, en su caso, el pago respectivo, el\ncual deberá efectuarse en un plazo no mayor a treinta días.\nTranscurridos dichos plazos, los sujetos obligados darán por concluida la solicitud y procederán, de ser el caso, a\nla destrucción del material en el que se reprodujo la información. Serán aplicables estas mismas disposiciones, en el\ncumplimiento a los recursos de revisión.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"d4f9e2ba-4e4f-41b1-a232-bc8e9c544ce7","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":137},{"identificador":"Artículo 138","tipo_articulo":"ordinario","contenido":"Cuando las Unidades de Transparencia determinen la notoria incompetencia por parte de los\nsujetos obligados, dentro del ámbito de su aplicación, para atender la solicitud de acceso a la información, deberán\ncomunicarlo a la persona solicitante, dentro de los tres días posteriores a la recepción de la solicitud y, en caso de\npoderlo determinar, señalar a la persona solicitante el o los sujetos obligados competentes.\nSi los sujetos obligados son competentes para atender parcialmente la solicitud de acceso a la información,\ndeberán dar respuesta respecto de dicha parte.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"735e4645-e3a9-5bf5-b020-31389339132d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":138},{"identificador":"Artículo 139","tipo_articulo":"ordinario","contenido":"En caso de que los sujetos obligados consideren que la información deba ser clasificada, se\nsujetará a lo siguiente:\nEl área deberá remitir la solicitud, así como un escrito en el que funde y motive la clasificación al Comité de\nTransparencia, mismo que deberá resolver para:\nI.  Confirmar la clasificación;\nII.  Modificar la clasificación y otorgar total o parcialmente el acceso a la información, y\nIII.  Revocar la clasificación y conceder el acceso a la información.\nEl Comité de Transparencia podrá tener acceso a la información que esté en poder del área correspondiente, de\nla cual se haya solicitado su clasificación.\nLa resolución del Comité de Transparencia será notificada a la persona interesada en el plazo de respuesta a la\nsolicitud que establece el artículo 134 de la presente Ley.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"1c437d71-b3d3-45cd-b22c-3b51db9294bd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":139},{"identificador":"Artículo 140","tipo_articulo":"ordinario","contenido":"Cuando la información no se encuentre en los archivos del sujeto obligado, el Comité de\nTransparencia:\nI.  Analizará el caso y tomará las medidas necesarias para localizar la información;\nII.  Expedirá una resolución que confirme la inexistencia del Documento;\nIII.  Ordenará, a través de la Unidad de Transparencia, se exponga de forma fundada y motivada, las\nrazones por las cuales en el caso particular no cuenta con la información, lo cual notificará a la\npersona solicitante, y\nIV.  En su caso, notificará al órgano interno de control o equivalente del sujeto obligado.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"36537898-df23-49e4-8660-25aac42219cd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":140},{"identificador":"Artículo 141","tipo_articulo":"ordinario","contenido":"La resolución del Comité de Transparencia que confirme la inexistencia de la información solicitada\ncontendrá los elementos mínimos que permitan a la persona solicitante tener la certeza de que se utilizó un criterio\nde búsqueda exhaustivo, además de señalar las circunstancias de tiempo, modo y lugar que generaron la\ninexistencia.\nEn aquellos casos en que no se advierta obligación o competencia alguna de los sujetos obligados para contar\ncon la información, derivado del análisis a las disposiciones jurídicas aplicables a la materia de la solicitud, además\nno se tengan elementos de convicción que permitan suponer que esta debe obrar en sus archivos, o bien, se cuente\ncon atribuciones, pero no se ha generado la información no será necesario que el Comité de Transparencia emita\nuna resolución que confirme la inexistencia de la misma.\nCuando se requiera un dato estadístico o numérico, y el resultado de la búsqueda de la información sea cero,\neste deberá entenderse como un dato que constituye un elemento numérico que atiende la solicitud, y no como la\ninexistencia de la información solicitada.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"1243824f-fc03-4ee1-85c4-abb3b1bf8c3f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":141},{"identificador":"Artículo 142","tipo_articulo":"ordinario","contenido":"Las personas físicas y morales que reciban y ejerzan recursos públicos o realicen actos de\nautoridad, serán responsables del cumplimiento de los plazos y términos para otorgar acceso a la información.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo I Del Procedimiento de Acceso a la Información","seccion_nombre":null,"id":"0838650a-c7ff-4207-ad25-c604b76dd7a5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":142},{"identificador":"Artículo 143","tipo_articulo":"ordinario","contenido":"En caso de existir costos para obtener la información, deberán cubrirse de manera previa a la\nentrega y no podrán ser superiores a la suma de:\nI.  El costo de los materiales utilizados en la reproducción de la información;\nII.  El costo de envío, en su caso, y\nIII.  El pago de la certificación de los documentos, cuando proceda.\nLas cuotas de los derechos aplicables deberán establecerse en la Ley Federal de Derechos, los cuales se\npublicarán en los sitios de Internet de los sujetos obligados. En su determinación se deberá considerar que los\nmontos permitan o faciliten el ejercicio del derecho de acceso a la información, asimismo, se establecerá la\nobligación de fijar una cuenta bancaria única y exclusivamente para que la persona solicitante realice el pago íntegro\ndel costo de la información que solicitó.\nLos sujetos obligados a los que no les sea aplicable la Ley Federal de Derechos deberán establecer cuotas que\nno deberán ser mayores a las dispuestas en dicha ley.\nLa información deberá ser entregada sin costo, cuando implique la entrega de no más de veinte hojas simples.\nLas Unidades de Transparencia podrán exceptuar el pago de reproducción y envío atendiendo a las circunstancias\nsocioeconómicas de la persona solicitante.","titulo_nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","capitulo_nombre":"Capítulo II De las Cuotas de Acceso","seccion_nombre":null,"id":"39e05b5c-8eee-4d4c-822a-653af32a49c2","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":143},{"identificador":"Artículo 144","tipo_articulo":"ordinario","contenido":"La persona solicitante podrá interponer, por sí mismo o por conducto de su representante, de\nmanera física o por medios electrónicos, recurso de revisión ante la Autoridad garante que corresponda, o ante la\nUnidad de Transparencia que haya conocido de la solicitud dentro de los quince días siguientes a la fecha de la\nnotificación de la respuesta, o del vencimiento del plazo para su notificación.\nEn el caso de que se interponga ante la Unidad de Transparencia, esta deberá remitir el recurso de revisión a la\nAutoridad garante que corresponda a más tardar al día siguiente de haberlo recibido.\nPara el caso de personas que posean algún tipo de discapacidad que les dificulte una comunicación clara y\nprecisa o de personas que sean hablantes de lengua indígena, se procurará proporcionarles gratuitamente un\ntraductor o intérprete.\nAsimismo, cuando el recurso sea presentado por una persona con discapacidad ante la Unidad de Transparencia,\ndicha circunstancia deberá ser notificada a la Autoridad garante, para que determine mediante acuerdo los ajustes\nrazonables que garanticen la tutela efectiva del derecho de acceso a la información.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"2ab962d3-4e0f-4ce6-a6e7-6ff21a7f9157","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":144},{"identificador":"Artículo 145","tipo_articulo":"ordinario","contenido":"El recurso de revisión procede en contra de:\nI.  La clasificación de la información;\nII.  La declaración de inexistencia de información;\nIII.  La declaración de incompetencia por el sujeto obligado;\nIV.  La entrega de información incompleta;\nV.  La entrega de información que no corresponda con lo solicitado;\nVI.  La falta de respuesta a una solicitud de acceso a la información dentro de los plazos establecidos en la\nley;\nVII.  La notificación, entrega o puesta a disposición de información en una modalidad o formato distinto al\nsolicitado;\nVIII.  La entrega o puesta a disposición de información en un formato incomprensible y/o no accesible para\nla persona solicitante;\nIX.  Los costos o tiempos de entrega de la información;\nX.  La falta de trámite a una solicitud;\nXI.  La negativa a permitir la consulta directa de la información;\nXII.  La falta, deficiencia o insuficiencia de la fundamentación y/o motivación en la respuesta, o\nXIII.  La orientación a un trámite específico.\nLa respuesta que den los sujetos obligados derivada de la resolución al recurso de revisión que proceda por las\ncausales señaladas en las fracciones III, VI, VIII, IX, X y XI de este artículo, es susceptible de ser impugnada de\nnueva cuenta, mediante recurso de revisión, ante la Autoridad garante correspondiente.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"83897723-69e7-4fc1-b5bd-be85696ea912","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":145},{"identificador":"Artículo 146","tipo_articulo":"ordinario","contenido":"El recurso de revisión debe contener:\nI.  El sujeto obligado ante el cual se presentó la solicitud;\nII.  El nombre de la persona solicitante que recurre o de su representante y, en su caso, de la persona\ntercera interesada, así como la dirección o medio que señale para recibir notificaciones;\nIII.  El número de folio de respuesta de la solicitud de acceso;\nIV.  La fecha en que fue notificada la respuesta a la persona solicitante o tuvo conocimiento del acto\nreclamado, o de presentación de la solicitud, en caso de falta de respuesta;\nV.  El acto que se recurre;\nVI.  Las razones o motivos de inconformidad, y\nVII.  La copia de la respuesta que se impugna y, en su caso, de la notificación correspondiente, salvo en el\ncaso de respuesta de la solicitud.\nAdicionalmente, se podrán anexar las pruebas y demás elementos que considere procedentes someter a juicio de\nla Autoridad garante.\nEn ningún caso será necesario que el particular ratifique el recurso de revisión interpuesto.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"64391472-1858-4109-9c9a-39e73c3977bd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":146},{"identificador":"Artículo 147","tipo_articulo":"ordinario","contenido":"Si el escrito de interposición del recurso no cumple con alguno de los requisitos establecidos en el\nartículo anterior y la Autoridad garante no cuentan con elementos para subsanarlos, se prevendrá al recurrente, por\nuna sola ocasión y a través del medio que haya elegido para recibir notificaciones, con el objeto de que subsane las\nomisiones dentro de un plazo que no podrá exceder de cinco días, contados a partir del día siguiente de la\nnotificación de la prevención, con el apercibimiento de que, de no cumplir, se desechará el recurso de revisión.\nLa prevención tendrá el efecto de interrumpir el plazo que tienen las Autoridades garantes para resolver el\nrecurso, por lo que comenzará a computarse a partir del día siguiente a su desahogo.\nEn los casos que no se proporcione un domicilio o medio para recibir notificaciones o, en su defecto, no haya sido\nposible practicar la notificación, se realizará por estrados en el domicilio de la Autoridad garante.\nNo podrá prevenirse por el nombre o los datos que proporcione la persona solicitante.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"b97073a6-86e1-49ea-a867-2511a48a81e8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":147},{"identificador":"Artículo 148","tipo_articulo":"ordinario","contenido":"La Autoridad garante resolverá el recurso de revisión en un plazo que no podrá exceder de\ncuarenta días, contados a partir de la admisión del mismo, plazo que podrá ampliarse por una sola vez y hasta por un\nperiodo de veinte días. Durante el procedimiento debe aplicarse la suplencia de la queja a favor del recurrente, sin\ncambiar los hechos expuestos, asegurándose de que las partes puedan presentar, de manera oral o escrita, los\nargumentos que funden y motiven sus pretensiones.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"dc8e7c07-996e-4563-a3df-733dc5d497c9","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":148},{"identificador":"Artículo 149","tipo_articulo":"ordinario","contenido":"Cuando en el recurso de revisión se señale como agravio la omisión por parte del sujeto obligado\nde responder a una solicitud de acceso, y el recurso se resuelva de manera favorable para el recurrente, el sujeto\nobligado deberá darle acceso a la información en un periodo no mayor a los diez días hábiles; en cuyo caso se hará\nsin que se requiera del pago correspondiente de derechos por su reproducción, siempre que la resolución esté firme,\nla entrega sea en el formato requerido originalmente y no se trate de copias certificadas.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"7754261d-4100-414f-84cc-933d6bf77741","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":149},{"identificador":"Artículo 150","tipo_articulo":"ordinario","contenido":"En todo momento las Autoridades garantes deben tener acceso a la información clasificada para\ndeterminar su naturaleza según se requiera. El acceso se dará de conformidad con las disposiciones jurídicas\nestablecidas por los sujetos obligados para el resguardo o salvaguarda de la información.\nTratándose de la información a que se refiere el último párrafo del artículo 104 de esta Ley, los sujetos obligados\ndeberán dar acceso a las Autoridades garantes a dicha información mediante la exhibición de la documentación\nrelacionada, en las oficinas de los propios sujetos obligados.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"8732c69f-a376-4181-87f6-144880cc5c03","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":150},{"identificador":"Artículo 151","tipo_articulo":"ordinario","contenido":"La información reservada o confidencial que, en su caso, sea consultada por las Autoridades\ngarantes por resultar indispensable para resolver el asunto, debe ser mantenida con ese carácter y no debe estar\ndisponible en el Expediente, salvo en los casos en los que sobreviniera la desclasificación de dicha información y\ncontinuara bajo el resguardo del sujeto obligado en el que originalmente se encontraba o cuando se requiera, por ser\nviolaciones graves a derechos humanos o delitos de lesa humanidad, de conformidad con el derecho nacional y los\ntratados internacionales de los que el Estado mexicano sea parte.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"7e73410e-470b-4b10-a806-f19a665a5f18","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":151},{"identificador":"Artículo 152","tipo_articulo":"ordinario","contenido":"La Autoridad garante al resolver el recurso de revisión, debe aplicar una prueba de interés público\ncon base en elementos de idoneidad, necesidad y proporcionalidad, cuando exista una colisión de derechos.\nPara estos efectos, se entiende por:\nI.  Idoneidad: La legitimidad del derecho adoptado como preferente, que sea el adecuado para el logro de\nun fin constitucionalmente válido o apto para conseguir el fin pretendido;\nII.  Necesidad: La falta de un medio alternativo menos lesivo a la apertura de la información, para\nsatisfacer el interés público, y\nIII.  Proporcionalidad: El equilibrio entre perjuicio y beneficio a favor del interés público, a fin de que la\ndecisión tomada represente un beneficio mayor al perjuicio que podría causar a la población.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"d5ffab04-c371-45ac-b485-19d81f20458c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":152},{"identificador":"Artículo 153","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes resolverán el recurso de revisión conforme a lo siguiente:\nI.  Interpuesto el recurso de revisión deberán proceder a su análisis para que decrete su admisión o su\ndesechamiento;\nII.  Admitido el recurso de revisión deberán integrar un Expediente y ponerlo a disposición de las partes,\npara que, en un plazo máximo de siete días, manifiesten lo que a su derecho convenga. De\nconsiderarse improcedente el recurso, deberá desecharse mediante acuerdo fundado y motivado,\ndentro de un plazo máximo de cinco días contados a partir de la conclusión del plazo otorgado a las\npartes para que manifiesten lo que a sus intereses convenga, debiendo notificarle dentro de los tres\ndías siguientes a la emisión del acuerdo;\nIII.  En caso de existir persona tercera interesada, se le hará la notificación para que en el plazo\nmencionado en la fracción anterior acredite su carácter, alegue lo que a su derecho convenga y aporte\nlas pruebas que estime pertinentes;\nIV.  Dentro del plazo mencionado en la fracción II del presente artículo, las partes podrán ofrecer todo tipo\nde pruebas o alegatos excepto la confesional por parte de los sujetos obligados y aquéllas que sean\ncontrarias a derecho. Se recibirán aquellas pruebas que resulten supervinientes por las partes, mismas\nque serán tomadas en cuenta, siempre y cuando no se haya dictado la resolución;\nV.  Podrán determinar la celebración de audiencias con las partes durante la sustanciación del recurso de\nrevisión;\nVI.  Concluido el plazo señalado en la fracción II del presente artículo, procederán a decretar el cierre de\ninstrucción. Asimismo, a solicitud de los sujetos obligados o los recurrentes, los recibirán en audiencia,\na efecto de allegarse de mayores elementos de convicción que le permitan valorar los puntos\ncontrovertidos objeto del recurso de revisión;\nVII.  No estarán obligadas a atender la información remitida por el sujeto obligado una vez decretado el\ncierre de instrucción, y\nVIII.  Decretado el cierre de instrucción, el expediente pasará a resolución, en un plazo que no podrá\nexceder de veinte días.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"c0658438-c194-4b5b-bda4-85fb8f13c470","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":153},{"identificador":"Artículo 154","tipo_articulo":"ordinario","contenido":"Las resoluciones de las Autoridades garantes podrán:\nI.  Desechar o sobreseer el recurso;\nII.  Confirmar la respuesta del sujeto obligado, o\nIII.  Revocar o modificar la respuesta del sujeto obligado.\nLas resoluciones establecerán, en su caso, los plazos y términos para su cumplimiento y los procedimientos para\nasegurar su ejecución, los cuales no podrán exceder de diez días para la entrega de información. Excepcionalmente,\nlas Autoridades garantes previa fundamentación y motivación, podrán ampliar estos plazos cuando el asunto así lo\nrequiera.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"c2592b7c-03f2-4e9a-b895-6833611afc6a","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":154},{"identificador":"Artículo 155","tipo_articulo":"ordinario","contenido":"En las resoluciones las Autoridades garantes podrán señalarles a los sujetos obligados que la\ninformación que deben proporcionar sea considerada como obligación de transparencia de conformidad con el\nCapítulo II del Título Quinto, denominado “De las Obligaciones de Transparencia Comunes” de la presente Ley,\natendiendo a la relevancia de la información, la incidencia de las solicitudes sobre la misma y el sentido reiterativo de\nlas resoluciones.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"5fa6ebc8-86f4-412e-8620-c72c6b94495d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":155},{"identificador":"Artículo 156","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes deben notificar a las partes y publicar las resoluciones, a más tardar, al\ntercer día siguiente de su aprobación.\nLos sujetos obligados deben informar a las Autoridades garantes de que se trate, el cumplimiento de sus\nresoluciones en un plazo no mayor a tres días.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"2dff1aad-e9fc-4509-b457-47a4bf23ded1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":156},{"identificador":"Artículo 157","tipo_articulo":"ordinario","contenido":"Cuando las Autoridades garantes determinen durante la sustanciación del recurso de revisión que\npudo haberse incurrido en una probable responsabilidad por el incumplimiento a las obligaciones previstas en esta\nLey y las demás disposiciones aplicables en la materia, debe hacerlo del conocimiento del órgano interno de control\no de la instancia competente para que esta inicie, en su caso, el procedimiento de responsabilidad respectivo.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"734a77d6-af4c-47c4-bdde-4f3a0f967d34","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":157},{"identificador":"Artículo 158","tipo_articulo":"ordinario","contenido":"El recurso será desechado por improcedente cuando:\nI.  Sea extemporáneo por haber transcurrido el plazo establecido en el artículo 144 de la presente Ley;\nII.  Se esté tramitando ante el Poder Judicial algún recurso o medio de defensa interpuesto por el\nrecurrente;\nIII.  No actualice alguno de los supuestos previstos en el artículo 145 de la presente Ley;\nIV.  No se haya desahogado la prevención en los términos establecidos en el artículo 147 de la presente\nLey;\nV.  Se impugne la veracidad de la información proporcionada;\nVI.  Se trate de una consulta, o\nVII.  El recurrente amplíe su solicitud en el recurso de revisión, únicamente respecto de los nuevos\ncontenidos.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"026c1a92-17c7-56e4-b296-00c044fcbb91","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":158},{"identificador":"Artículo 159","tipo_articulo":"ordinario","contenido":"El recurso será sobreseído, en todo o en parte, cuando, una vez admitido, se actualicen alguno de\nlos siguientes supuestos:\nI.  El recurrente se desista;\nII.  El recurrente fallezca o tratándose de personas morales que se disuelvan;\nIII.  El sujeto obligado responsable del acto lo modifique o revoque de tal manera que el recurso de\nrevisión quede sin materia, o\nIV.  Admitido el recurso de revisión, aparezca alguna causal de improcedencia en los términos del presente\nCapítulo.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"5f62bf96-a12b-4eb8-a371-d5019b5396bc","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":159},{"identificador":"Artículo 160","tipo_articulo":"ordinario","contenido":"Las resoluciones de las Autoridades garantes son vinculatorias, definitivas e inatacables para los\nsujetos obligados.\nÚnicamente la persona titular de la Consejería Jurídica del Ejecutivo Federal podrá interponer recurso de revisión\nante la Suprema Corte de Justicia de la Nación, en los términos que se establecen en el Capítulo III denominado “Del\nRecurso de Revisión en Materia de Seguridad Nacional”, del presente Título, sólo en el caso que dichas resoluciones\npuedan poner en peligro la seguridad nacional.\nLos jueces y tribunales especializados en materia de transparencia tendrán acceso a la información clasificada\ncuando resulte indispensable para resolver el asunto y hubiera sido ofrecida en juicio. Dicha información deberá ser\nmantenida con ese carácter y no estará disponible en el expediente judicial. El acceso se dará de conformidad con\nlos protocolos previamente establecidos para la protección y resguardo de la información por parte de los sujetos\nobligados.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"6181aa80-c590-4110-8091-c46143097564","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":160},{"identificador":"Artículo 161","tipo_articulo":"ordinario","contenido":"Las personas particulares podrán impugnar las determinaciones o resoluciones de las Autoridades\ngarantes por la vía del recurso de inconformidad, en los casos previstos en la presente Ley, o ante los jueces y\ntribunales especializados en materia de transparencia establecidos por el Poder Judicial de la Federación mediante\nel juicio de amparo.\nLos juicios de amparo serán sustanciados por jueces y tribunales especializados en los términos del artículo 94\nde la Constitución Política de los Estados Unidos Mexicanos.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo I Del Recurso de Revisión","seccion_nombre":null,"id":"81716219-8287-4ef4-b4eb-f5bf97c42b57","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":161},{"identificador":"Artículo 162","tipo_articulo":"ordinario","contenido":"Tratándose de las resoluciones a los recursos de revisión de las Autoridades garantes locales\ncuando las mismas se encuentren vinculadas con solicitudes de información concernientes a recursos públicos\nfederales, las personas particulares podrán acudir ante la Autoridad garante federal o ante los tribunales\nespecializados en materia de transparencia del Poder Judicial de la Federación.\nEn el supuesto de que el Sistema Nacional adopte los acuerdos previstos en el artículo 25, fracción XIV de la\npresente Ley, la Autoridad garante federal deberá de aplicar las disposiciones previstas en este Capítulo.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"6a8b23ce-14fc-4ba0-8244-acdcc4f42183","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":162},{"identificador":"Artículo 163","tipo_articulo":"ordinario","contenido":"El recurso de inconformidad procede contra las resoluciones emitidas por las Autoridades garantes\nlocales cuando se encuentren vinculadas con solicitudes de información concernientes a recursos públicos federales\nque:\nI.  Confirmen o modifiquen la clasificación de la información vinculada con recursos públicos federales, o\nII.  Confirmen la inexistencia o negativa de información vinculadas con recursos públicos federales.\nSe entenderá como negativa de acceso a la información, la falta de resolución de las Autoridades garantes\nlocales dentro del plazo previsto para ello.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"9b3ded8a-cf31-4201-b81b-e7bc9d840df9","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":163},{"identificador":"Artículo 164","tipo_articulo":"ordinario","contenido":"El recurso de inconformidad debe presentarse dentro de los quince días posteriores a que se tuvo\nconocimiento de la resolución o que se venza el plazo para que fuera emitido, mediante el sistema electrónico o por\nescrito, ante la Autoridad garante federal o ante la Autoridad garante local que hubiere emitido la resolución.\nEn caso de presentarse recurso de inconformidad por escrito ante la Autoridad garante local, esta deberá hacerlo\ndel conocimiento a la Autoridad garante federal al día siguiente de su recepción, acompañándolo con la resolución\nimpugnada, a través de la Plataforma Nacional.\nIndependientemente de la vía a través de la cual sea interpuesto el recurso de inconformidad, el Expediente\nrespectivo deberá obrar en la Plataforma Nacional.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"3d73d6f1-6f2d-4c80-867e-9c37f1200e61","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":164},{"identificador":"Artículo 165","tipo_articulo":"ordinario","contenido":"El recurso de inconformidad debe contener:\nI.  El sujeto obligado ante el cual se presentó la solicitud;\nII.  El número de la resolución del recurso de revisión de la resolución impugnada;\nIII.  La Autoridad garante local que emitió la resolución que se impugna;\nIV.  El nombre del inconforme y, en su caso, de la persona tercera interesada, así como las\ncorrespondientes direcciones o medios para recibir notificaciones;\nV.  La fecha en que fue notificada la resolución impugnada;\nVI.  El acto que se recurre;\nVII.  Las razones o motivos de la inconformidad, y\nVIII.  La copia de la resolución que se impugna y, en su caso, de la notificación correspondiente.\nEl recurrente podrá anexar las pruebas y demás elementos que considere procedentes someter a consideración\nde la Autoridad garante.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"ac4c59c6-128d-4085-bf74-169b9f4a0554","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":165},{"identificador":"Artículo 166","tipo_articulo":"ordinario","contenido":"Una vez que la Autoridad garante federal reciba el recurso de inconformidad examinará su\nprocedencia y, en su caso, requerirá los elementos que considere necesarios a la Autoridad garante local\nresponsable.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"b8043e13-72c5-43c9-9fe3-d9b1990f7ad3","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":166},{"identificador":"Artículo 167","tipo_articulo":"ordinario","contenido":"Si el escrito de interposición del recurso de inconformidad no cumple con alguno de los requisitos\nestablecidos en el artículo 165 de esta Ley y la Autoridad garante federal no cuenta con elementos para subsanarlos,\nse prevendrá al inconforme en un plazo que no excederá de cinco días, por una sola ocasión y a través del medio\nque haya elegido para recibir notificaciones, para que subsane las omisiones dentro de un plazo que no podrá\nexceder de quince días, contados a partir del día siguiente al de la notificación de la prevención, con el\napercibimiento de que, de no desahogar la prevención en tiempo y forma, se tendrá por no presentado el recurso de\ninconformidad.\nLa prevención tendrá el efecto de interrumpir el plazo que tiene la Autoridad garante federal para resolver el\nrecurso de inconformidad, por lo que este comenzará a computarse nuevamente a partir del día siguiente a su\ndesahogo.\nNo podrá prevenirse por el nombre que proporcione el inconforme.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"3ba0dc20-3248-42dd-b494-1873c076b9ba","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":167},{"identificador":"Artículo 168","tipo_articulo":"ordinario","contenido":"La Autoridad garante federal resolverá el recurso de inconformidad en un plazo que no podrá\nexceder de treinta días, plazo que podrá ampliarse por una sola vez y hasta por un periodo igual.\nInterpuesto el recurso de inconformidad por falta de resolución, en términos del segundo párrafo del artículo 163\nde esta Ley, la Autoridad garante federal dará vista, en el término de tres días siguientes, contados a partir del día en\nque fue recibido el recurso, a la Autoridad garante local, para que alegue lo que a su derecho convenga en un plazo\nde cinco días.\nRecibida la contestación, la Autoridad garante federal debe emitir su resolución en un plazo no mayor a quince\ndías. En caso de no recibir la contestación por parte de la Autoridad garante local o que esta no pruebe\nfehacientemente que dictó resolución o no exponga de manera fundada y motivada, a criterio de la Autoridad garante\nfederal, que se trata de información reservada o confidencial, esta resolverá a favor de la persona solicitante.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"34558ce2-cdf9-464a-8d93-4f4b23857a13","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":168},{"identificador":"Artículo 169","tipo_articulo":"ordinario","contenido":"Durante el procedimiento debe aplicarse la suplencia de la deficiencia de la queja, sin cambiar los\nhechos, a favor del recurrente y se deberá asegurar que las partes puedan presentar los argumentos y constancias\nque funden y motiven sus pretensiones y formular sus alegatos.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"333633a5-990e-4ff6-baa2-9cf358b08cfc","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":169},{"identificador":"Artículo 170","tipo_articulo":"ordinario","contenido":"En todo caso, la Autoridad garante federal tendrá acceso a la información clasificada para\ndeterminar su naturaleza.\nLa información reservada o confidencial que, en su caso, sea consultada por la persona Titular o la persona\nservidora pública que se designe para tal efecto de la Autoridad garante federal por resultar indispensable para\nresolver el asunto, debe ser mantenida con ese carácter y no debe estar disponible en el Expediente, salvo en los\ncasos en los que sobreviniera la desclasificación de dicha información, continuando bajo el resguardo del sujeto\nobligado en el que originalmente se encontraba.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"bc38441d-4bc7-4d38-882b-3c59011cf93c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":170},{"identificador":"Artículo 171","tipo_articulo":"ordinario","contenido":"Admitido el recurso de inconformidad, se correrá traslado del mismo a la Autoridad garante local, a\nfin de que en un plazo máximo de diez días rinda su informe justificado.\nEl recurrente podrá manifestar lo que a su derecho convenga y aportar los elementos que considere pertinentes,\ndentro de los diez días siguientes a la notificación de la admisión del recurso de inconformidad. Concluido este plazo,\nse decretará el cierre de instrucción y el Expediente pasará a resolución.\nEl recurrente podrá solicitar la ampliación del plazo, antes del cierre de instrucción, hasta por un periodo de diez\ndías adicionales para manifestar lo que a su derecho convenga.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"5282598b-024f-47a4-ac32-38c814584ac8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":171},{"identificador":"Artículo 172","tipo_articulo":"ordinario","contenido":"Después del cierre de instrucción y hasta antes de dictada la resolución, sólo serán admisibles las\npruebas supervenientes y la petición de ampliación de informes a las Autoridades garantes locales.\nEn caso de existir persona tercera interesada, se le notificará la admisión del recurso de inconformidad para que,\nen un plazo no mayor a cinco días, acredite su carácter y alegue lo que a su derecho convenga.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"c5c86132-2a6a-4d8a-8501-ebbb2619acac","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":172},{"identificador":"Artículo 173","tipo_articulo":"ordinario","contenido":"Las resoluciones de la unidad correspondiente de la Autoridad garante federal podrán:\nI.  Desechar o sobreseer el recurso de inconformidad;\nII.  Confirmar la resolución de la Autoridad garante local, o\nIII.  Revocar o modificar la resolución de la Autoridad garante local.\nLa resolución será notificada al inconforme, al sujeto obligado, a la Autoridad garante local, y, en su caso, a la\npersona tercera interesada, a través de la Plataforma Nacional.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"72517e4b-59dd-4337-893a-cf18aa9d4d7e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":173},{"identificador":"Artículo 174","tipo_articulo":"ordinario","contenido":"Cuando la Autoridad garante federal determine durante la sustanciación del recurso de\ninconformidad que pudo haberse incurrido en una probable responsabilidad por el incumplimiento a las obligaciones\nprevistas en la presente Ley y demás disposiciones aplicables en la materia, deberá hacerlo del conocimiento de la\nautoridad competente para que esta inicie, en su caso, el procedimiento de responsabilidad respectivo.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"a17740a3-a45e-4207-959e-1ff5177af613","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":174},{"identificador":"Artículo 175","tipo_articulo":"ordinario","contenido":"En los casos en que por conducto del recurso de inconformidad se modifique o revoque lo decidido\nen el recurso de revisión, la Autoridad garante local, señalada como responsable y que fuera la que dictó la\nresolución recurrida, procederá a emitir un nuevo fallo, atendiendo los lineamientos que se fijaron al resolver la\ninconformidad, dentro del plazo de quince días, contados a partir del día siguiente al en que se hubiere notificado o\nse tenga conocimiento de la resolución dictada en la inconformidad.\nExcepcionalmente, considerando las circunstancias especiales de cada caso en concreto, las Autoridades\ngarantes locales, de manera fundada y motivada, podrán solicitar a la Autoridad garante federal una ampliación de\nplazo para la emisión de la nueva resolución, la cual debe realizarse a más tardar cinco días antes de que venza el\nplazo otorgado para el cumplimiento de la resolución, a efecto de que dicha Autoridad garante federal resuelva sobre\nla procedencia de la misma dentro de los tres días siguientes de realizada la petición.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"dc9c9b15-e8ba-4e64-8305-164cd5ba7a70","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":175},{"identificador":"Artículo 176","tipo_articulo":"ordinario","contenido":"Una vez emitida la nueva resolución por la Autoridad garante local responsable de la entidad\nfederativa, según corresponda, en cumplimiento al fallo del recurso de inconformidad, la notificará sin demora, a\ntravés de la Plataforma Nacional a la Autoridad garante federal, así como al sujeto obligado que corresponda, a\ntravés de su Unidad de Transparencia para efecto del cumplimiento.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"68484c52-7ec8-4d7a-aaaa-5e0b79d42b25","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":176},{"identificador":"Artículo 177","tipo_articulo":"ordinario","contenido":"El sujeto obligado, a través de la Unidad de Transparencia debe cumplir con la nueva resolución\nque le hubiere notificado la Autoridad garante local en cumplimiento al fallo del recurso de inconformidad, en un plazo\nno mayor a diez días, a menos de que en la misma se hubiere determinado un plazo mayor para su cumplimiento. En\nel propio acto en que se haga la notificación al sujeto obligado, se le requerirá para que informe sobre el\ncumplimiento que se dé a la resolución de referencia.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"d617dc72-e650-434f-a0e5-ebaa14fec52a","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":177},{"identificador":"Artículo 178","tipo_articulo":"ordinario","contenido":"Una vez cumplimentada la resolución a que se refiere el artículo anterior por parte del sujeto\nobligado, este debe informar a la Autoridad garante local respecto de su cumplimiento, lo cual debe hacer dentro del\nplazo previsto en el artículo anterior.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"9239e2a3-c173-4736-b316-d6a983605bf8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":178},{"identificador":"Artículo 179","tipo_articulo":"ordinario","contenido":"Corresponderá a las Autoridades garantes locales, en el ámbito de su competencia, realizar el\nseguimiento y vigilancia del debido cumplimiento por parte del sujeto obligado respectivo de la nueva resolución\nemitida como consecuencia de la inconformidad, en términos del Capítulo II del presente Título.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"6cc8d93e-749f-46df-8edc-9468733bcd30","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":179},{"identificador":"Artículo 180","tipo_articulo":"ordinario","contenido":"Las medidas de apremio previstas en esta Ley resultarán aplicables para efectos del cumplimiento\nde las resoluciones que recaigan a los recursos de inconformidad. Estas medidas de apremio deben establecerse en\nla propia resolución.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"822a85ec-45ca-480d-8d01-770388e3b8a4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":180},{"identificador":"Artículo 181","tipo_articulo":"ordinario","contenido":"El recurso de inconformidad será desechado por improcedente cuando:\nI.  Sea extemporáneo por haber transcurrido el plazo establecido en el artículo 164 de la presente Ley;\nII.  Se esté tramitando ante el tribunal especializado en materia de transparencia del Poder Judicial algún\nrecurso o medio de defensa interpuesto por el inconforme o, en su caso, por la persona tercera\ninteresada, en contra del acto recurrido ante la Autoridad garante federal;\nIII.  No se actualice alguno de los supuestos previstos en el artículo 163 de la presente Ley;\nIV.  Cuando la pretensión del recurrente vaya más allá de los agravios planteados inicialmente ante la\nAutoridad garante local correspondiente;\nV.  La Autoridad garante federal no sea competente, o\nVI.  Se actualice cualquier otra hipótesis de improcedencia prevista en la presente Ley.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"ac319387-98af-4bd6-a239-0b9d3f478f7d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":181},{"identificador":"Artículo 182","tipo_articulo":"ordinario","contenido":"El recurso de inconformidad será sobreseído cuando, una vez admitido, se actualicen alguno de los\nsiguientes supuestos:\nI.  El inconforme se desista expresamente del recurso;\nII.  El recurrente fallezca;\nIII.  El sujeto obligado responsable del acto lo modifique o revoque de tal manera que el recurso de\ninconformidad quede sin materia, o\nIV.  Admitido el recurso de inconformidad, aparezca alguna causal de improcedencia en los términos del\npresente Capítulo.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"b3ae1e1f-209a-474f-9752-da6dd5a1bdbc","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":182},{"identificador":"Artículo 183","tipo_articulo":"ordinario","contenido":"La resolución de la Autoridad garante federal será definitiva e inatacable para la Autoridad garante\nlocal y el sujeto obligado de que se trate.\nLas personas particulares podrán impugnar las resoluciones de la Autoridad garante federal ante los jueces y\ntribunales especializados en materia de transparencia establecidos por el Poder Judicial de la Federación.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo II Del Recurso de Inconformidad","seccion_nombre":null,"id":"1040bd77-59fc-4e66-84ec-b532fbecb883","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":183},{"identificador":"Artículo 184","tipo_articulo":"ordinario","contenido":"La persona titular de la Consejería Jurídica del Ejecutivo Federal podrá interponer recurso de\nrevisión en materia de seguridad nacional directamente ante la Suprema Corte de Justicia de la Nación, cuando\nconsidere que las resoluciones emitidas por la Autoridad garante federal ponen en peligro la seguridad nacional.\nEl recurso debe interponerse durante los siete días siguientes a aquél en el que la Autoridad garante notifique la\nresolución al sujeto obligado. La Suprema Corte de Justicia de la Nación determinará, de inmediato, en su caso, la\nsuspensión de la ejecución de la resolución y dentro de los cinco días siguientes a la interposición del recurso\nresolverá sobre su admisión o improcedencia.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo III Del Recurso de Revisión en Materia de Seguridad Nacional","seccion_nombre":null,"id":"6d95f26f-b187-494e-97f6-5559d994728d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":184},{"identificador":"Artículo 185","tipo_articulo":"ordinario","contenido":"En el escrito del recurso, la persona titular de la Consejería Jurídica del Ejecutivo Federal debe\nseñalar la resolución que se impugna, los fundamentos y motivos por los cuales considera que vulnera la seguridad\nnacional, así como los elementos de prueba necesarios.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo III Del Recurso de Revisión en Materia de Seguridad Nacional","seccion_nombre":null,"id":"92aea394-7140-454d-86ee-4355651ee5d9","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":185},{"identificador":"Artículo 186","tipo_articulo":"ordinario","contenido":"La información reservada o confidencial que, en su caso, sea solicitada por la Suprema Corte de\nJusticia de la Nación por resultar indispensable para resolver el asunto, debe mantenerse con ese carácter y no\nestará disponible en el Expediente, salvo en las excepciones previstas en el artículo 119 de la presente Ley.\nEn todo momento, las Ministras y los Ministros deben tener acceso a la información clasificada para determinar su\nnaturaleza, según se requiera. El acceso se dará de conformidad con las disposiciones jurídicas aplicables al\nresguardo o salvaguarda de la información por parte de los sujetos obligados.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo III Del Recurso de Revisión en Materia de Seguridad Nacional","seccion_nombre":null,"id":"4bbde2f1-b3e0-430e-97e7-6d6abaf7f782","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":186},{"identificador":"Artículo 187","tipo_articulo":"ordinario","contenido":"La Suprema Corte de Justicia de la Nación resolverá con plenitud de jurisdicción, y en ningún caso,\nprocederá el reenvío.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo III Del Recurso de Revisión en Materia de Seguridad Nacional","seccion_nombre":null,"id":"5a8d1d37-4520-4067-afd0-f4ed7adda9dd","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":187},{"identificador":"Artículo 188","tipo_articulo":"ordinario","contenido":"Si la Suprema Corte de Justicia de la Nación confirma el sentido de la resolución recurrida, el sujeto\nobligado deberá dar cumplimiento y entregar la información en los términos que establece el artículo 191 de esta Ley.\nEn caso de que se revoque la resolución, la Autoridad garante federal debe actuar en los términos que ordene la\nSuprema Corte de Justicia de la Nación.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo III Del Recurso de Revisión en Materia de Seguridad Nacional","seccion_nombre":null,"id":"68da5d35-f944-41ef-8f6e-f01c9b3ccc9a","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":188},{"identificador":"Artículo 189","tipo_articulo":"ordinario","contenido":"En la aplicación de las disposiciones de la presente Ley, relacionadas con la información de\nasuntos jurisdiccionales de la Suprema Corte de Justicia de la Nación, se debe crear un comité especializado en\nmateria de acceso a la información integrado por tres ministros.\nPara resolver los recursos de revisión relacionados con la información de asuntos jurisdiccionales, dicho comité\natenderá a los principios, reglas y procedimientos de resolución establecidos en la presente Ley y tendrá las\natribuciones de las Autoridades garantes.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo IV Del Recurso de Revisión de Asuntos Jurisdiccionales de la Suprema Corte de Justicia de la Nación","seccion_nombre":null,"id":"a93f46c3-3599-4417-bef3-7550d4c60884","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":189},{"identificador":"Artículo 190","tipo_articulo":"ordinario","contenido":"Se entienden como asuntos jurisdiccionales, aquellos que estén relacionados con el ejercicio de la\nfunción constitucional de impartición de justicia competencia de la Suprema Corte de Justicia de la Nación, en\ntérminos de lo previsto por la Ley Orgánica del Poder Judicial de la Federación.\nLa Suprema Corte de Justicia de la Nación podrá emitir un Acuerdo para la integración, plazos, términos y\nprocedimientos del Comité referido, de conformidad con los principios, reglas y procedimientos de resolución\nestablecidos en esta Ley.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo IV Del Recurso de Revisión de Asuntos Jurisdiccionales de la Suprema Corte de Justicia de la Nación","seccion_nombre":null,"id":"3a2e8d6c-9fe9-4a40-b471-d0e869309305","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":190},{"identificador":"Artículo 191","tipo_articulo":"ordinario","contenido":"Los sujetos obligados deben, por medio de sus Unidades de Transparencia, dar estricto\ncumplimiento a las resoluciones de las Autoridades garantes, y deberán informar a estos sobre su cumplimiento.\nExcepcionalmente, considerando las circunstancias especiales del caso, los sujetos obligados podrán solicitar a\nlas Autoridades garantes, de manera fundada y motivada, una ampliación del plazo para el cumplimiento de la\nresolución.\nDicha solicitud debe presentarse, a más tardar, dentro de los primeros tres días del plazo otorgado para el\ncumplimiento, a efecto de que las Autoridades garantes, resuelvan sobre la procedencia de la misma dentro de los\ncinco días siguientes.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo V Del Cumplimiento de las Resoluciones","seccion_nombre":null,"id":"16f53e07-cb2a-484b-b548-47d2489cee6b","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":191},{"identificador":"Artículo 192","tipo_articulo":"ordinario","contenido":"Transcurrido el plazo señalado en el artículo anterior, el sujeto obligado debe informar a la\nAutoridad garante sobre el cumplimiento de la resolución y publicar en la Plataforma Nacional la información con la\nque se atendió a la misma.\nLa Autoridad garante verificará de oficio la calidad de la información y, a más tardar al día siguiente de recibir el\ninforme, dará vista al recurrente para que, dentro de los cinco días siguientes, manifieste lo que a su derecho\nconvenga. Si dentro del plazo señalado el recurrente manifiesta que el cumplimiento no corresponde a lo ordenado\npor la Autoridad garante, deberá expresar las causas específicas por las cuales así lo considera.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo V Del Cumplimiento de las Resoluciones","seccion_nombre":null,"id":"ccc04dd2-fa21-461f-8912-3f0788e668a5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":192},{"identificador":"Artículo 193","tipo_articulo":"ordinario","contenido":"La Autoridad garante deberá pronunciarse, en un plazo no mayor a cinco días, sobre todas las\ncausas que el recurrente manifieste, así como del resultado de la verificación realizada. Si la autoridad antes\nseñalada considera que se dio cumplimiento a la resolución, emitirá un acuerdo de cumplimiento y se ordenará el\narchivo del Expediente. En caso contrario, dicha autoridad:\nI.  Emitirá un acuerdo de incumplimiento;\nII.  Notificará al superior jerárquico del responsable de dar cumplimiento, para el efecto de que, en un\nplazo no mayor a cinco días, se dé cumplimiento a la resolución, y\nIII.  Determinarán las medidas de apremio o sanciones, según corresponda, que deberán imponerse o las\nacciones procedentes que deberán aplicarse, de conformidad con lo señalado en el siguiente Título.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo V Del Cumplimiento de las Resoluciones","seccion_nombre":null,"id":"c5a26c75-6078-42b6-aed7-229b022179ae","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":193},{"identificador":"Artículo 194","tipo_articulo":"ordinario","contenido":"Una vez que hayan causado ejecutoria las resoluciones dictadas en los recursos que se sometan a\nsu competencia, la Autoridad garante federal podrá emitir los criterios de interpretación que estime pertinentes y que\nderiven de lo resuelto en dichos asuntos.\nLa Autoridad garante federal podrá emitir criterios de carácter orientador para las Autoridades garantes, que se\nestablecerán por reiteración al resolver tres casos análogos de manera consecutiva en el mismo sentido, derivados\nde resoluciones que hayan causado estado.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo VI De los Criterios de Interpretación","seccion_nombre":null,"id":"70232c87-e490-4b1b-bca9-48344e2ab5ce","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":194},{"identificador":"Artículo 195","tipo_articulo":"ordinario","contenido":"Los criterios se compondrán de un rubro, un texto y el precedente o precedentes que, en su caso,\nhayan originado su emisión.\nTodo criterio que emita la Autoridad garante federal debe contener una clave de control para su debida\nidentificación.","titulo_nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","capitulo_nombre":"Capítulo VI De los Criterios de Interpretación","seccion_nombre":null,"id":"d17148cb-8d07-42df-9a83-8c608f5a559d","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":195},{"identificador":"Artículo 196","tipo_articulo":"ordinario","contenido":"Las Autoridades garantes, en sus respectivos ámbitos de competencia, podrán imponer a la\npersona servidora pública encargada de cumplir con la resolución, o a las y los miembros de los sindicatos, partidos\npolíticos o a la persona física o moral responsable, las siguientes medidas de apremio para asegurar el cumplimiento\nde sus determinaciones:\nI.  Amonestación pública, o\nII.  Multa, de ciento cincuenta hasta mil quinientas veces la Unidad de Medida y Actualización vigente al\nmomento en que se cometa el incumplimiento.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo I De las Medidas de Apremio","seccion_nombre":null,"id":"89bb735b-eaf5-4f41-8954-ad6d7ddd5593","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":196},{"identificador":"Artículo 197","tipo_articulo":"ordinario","contenido":"Para calificar las medidas de apremio, las Autoridades garantes deberán considerar:\nI.  La gravedad de la falta del sujeto obligado, determinada por elementos tales como el daño causado,\nlos indicios de intencionalidad, la duración del incumplimiento de las determinaciones de las\nAutoridades garantes, y la afectación al ejercicio de sus atribuciones;\nII.  La condición económica de la persona infractora, y\nIII.  La reincidencia.\nEl incumplimiento de los sujetos obligados será difundido en la Plataforma Nacional y en los portales de\nobligaciones de transparencia de las Autoridades garantes y considerado en las evaluaciones que realicen estas.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo I De las Medidas de Apremio","seccion_nombre":null,"id":"cf519bef-b844-4885-a09c-f0c0c4bd0ed1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":197},{"identificador":"Artículo 198","tipo_articulo":"ordinario","contenido":"En caso de reincidencia, las Autoridades garantes podrán imponer una multa equivalente hasta el\ndoble de la que se hubiera determinado por las mismas.\nSe considerará reincidente al que habiendo incurrido en una infracción que haya sido sancionada, cometa otra\ndel mismo tipo o naturaleza.\nEn caso de que el incumplimiento de las determinaciones de las Autoridades garantes implique la presunta\ncomisión de un delito o una de las conductas señaladas en el artículo 204 de esta Ley, la Autoridad garante\nrespectiva deberá denunciar los hechos ante la autoridad competente.\nLas medidas de apremio de carácter económico no podrán ser cubiertas con recursos públicos.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo I De las Medidas de Apremio","seccion_nombre":null,"id":"10bc9647-a62c-4be5-8ece-05e7ee9e3a0a","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":198},{"identificador":"Artículo 199","tipo_articulo":"ordinario","contenido":"Si a pesar de la ejecución de las medidas de apremio previstas en el artículo anterior no se cumple\ncon la determinación, se requerirá el cumplimiento al superior jerárquico para que en un plazo de cinco días lo\ninstruya a cumplir sin demora. De persistir el incumplimiento, se aplicarán sobre el superior jerárquico las medidas de\napremio establecidas en el artículo anterior.\nTranscurrido el plazo, sin que se haya dado cumplimiento, en su caso, determinará las sanciones que\ncorrespondan.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo I De las Medidas de Apremio","seccion_nombre":null,"id":"cf9cc1a3-22b2-4d37-a20f-39ea2154bf78","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":199},{"identificador":"Artículo 200","tipo_articulo":"ordinario","contenido":"Las medidas de apremio a que se refiere el presente Capítulo, deberán ser impuestas por\nAutoridades garantes y ejecutadas por sí mismas o con el apoyo de la autoridad competente, de conformidad con los\nprocedimientos que establezcan las disposiciones jurídicas aplicables.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo I De las Medidas de Apremio","seccion_nombre":null,"id":"e34d4a63-30e9-405e-a3b6-3f87e59589b8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":200},{"identificador":"Artículo 201","tipo_articulo":"ordinario","contenido":"Las medidas de apremio deberán aplicarse e implementarse en un plazo máximo de quince días,\ncontados a partir de que sea notificada la medida de apremio a la persona infractora.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo I De las Medidas de Apremio","seccion_nombre":null,"id":"7e9c4bc3-22b7-41d3-be81-822e0b4f8477","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":201},{"identificador":"Artículo 202","tipo_articulo":"ordinario","contenido":"La amonestación pública será impuesta y ejecutada por las Autoridades garantes, a excepción de\ncuando se trate de personas servidoras públicas, en cuyo caso será ejecutada por el superior jerárquico inmediato de\nla persona infractora con el que se relacione.\nLas multas que fijen las Autoridades garantes se harán efectivas ante el Servicio de Administración Tributaria o\nlas Secretarías de Finanzas de las entidades federativas, según corresponda, a través de los procedimientos que las\nleyes establezcan.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo I De las Medidas de Apremio","seccion_nombre":null,"id":"686079ab-cd48-40bf-a53f-cb3f1943d45f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":202},{"identificador":"Artículo 203","tipo_articulo":"ordinario","contenido":"Será supletorio a los mecanismos de notificación y ejecución de medidas de apremio, lo dispuesto\nen la Ley Federal de Procedimiento Administrativo y la equivalente en las entidades federativas.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo I De las Medidas de Apremio","seccion_nombre":null,"id":"61979a6b-2a19-45ca-8209-64d71c1a80f4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":203},{"identificador":"Artículo 204","tipo_articulo":"ordinario","contenido":"Serán causas de sanción por incumplimiento de las obligaciones establecidas en la materia de la\npresente Ley, al menos las siguientes:\nI.  La falta de respuesta a las solicitudes de información en los plazos señalados en las disposiciones\njurídicas aplicables;\nII.  Actuar con negligencia, dolo o mala fe durante la sustanciación de las solicitudes en materia de acceso\na la información o bien, al no difundir la información relativa a las obligaciones de transparencia\nprevistas en la presente Ley;\nIII.  Incumplir los plazos de atención previstos en la presente Ley;\nIV.  Usar, sustraer, divulgar, ocultar, alterar, mutilar, destruir o inutilizar, total o parcialmente, sin causa\nlegítima, conforme a las facultades correspondientes, la información que se encuentre bajo la custodia\nde los sujetos obligados y de sus personas servidoras públicas o a la cual tengan acceso o\nconocimiento con motivo de su empleo, cargo o comisión;\nV.  Entregar información incomprensible, incompleta, en un formato no accesible, una modalidad de envío\no de entrega diferente a la solicitada previamente por personas usuarias en su solicitud de acceso a la\ninformación, al responder sin la debida motivación y fundamentación establecidas en esta Ley;\nVI.  No actualizar la información correspondiente a las obligaciones de transparencia en los plazos\nprevistos en la presente Ley;\nVII.  Declarar con dolo o negligencia la inexistencia de información cuando el sujeto obligado deba\ngenerarla, derivado del ejercicio de sus facultades, competencias o funciones;\nVIII.  Declarar la inexistencia de la información cuando exista total o parcialmente en sus archivos;\nIX.  No documentar con dolo o negligencia, el ejercicio de sus facultades, competencias, funciones o actos\nde autoridad, de conformidad con las disposiciones jurídicas aplicables;\nX.  Realizar actos para intimidar a las personas solicitantes de información o inhibir el ejercicio del\nderecho;\nXI.  Denegar intencionalmente información que no se encuentre clasificada como reservada o confidencial;\nXII.  Clasificar como reservada, con dolo o negligencia, la información sin que se cumplan las\ncaracterísticas señaladas en la presente Ley. La sanción procederá cuando exista una resolución\nprevia de las Autoridades garantes, que haya quedado firme;\nXIII.  No desclasificar la información como reservada cuando los motivos que le dieron origen ya no existan\no haya fenecido el plazo, cuando Autoridades garantes, determinen que existe una causa de interés\npúblico que persiste o no se solicite la prórroga al Comité de Transparencia;\nXIV.  No atender los requerimientos establecidos en la presente Ley, emitidos por las Autoridades garantes,\no\nXV.  No acatar las resoluciones emitidas por las Autoridades garantes, en ejercicio de sus funciones.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo II De las Sanciones","seccion_nombre":null,"id":"01e7c8c6-9dfd-4bfe-9b3a-b07082a42ecf","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":204},{"identificador":"Artículo 205","tipo_articulo":"ordinario","contenido":"Para determinar el monto de las multas y calificar las sanciones establecidas en el presente\nCapítulo, la Autoridad garante deberá considerar:\nI.  La gravedad de la falta del sujeto obligado, determinada por elementos tales como el daño causado,\nlos indicios de intencionalidad, la duración del incumplimiento de las determinaciones de las\nAutoridades garantes, y la afectación al ejercicio de sus atribuciones;\nII.  La condición económica de la persona infractora;\nIII.  La reincidencia, y\nIV.  En su caso, el cumplimiento espontáneo de las obligaciones que dieron origen al procedimiento\nsancionatorio, el cual podrá considerarse como atenuante de la sanción a imponerse.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo II De las Sanciones","seccion_nombre":null,"id":"60b53040-0dbd-4462-b59c-4cc59e9e40c4","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":205},{"identificador":"Artículo 206","tipo_articulo":"ordinario","contenido":"Con independencia del carácter de las personas presuntas infractoras, las Autoridades garantes\npara conocer, investigar, remitir documentación y, en su caso, sancionar, prescribirán en un plazo de cinco años a\npartir del día siguiente en que se hubieran cometido las infracciones o a partir del momento en que hubieren cesado,\nsi fueren de carácter continuo.\nLas sanciones de carácter económico no podrán ser cubiertas con recursos públicos.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo II De las Sanciones","seccion_nombre":null,"id":"e96ecd38-6651-4b8f-8fa8-341aa46c3abf","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":206},{"identificador":"Artículo 207","tipo_articulo":"ordinario","contenido":"Las conductas a que se refiere el artículo 204 serán sancionadas por las Autoridades garantes,\nsegún corresponda y, en su caso, conforme a su competencia darán vista a la autoridad competente para que\nimponga o ejecute la sanción.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo II De las Sanciones","seccion_nombre":null,"id":"0b1ff391-1d78-4392-bfab-f15986fb453f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":207},{"identificador":"Artículo 208","tipo_articulo":"ordinario","contenido":"Las responsabilidades que resulten de los procedimientos administrativos correspondientes\nderivados de la violación a lo dispuesto por el artículo 204 de esta Ley, son independientes de las del orden civil,\npenal o de cualquier otro tipo que se puedan derivar de los mismos hechos.\nDichas responsabilidades se determinarán, en forma autónoma, a través de los procedimientos previstos en las\nleyes aplicables y las sanciones que, en su caso, se impongan por las autoridades competentes, también se\nejecutarán de manera independiente.\nPara tales efectos, las Autoridades garantes podrán denunciar ante las autoridades competentes cualquier acto u\nomisión violatoria de esta Ley y aportar las pruebas que consideren pertinentes, en los términos de las leyes\naplicables.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo II De las Sanciones","seccion_nombre":null,"id":"78e31f0d-4565-4a45-927e-1285bde9af2e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":208},{"identificador":"Artículo 209","tipo_articulo":"ordinario","contenido":"Ante incumplimientos en materia de transparencia y acceso a la información por parte de los\npartidos políticos, las Autoridades garantes darán vista, según corresponda, al Instituto Nacional Electoral o a los\norganismos públicos locales electorales de las entidades federativas competentes, para que resuelvan lo\nconducente, sin perjuicio de las sanciones establecidas para los partidos políticos en las leyes aplicables.\nEn el caso de probables infracciones relacionadas con fideicomisos o fondos públicos, sindicatos o personas\nfísicas o morales que reciban y ejerzan recursos públicos o realicen actos de autoridad, las Autoridades garantes\ndeberán dar vista al órgano interno de control del sujeto obligado relacionado con estos, cuando sean personas\nservidoras públicas, con el fin de que instrumenten los procedimientos administrativos a que haya lugar.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo II De las Sanciones","seccion_nombre":null,"id":"59046737-40b0-48de-9a95-13f5a277da73","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":209},{"identificador":"Artículo 210","tipo_articulo":"ordinario","contenido":"En aquellos casos en que la persona presunta infractora tenga la calidad de persona servidora\npública, las Autoridades garantes deberán remitir a la autoridad competente, junto con la denuncia correspondiente,\nun expediente en que se contengan todos los elementos que sustenten la presunta responsabilidad administrativa.\nLa autoridad que conozca del asunto deberá informar de la conclusión del procedimiento y, en su caso, de la\nejecución de la sanción a la autoridad denunciante.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo II De las Sanciones","seccion_nombre":null,"id":"19e4c33d-8ccd-4ddd-bcda-c821f0face81","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":210},{"identificador":"Artículo 211","tipo_articulo":"ordinario","contenido":"Cuando se trate de personas presuntas infractoras que no cuenten con la calidad de personas\nservidoras públicas, las Autoridades garantes serán las autoridades facultadas para conocer y desahogar el\nprocedimiento sancionatorio conforme a esta Ley, y llevar a cabo las acciones conducentes para la imposición y\nejecución de las sanciones.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo II De las Sanciones","seccion_nombre":null,"id":"b55753b5-470c-486c-9b0e-5dadc5c41744","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":211},{"identificador":"Artículo 212","tipo_articulo":"ordinario","contenido":"El procedimiento a que se refiere el artículo anterior dará comienzo con la notificación que efectúe\nla Autoridad garante a la persona presunta infractora, sobre los hechos e imputaciones que motivaron el inicio del\nprocedimiento y le otorgará un término de quince días para que rinda pruebas y manifieste por escrito lo que a su\nderecho convenga. En caso de no hacerlo, la autoridad competente que conozca del procedimiento resolverá de\ninmediato con los elementos de convicción que disponga.\nLa Autoridad garante admitirá las pruebas que estime pertinentes y procederá a su desahogo. Una vez\ndesahogadas las pruebas, la Autoridad garante notificará a la persona presunta infractora el derecho que le asiste\npara que, de considerarlo necesario, presente sus alegatos dentro de los cinco días siguientes a su notificación.\nUna vez analizadas las pruebas y demás elementos de convicción, la Autoridad garante resolverá, en definitiva,\ndentro de los treinta días siguientes a la fecha en que inició el procedimiento sancionador. Dicha resolución deberá\nser notificada a la persona presunta infractora y, dentro de los diez días siguientes a la notificación, se hará pública la\nresolución correspondiente.\nCuando haya causa justificada debidamente fundada y motivada, la autoridad que conozca del asunto podrá\nampliar el plazo de resolución por una sola vez y hasta por un periodo igual.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo II De las Sanciones","seccion_nombre":null,"id":"905ec75f-860b-4a07-9a0b-1f282c8b0aa8","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":212},{"identificador":"Artículo 213","tipo_articulo":"ordinario","contenido":"En las normas respectivas de las Autoridades garantes se precisará toda circunstancia relativa a la\nforma, términos y cumplimiento de los plazos a que se refiere el procedimiento sancionatorio previsto en esta Ley,\nincluyendo la presentación de pruebas y alegatos, la celebración de audiencias, el cierre de instrucción y la ejecución\nde sanciones. En todo caso, será supletorio a este procedimiento sancionador lo dispuesto en las leyes en materia\nde procedimiento administrativo del orden jurídico que corresponda.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo II De las Sanciones","seccion_nombre":null,"id":"c2c574ea-6301-4873-afc6-43f4af05018e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":213},{"identificador":"Artículo 214","tipo_articulo":"ordinario","contenido":"Las infracciones a lo previsto en la presente Ley por parte de sujetos obligados que no cuenten con\nla calidad de persona servidora pública, serán sancionadas con:\nI.  Apercibimiento, por única ocasión, para que el sujeto obligado cumpla su obligación de manera\ninmediata, en los términos previstos en esta Ley, tratándose de los supuestos previstos en las\nfracciones I, III, V, VI y X del artículo 204 de esta Ley.\nSi una vez hecho el apercibimiento no se cumple de manera inmediata con la obligación en los\ntérminos previstos en esta Ley, tratándose de los supuestos mencionados en esta fracción, se aplicará\nmulta de ciento cincuenta a doscientos cincuenta veces el valor diario de la Unidad de Medida y\nActualización;\nII.  Multa de doscientos cincuenta a ochocientas veces el valor diario de la Unidad de Medida y\nActualización, en los casos previstos en las fracciones II y IV del artículo 204 de esta Ley, y\nIII.  Multa de ochocientos a mil quinientas veces el valor diario de la Unidad de Medida y Actualización, en\nlos casos previstos en las fracciones VII, VIII, IX, XI, XII, XIII, XIV y XV del artículo 204 de esta Ley.\nSe aplicará multa adicional de hasta cincuenta veces el valor diario de la Unidad de Medida y Actualización, por\ndía, a quien persista en las infracciones citadas en los incisos anteriores.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo II De las Sanciones","seccion_nombre":null,"id":"412f1184-8da6-4d74-aa58-9a09a1597439","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":214},{"identificador":"Artículo 215","tipo_articulo":"ordinario","contenido":"En caso de que el incumplimiento de las determinaciones de las Autoridades garantes implique la\npresunta comisión de un delito, estos deberán denunciar los hechos ante la autoridad competente.","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo II De las Sanciones","seccion_nombre":null,"id":"98491028-bcc8-4403-98e6-27d1b06d1c00","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":215},{"identificador":"Artículo 216","tipo_articulo":"ordinario","contenido":"Las personas físicas o morales que reciban y ejerzan recursos públicos o ejerzan actos de\nautoridad deberán proporcionar la información que permita al sujeto obligado que corresponda, cumplir con sus\nobligaciones de transparencia y para atender las solicitudes de acceso correspondientes.\nArtículo Segundo a Artículo Cuarto.-  …….","titulo_nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","capitulo_nombre":"Capítulo II De las Sanciones","seccion_nombre":null,"id":"8cf20cf8-73ca-4cb4-bca4-876d5ca59766","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":216},{"identificador":"Transitorio Primero","tipo_articulo":"transitorio","contenido":"El presente Decreto entrará en vigor al día siguiente de su publicación en el Diario Oficial de la\nFederación, con excepción de lo previsto en el transitorio Tercero de este instrumento.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"c8298e4a-12a8-49a7-b670-f338feb59def","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":217},{"identificador":"Transitorio Segundo","tipo_articulo":"transitorio","contenido":"A la entrada en vigor del presente Decreto se abrogan las disposiciones siguientes:\nI.  La Ley Federal de Protección de Datos Personales en Posesión de los Particulares, publicada en el\nDiario Oficial de la Federación el 5 de julio de 2010;\nII.  La Ley General de Transparencia y Acceso a la Información Pública, publicada en el Diario Oficial de\nla Federación el 4 de mayo de 2015 y sus modificaciones posteriores;\nIII.  La Ley Federal de Transparencia y Acceso a la Información Pública, publicada en el Diario Oficial de la\nFederación el 9 de mayo de 2016 y sus modificaciones posteriores;\nIV.  La Ley General de Protección de Datos Personales en Posesión de Sujetos Obligados, publicada en el\nDiario Oficial de la Federación el 26 de enero de 2017, y\nV.  El Acuerdo mediante el cual se aprueba el Programa Anual de Verificación y Acompañamiento\nInstitucional para el cumplimiento de las obligaciones en materia de acceso a la información y\ntransparencia por parte de los sujetos obligados del ámbito federal, correspondiente al ejercicio 2025,\npublicado en el Diario Oficial de la Federación el 21 de enero de 2025.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"468d8f0e-355e-4c33-a3e2-adf6ffb3ec4e","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":218},{"identificador":"Transitorio Tercero","tipo_articulo":"transitorio","contenido":"Los artículos 71 y 72 de la Ley General de Transparencia y Acceso a la Información Pública entrarán\nen vigor cuando se extingan la Comisión Federal de Competencia Económica y el Instituto Federal de\nTelecomunicaciones conforme a lo previsto en los transitorios Décimo y Décimo Primero del “Decreto por el que se\nreforman, adicionan y derogan diversas disposiciones de la Constitución Política de los Estados Unidos Mexicanos,\nen materia de simplificación orgánica”, publicado en el Diario Oficial de la Federación el 20 de diciembre de 2024.\nPara efectos del párrafo anterior, la Comisión Federal de Competencia Económica y el Instituto Federal de\nTelecomunicaciones deberán poner a disposición del público y actualizar la información a que se refiere el artículo\n72, fracciones II y V, respectivamente, de la Ley Federal de Transparencia y Acceso a la Información Pública que se\nabroga por virtud del presente Decreto.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"5679e235-6e9e-4676-945e-5c0c8a942aa5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":219},{"identificador":"Transitorio Cuarto","tipo_articulo":"transitorio","contenido":"Las menciones, atribuciones o funciones contenidas en otras leyes, reglamentos y, en general, en\ncualquier disposición normativa, respecto al Instituto Nacional de Transparencia, Acceso a la Información y\nProtección de Datos Personales se entenderán hechas o conferidas a los entes públicos que adquieren tales\natribuciones o funciones, según corresponda.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"6cbde3f7-fe92-45cc-bc19-ffef59dbbcb5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":220},{"identificador":"Transitorio Quinto","tipo_articulo":"transitorio","contenido":"Los derechos laborales de las personas servidoras públicas del Instituto Nacional de Transparencia,\nAcceso a la Información y Protección de Datos Personales, serán respetados, en términos de la legislación aplicable.\nLos recursos humanos con que cuente el referido Instituto pasarán a formar parte de la Secretaría Anticorrupción y\nBuen Gobierno y Transparencia para el Pueblo.\nEl Instituto Nacional de Transparencia, Acceso a la Información y Protección de Datos Personales transferirá los\nrecursos correspondientes al valor del inventario o plantilla de plazas a la Secretaría de Hacienda y Crédito Público,\ndentro de los veinte días hábiles siguientes contados a partir de la entrada en vigor del presente Decreto, a fin de que\nesa dependencia realice las acciones que correspondan, conforme a las disposiciones jurídicas aplicables.\nLas personas servidoras públicas del Instituto Nacional de Transparencia, Acceso a la Información y Protección\nde Datos Personales que dejen de prestar sus servicios en el mencionado Instituto y que estén obligadas a presentar\ndeclaración patrimonial y de intereses, de conformidad con las disposiciones jurídicas aplicables, lo realizarán en los\nsistemas de la Secretaría Anticorrupción y Buen Gobierno habilitados para tales efectos o en los medios que esta\ndetermine y conforme a la normativa aplicable a la Administración Pública Federal. Lo anterior también es aplicable a\nlas personas que se hayan desempeñado como servidoras públicas en el mencionado Instituto y que a la fecha de\nentrada en vigor del presente Decreto aún tengan pendiente cumplir con dicha obligación.\nLas personas que dentro de los diez días previos a la entrada en vigor del presente Decreto se hayan\ndesempeñado como personas servidoras públicas del Instituto Nacional de Transparencia, Acceso a la Información y\nProtección de Datos Personales, incluyendo a las personas Comisionadas, deben presentar acta administrativa de\nentrega-recepción institucional e individual, según corresponda, a la persona servidora pública que la Secretaría\nAnticorrupción y Buen Gobierno designe y conforme a la normativa aplicable a la Administración Pública Federal, en\nlos sistemas de la referida dependencia habilitados para tales efectos o en los medios que ésta determine, en el\nentendido que la entrega que se realice no implica liberación alguna de responsabilidades que pudieran llegarse a\ndeterminar por la autoridad competente con posterioridad.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"5c4d4813-0952-43e4-95c0-bfa64f2bcc78","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":221},{"identificador":"Transitorio Sexto","tipo_articulo":"transitorio","contenido":"Los recursos materiales con que cuente el Instituto Nacional de Transparencia, Acceso a la Información y\nProtección de Datos Personales serán transferidos a la Secretaría Anticorrupción y Buen Gobierno, dentro de los\nveinte días hábiles siguientes a la entrada en vigor del presente Decreto.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"2c0fc9d6-901d-4a1d-bb5d-6f849c5fb094","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":222},{"identificador":"Transitorio Séptimo","tipo_articulo":"transitorio","contenido":"El Instituto Nacional de Transparencia, Acceso a la Información y Protección de Datos Personales\ntransferirá los recursos financieros a la Secretaría de Hacienda y Crédito Público, de conformidad con las\ndisposiciones jurídicas aplicables.\nAsimismo, el Instituto Nacional de Transparencia, Acceso a la Información y Protección de Datos Personales\ndeberá entregar a la citada dependencia la información y formatos necesarios para integrar la Cuenta Pública y\ndemás informes correspondientes al primer trimestre, de conformidad con las disposiciones jurídicas aplicables,\ndentro de los diez días hábiles siguientes a la entrada en vigor del presente Decreto.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"b2b7e9e3-13cc-47c9-a243-586269c3bb41","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":223},{"identificador":"Transitorio Octavo","tipo_articulo":"transitorio","contenido":"Los registros, padrones y sistemas, internos y externos, que integran la Plataforma Nacional de\nTransparencia con los que cuenta el Instituto Nacional de Transparencia, Acceso a la Información y Protección de\nDatos Personales, así como los sistemas informáticos utilizados por dicho Instituto, incluso los que ya no se utilicen\npero contengan registros históricos, incluida su documentación y titularidad, serán transferidos a la Secretaría\nAnticorrupción y Buen Gobierno dentro de los quince días hábiles siguientes a la entrada en vigor del presente\nDecreto.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"bf7f92e1-6d46-41c9-8804-78977e3cfc98","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":224},{"identificador":"Transitorio Noveno","tipo_articulo":"transitorio","contenido":"Los procedimientos iniciados con anterioridad a la entrada en vigor de este Decreto ante el Instituto\nNacional de Transparencia, Acceso a la Información y Protección de Datos Personales, en materia de acceso a la\ninformación pública, se sustanciarán ante Transparencia para el Pueblo conforme a las disposiciones aplicables\nvigentes al momento de su inicio.\nLa defensa legal ante autoridades administrativas, jurisdiccionales y judiciales de los actos administrativos y\njurídicos emitidos por el Instituto Nacional de Transparencia, Acceso a la Información y Protección de Datos\nPersonales, en materia de acceso a la información pública, se llevará a cabo por Transparencia para el Pueblo.\nTransparencia para el Pueblo podrá remitir a la Autoridad garante competente aquellos asuntos que se\nmencionan en los párrafos anteriores que le corresponda conforme al ámbito de sus atribuciones para su atención.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"8c638c66-4740-4154-96b4-eb7274dc69d6","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":225},{"identificador":"Transitorio Décimo","tipo_articulo":"transitorio","contenido":"Los procedimientos iniciados con anterioridad a la entrada en vigor de este Decreto ante el Instituto\nNacional de Transparencia, Acceso a la Información y Protección de Datos Personales, en materia de datos\npersonales o cualquier otra distinta a la mencionada en el transitorio anterior, se sustanciarán conforme a las\ndisposiciones vigentes al momento de su inicio ante la Secretaría Anticorrupción y Buen Gobierno a que se refiere\neste Decreto.\nLa defensa legal ante autoridades administrativas, jurisdiccionales o judiciales de los actos administrativos y\njurídicos emitidos por el Instituto Nacional de Transparencia, Acceso a la Información y Protección de Datos\nPersonales, en materia de datos personales o cualquier otra distinta a la mencionada en el transitorio anterior, así\ncomo el seguimiento de los que se encuentren en trámite, incluso los procedimientos penales y laborales, se llevará\na cabo por la Secretaría Anticorrupción y Buen Gobierno.\nLa Secretaría Anticorrupción y Buen Gobierno podrá remitir a la Autoridad garante competente aquellos asuntos\nque se mencionan en los párrafos anteriores que le corresponda conforme al ámbito de sus atribuciones para su\natención.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"593efe8c-0d80-46e0-8523-d7a1179ecc9c","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":226},{"identificador":"Transitorio Décimo Primero","tipo_articulo":"transitorio","contenido":"Los municipios podrán cumplir con las obligaciones a su cargo en materia de transparencia y\nacceso a la información, en términos de lo previsto en el transitorio Décimo de la Ley General de Transparencia y\nAcceso a la Información Pública que se abroga por virtud de este Decreto.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"252b71d8-5f9c-4e07-bc78-26fac9fd53d1","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":227},{"identificador":"Transitorio Décimo Segundo","tipo_articulo":"transitorio","contenido":"La persona titular del Ejecutivo Federal deberá expedir las adecuaciones correspondientes a\nlos reglamentos y demás disposiciones aplicables, incluida la emisión del Reglamento Interior de Transparencia para\nel Pueblo, dentro de los noventa días naturales siguientes a la entrada en vigor del presente Decreto, a fin de\narmonizarlos a lo previsto en el mismo.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"9198e281-5235-4d1f-9478-aab24cc68160","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":228},{"identificador":"Transitorio Décimo Tercero","tipo_articulo":"transitorio","contenido":"Los expedientes y archivos que a la entrada en vigor del presente Decreto estén a cargo del\nInstituto Nacional de Transparencia, Acceso a la Información y Protección de Datos Personales para el ejercicio de\nsus facultades sustantivas, competencias o funciones, de conformidad con la Ley General de Archivos y demás\ndisposiciones jurídicas aplicables, serán transferidos a la Secretaría Anticorrupción y Buen Gobierno dentro de los\nveinte días hábiles siguientes a la entrada en vigor del presente Decreto.\nLa Secretaría Anticorrupción y Buen Gobierno, dentro de los treinta días naturales siguientes contados a partir de\nque se reciban los expedientes y archivos que se mencionan en el párrafo anterior, podrá transferirlos a la autoridad\ncorrespondiente.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"5bda8869-09e0-4707-8813-3a1ec550723f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":229},{"identificador":"Transitorio Décimo Cuarto","tipo_articulo":"transitorio","contenido":"El Órgano Interno de Control del Instituto Nacional de Transparencia, Acceso a la Información y\nProtección de Datos Personales queda extinto y sus asuntos y procedimientos que a la entrada en vigor del presente\nDecreto estén a su cargo, así como los expedientes y archivos, serán transferidos al Órgano Interno de Control de la\nSecretaría Anticorrupción y Buen Gobierno dentro de los veinte días hábiles siguientes a su entrada en vigor, y serán\ntramitados y resueltos por dicho órgano conforme a las disposiciones jurídicas vigentes al momento de su inicio.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"4bcf91fb-ff03-499f-9fb1-605e4d04e8b3","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":230},{"identificador":"Transitorio Décimo Quinto","tipo_articulo":"transitorio","contenido":"Para efectos de lo dispuesto en los transitorios Quinto, Sexto, Séptimo, Octavo y Décimo\nTercero del presente Decreto el Pleno del Instituto Nacional de Transparencia, Acceso a la Información y Protección\nde Datos Personales deberá integrar, en la fecha de publicación de este instrumento, un Comité de Transferencia\nconformado por los Comisionados del mencionado Instituto y once personas servidoras públicas del mismo con al\nmenos el nivel de Dirección de área o equivalente, que tengan conocimiento o que se encuentren a su cargo los\nasuntos que se mencionan en los propios transitorios.\nEl Comité de Transferencia estará vigente por un periodo de 30 días naturales, en el que sus integrantes\nparticiparán con las diversas autoridades competentes para recibir los asuntos que se señalan en los transitorios\nantes citados y realizar las demás acciones que se consideren necesarias para dichos efectos.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"ef6d3e97-6ad6-44e8-b657-52f4c54318e2","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":231},{"identificador":"Transitorio Décimo Sexto","tipo_articulo":"transitorio","contenido":"El Consejo del Sistema Nacional de Acceso a la Información Pública deberá instalarse a más\ntardar en sesenta días naturales, a partir de la entrada en vigor del presente Decreto, previa convocatoria que al\nefecto emita la Secretaría Anticorrupción y Buen Gobierno.\nHasta en tanto las legislaturas de las entidades federativas que correspondan armonizan su marco jurídico en\nmateria de acceso a la información pública en términos de lo previsto en el transitorio Cuarto del Decreto por el que\nse reforman, adicionan y derogan diversas disposiciones de la Constitución Política de los Estados Unidos\nMexicanos, en materia de simplificación orgánica, publicado en el Diario Oficial de la Federación el 20 de diciembre\nde 2024, la persona titular del poder ejecutivo local de que se trate será integrante del Consejo del Sistema Nacional\nde Acceso a la Información Pública.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"bbce4d22-15fc-4afb-8544-38b3d00c865f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":232},{"identificador":"Transitorio Décimo Séptimo","tipo_articulo":"transitorio","contenido":"La persona titular de la Secretaría Ejecutiva del Consejo del Sistema Nacional de Acceso a la\nInformación Pública propondrá las reglas de operación y funcionamiento que se señalan en el artículo 25, fracción\nXV, de la Ley General de Transparencia y Acceso a la Información Pública, para que sean aprobadas en la\ninstalación de dicho Consejo.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"aeb089ab-04ef-4c9c-860e-ce2cbf77c947","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":233},{"identificador":"Transitorio Décimo Octavo","tipo_articulo":"transitorio","contenido":"El órgano de control y disciplina del Poder Judicial; los órganos internos de control de los\nórganos constitucionales autónomos; las contralorías internas del Congreso de la Unión; el Instituto Nacional\nElectoral; el Centro Federal de Conciliación y Registro Laboral y el Tribunal Federal de Conciliación y Arbitraje en un\nplazo máximo de treinta días naturales contados a partir de la entrada en vigor del presente Decreto deberán realizar\nlas adecuaciones necesarias a su normativa interna para dar cumplimiento a lo dispuesto en este instrumento.\nPara efectos de lo previsto en este transitorio, se suspenden por un plazo de noventa días naturales contados a\npartir de la entrada en vigor de este Decreto todos y cada uno de los trámites, procedimientos y demás medios de\nimpugnación, establecidos en este instrumento y demás normativa aplicable, con excepción de la recepción y\natención de las solicitudes de información que se tramitan a través de la Plataforma Nacional de Transparencia por\nlas autoridades que se mencionan en el párrafo anterior.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"3c626412-3bcb-452d-a6bb-a5b6788060ef","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":234},{"identificador":"Transitorio Décimo Noveno","tipo_articulo":"transitorio","contenido":"Hasta en tanto las legislaturas de las entidades federativas, emitan legislación para armonizar\nsu marco jurídico conforme al presente Decreto, los organismos garantes de las mismas continuarán operando y\nrealizarán las atribuciones que le son conferidas a las Autoridades garantes locales, así como a los órganos\nencargados de la contraloría interna u homólogos de los poderes legislativo y judicial, así como los órganos\nconstitucionales autónomos de las propias entidades federativas en la presente Ley.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"88e2a81e-a10a-4a97-99de-3941abccdd7f","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":235},{"identificador":"Transitorio Vigésimo","tipo_articulo":"transitorio","contenido":"El Poder Judicial de la Federación deberá habilitar juzgados de Distrito y tribunales Colegiados de\nCircuito especializados en materia de acceso a la información pública y protección de datos personales, en un plazo\nno mayor a ciento veinte días naturales contados a partir de la entrada en vigor del presente Decreto, a los cuales se\nremitirán los juicios de amparo en dichas materias que se encuentran en trámite para su resolución.\nPara efectos de lo previsto en este transitorio, se suspenden por un plazo de ciento ochenta días naturales\ncontados a partir de la entrada en vigor de este Decreto los plazos y términos procesales de los juicios de amparo en\nmateria de acceso a la información pública y protección de datos personales que se encuentran en trámite ante\njuzgados de Distrito y tribunales Colegiados de Circuito.","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"f10bb70f-0076-48ef-85e3-7f88d6b60ad5","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":236},{"identificador":"Firmas y promulgación","tipo_articulo":"complementario","contenido":"Ciudad de México, a 20 de marzo de 2025.- Sen. Imelda Castro Castro, Vicepresidenta.- Dip. Sergio Carlos\nGutiérrez Luna, Presidente.- Sen. Verónica Noemí Camino Farjat, Secretaria.- Dip. José Luis Montalvo Luna,\nSecretario.- Rúbricas. \"\nEn cumplimiento de lo dispuesto por la fracción I del Artículo 89 de la Constitución Política de los Estados Unidos\nMexicanos, y para su debida publicación y observancia, expido el presente Decreto en la Residencia del Poder\nEjecutivo Federal, en la Ciudad de México, a 20 de marzo de 2025.-  Claudia Sheinbaum Pardo , Presidenta de los\nEstados Unidos Mexicanos.- Rúbrica.- Lcda.  Rosa Icela Rodríguez Velázquez , Secretaria de Gobernación.-\nRúbrica.","titulo_nombre":"Documentos complementarios","capitulo_nombre":null,"seccion_nombre":null,"id":"76a754ac-f657-5a89-82f0-475075494e93","ley_id":"e7297529-d3df-4e69-8c01-d3d6d70e3e55","orden":237}],"remove":["d574ce36-1a91-48f5-8bfd-0ce28b0e8103"],"themes_before":[],"themes_after":[{"nivel":"titulo","nombre":"TÍTULO PRIMERO DISPOSICIONES GENERALES","orden":0},{"nivel":"capitulo","nombre":"Capítulo I Disposiciones Preliminares","orden":1},{"nivel":"capitulo","nombre":"Capítulo II De los Principios Generales","orden":2},{"nivel":"seccion","nombre":"Sección Primera De los principios rectores de las Autoridades garantes","orden":3},{"nivel":"seccion","nombre":"Sección Segunda De los Principios en Materia de Transparencia y Acceso a la Información Pública","orden":4},{"nivel":"capitulo","nombre":"Capítulo III De los Sujetos Obligados","orden":5},{"nivel":"titulo","nombre":"TÍTULO SEGUNDO RESPONSABLES EN MATERIA DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN","orden":6},{"nivel":"capitulo","nombre":"Capítulo I Del Sistema Nacional","orden":7},{"nivel":"capitulo","nombre":"Capítulo II Del Consejo Nacional","orden":8},{"nivel":"capitulo","nombre":"Capítulo III De los Subsistemas de Transparencia","orden":9},{"nivel":"capitulo","nombre":"Capítulo IV De las Autoridades garantes","orden":10},{"nivel":"capitulo","nombre":"Capítulo V De los Comités de Transparencia","orden":11},{"nivel":"capitulo","nombre":"Capítulo VI De las Unidades de Transparencia","orden":12},{"nivel":"titulo","nombre":"TÍTULO TERCERO PLATAFORMA NACIONAL DE TRANSPARENCIA","orden":13},{"nivel":"capitulo","nombre":"Capítulo Único De la Plataforma Nacional de Transparencia","orden":14},{"nivel":"titulo","nombre":"TÍTULO CUARTO CULTURA DE TRANSPARENCIA Y APERTURA INSTITUCIONAL","orden":15},{"nivel":"capitulo","nombre":"Capítulo I De la Promoción de la Transparencia y el Derecho de Acceso a la Información","orden":16},{"nivel":"capitulo","nombre":"Capítulo II De la Transparencia con Sentido Social","orden":17},{"nivel":"capitulo","nombre":"Capítulo III De la Apertura Institucional","orden":18},{"nivel":"titulo","nombre":"TÍTULO QUINTO OBLIGACIONES DE TRANSPARENCIA","orden":19},{"nivel":"capitulo","nombre":"Capítulo I De las Obligaciones Generales","orden":20},{"nivel":"capitulo","nombre":"Capítulo II De las Obligaciones de Transparencia Comunes","orden":21},{"nivel":"capitulo","nombre":"Capítulo III De las Obligaciones Específicas","orden":22},{"nivel":"capitulo","nombre":"Capítulo IV De las Obligaciones Específicas de las Personas Físicas o Morales que Reciben y Ejercen Recursos Públicos o Ejercen Actos de Autoridad","orden":23},{"nivel":"capitulo","nombre":"Capítulo V De las Obligaciones Específicas en Materia Energética","orden":24},{"nivel":"capitulo","nombre":"Capítulo VI De la Verificación de las Obligaciones de Transparencia","orden":25},{"nivel":"capitulo","nombre":"Capítulo VII De la Denuncia por Incumplimiento a las Obligaciones de Transparencia","orden":26},{"nivel":"titulo","nombre":"TÍTULO SEXTO INFORMACIÓN CLASIFICADA","orden":27},{"nivel":"capitulo","nombre":"Capítulo I De las Disposiciones Generales de la Clasificación y Desclasificación de la Información","orden":28},{"nivel":"capitulo","nombre":"Capítulo II De la Información Reservada","orden":29},{"nivel":"capitulo","nombre":"Capítulo III De la Información Confidencial","orden":30},{"nivel":"capitulo","nombre":"Capítulo IV De las Versiones Públicas","orden":31},{"nivel":"titulo","nombre":"TÍTULO SÉPTIMO PROCEDIMIENTOS DE ACCESO A LA INFORMACIÓN PÚBLICA","orden":32},{"nivel":"capitulo","nombre":"Capítulo I Del Procedimiento de Acceso a la Información","orden":33},{"nivel":"capitulo","nombre":"Capítulo II De las Cuotas de Acceso","orden":34},{"nivel":"titulo","nombre":"TÍTULO OCTAVO DE LOS PROCEDIMIENTOS DE IMPUGNACIÓN","orden":35},{"nivel":"capitulo","nombre":"Capítulo I Del Recurso de Revisión","orden":36},{"nivel":"capitulo","nombre":"Capítulo II Del Recurso de Inconformidad","orden":37},{"nivel":"capitulo","nombre":"Capítulo III Del Recurso de Revisión en Materia de Seguridad Nacional","orden":38},{"nivel":"capitulo","nombre":"Capítulo IV Del Recurso de Revisión de Asuntos Jurisdiccionales de la Suprema Corte de Justicia de la Nación","orden":39},{"nivel":"capitulo","nombre":"Capítulo V Del Cumplimiento de las Resoluciones","orden":40},{"nivel":"capitulo","nombre":"Capítulo VI De los Criterios de Interpretación","orden":41},{"nivel":"titulo","nombre":"TÍTULO NOVENO MEDIDAS DE APREMIO Y SANCIONES","orden":42},{"nivel":"capitulo","nombre":"Capítulo I De las Medidas de Apremio","orden":43},{"nivel":"capitulo","nombre":"Capítulo II De las Sanciones","orden":44}],"date_before":"2025-03-20","date_after":"2025-03-20"}$payload$::jsonb; lid uuid; n integer;
BEGIN
 lid := (p->>'ley_id')::uuid;
 LOCK TABLE public.articulos, public.temas, public.user_favorites, public.user_notes IN SHARE ROW EXCLUSIVE MODE;
 PERFORM 1 FROM public.leyes WHERE id=lid FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM public.leyes WHERE id=lid AND fecha_publicacion=(p->>'date_before')::date) THEN RAISE EXCEPTION 'Cambió la fecha o el instrumento'; END IF;
 SELECT count(*) INTO n FROM public.articulos WHERE ley_id=lid;
 IF n<>jsonb_array_length(p->'before') THEN RAISE EXCEPTION 'Cambió el conteo antes de aplicar'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'before') b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR md5(a.contenido) IS DISTINCT FROM b->>'contenido_md5' OR (to_jsonb(a)-'contenido'-'fts'-'created_at') IS DISTINCT FROM (b-'contenido_md5')) THEN RAISE EXCEPTION 'El respaldo ya no coincide con los artículos'; END IF;
 IF (SELECT count(*) FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'themes_before') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'themes_before') b WHERE NOT EXISTS(SELECT 1 FROM public.temas t WHERE t.ley_id=lid AND (to_jsonb(t)-'created_at')=b)) THEN RAISE EXCEPTION 'Cambió el índice de temas'; END IF;
 IF EXISTS(SELECT 1 FROM public.user_favorites f WHERE f.articulo_id IN(SELECT jsonb_array_elements_text(p->'remove'))) OR EXISTS(SELECT 1 FROM public.user_notes f WHERE f.articulo_id IN(SELECT jsonb_array_elements_text(p->'remove'))) THEN RAISE EXCEPTION 'Hay referencias nuevas a fragmentos que se unirán: revisar traslado'; END IF;
 INSERT INTO public.articulos(id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden)
 SELECT id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden FROM jsonb_populate_recordset(null::public.articulos,p->'after')
 ON CONFLICT(id) DO UPDATE SET identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre,orden=excluded.orden;
 DELETE FROM public.articulos WHERE ley_id=lid AND id IN(SELECT jsonb_array_elements_text(p->'remove')::uuid);
 DELETE FROM public.temas WHERE ley_id=lid;
 insert into public.temas(ley_id,nivel,nombre,orden) select lid,t->>'nivel',t->>'nombre',(t->>'orden')::int from jsonb_array_elements(p->'themes_after') t;
 UPDATE public.leyes SET fecha_publicacion=(p->>'date_after')::date WHERE id=lid;
 
 IF (SELECT count(*) FROM public.articulos WHERE ley_id=lid)<>jsonb_array_length(p->'after') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'after') b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR (to_jsonb(a)-'fts'-'created_at') IS DISTINCT FROM b) THEN RAISE EXCEPTION 'La comprobación posterior de artículos falló'; END IF;
 IF EXISTS(SELECT 1 FROM public.articulos WHERE ley_id=lid AND (nullif(trim(contenido),'') IS NULL OR fts IS NULL OR fts=''::tsvector)) THEN RAISE EXCEPTION 'Texto o FTS vacío'; END IF;
 IF (SELECT count(*) FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'themes_after') THEN RAISE EXCEPTION 'Índice incompleto'; END IF;
END $repair$;
COMMIT;
SELECT l.siglas,l.id,(SELECT count(*) FROM public.articulos a WHERE a.ley_id=l.id) AS fragmentos,(SELECT count(*) FROM public.temas t WHERE t.ley_id=l.id) AS temas,l.fecha_publicacion FROM public.leyes l WHERE l.id='e7297529-d3df-4e69-8c01-d3d6d70e3e55';
